INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C1','kor',6,2,'u4',1,'낱말의 세 갈래 — 고유어는 우리말에 처음부터 있던 낱말이나 그것을 바탕으로 만들어진 낱말, 한자어는 한자로 이루어진 낱말, 외래어는 다른 나라에서 들어와 우리 생활에서 널리 쓰이는 낱말이며, 세 갈래가 어울려 우리말을 이룬다',ARRAY['[6국04-03]']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C2','kor',6,2,'u4',1,'우리말을 바르게 쓴다는 것 — 고유어만 쓰거나 한자어·외래어를 몰아내는 것이 아니라, 듣는 사람이 알아들을 수 있게, 낱말의 뜻에 맞게, 바꿀 수 있는 말은 쉬운 우리말로 바꾸어 쓰고, 누구에게 어디에서 말하느냐에 따라 상황에 맞게 골라 쓰는 것',ARRAY['[6국04-03]']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C3','kor',6,2,'u4',1,'말이 잘 통하지 않을 때 — 지나치게 줄인 말(아는 사람끼리만 통함)·뜻을 알기 어려운 새말(뜻이 서로 다르게 통함)·기분을 상하게 하는 말(뜻은 통해도 마음이 다침)·굳이 어렵게 쓴 외국어(쉬운 우리말을 두고 알아듣기 어려움)는 되묻기·대화에서 밀려나기·다툼을 낳는다',ARRAY['[6국04-03]']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C4','kor',6,2,'u4',2,'국어사전으로 갈래 가리기 — 낱말 뒤에 아무것도 붙지 않고 한글 표기만 있으면 고유어, 한자가 함께 있으면 한자어, 영어 등의 외국어가 함께 있으면 외래어이며, 헷갈리는 낱말은 소리나 모양으로 짐작하지 말고 사전에서 확인한다(종이 사전·스마트 기기 사전 모두 같은 방법)',ARRAY['[6국04-03]']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C5','kor',6,2,'u4',2,'고유어의 두 모습과 가치 — 고유어는 처음부터 있던 낱말(이슬·호미)과 그것을 바탕으로 만들어진 낱말(나들이·마중물)이 있어 지금도 새로 만들어질 수 있고, 우리말의 기본 바탕을 이루며, 뜻을 쉽게 짐작할 수 있고 느낌을 살려 표현할 수 있고(싱긋·껄껄) 우리 문화와 정서를 담는다',ARRAY['[6국04-03]']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C6','kor',6,2,'u4',2,'갈래에 등수 없음 · 다듬은 말 — 세 갈래는 하는 일이 다를 뿐 좋고 나쁨이 없으며, 쉬운 우리말이 있는데도 굳이 어렵게 쓴 말은 다듬고(노견→갓길·익일→다음 날·회람→돌려보기·다운로드→내려받기) 바꿀 말이 마땅치 않거나 바꾸면 오히려 통하지 않는 말(컴퓨터·버스·학교·수학)은 그대로 쓴다 — 다듬기의 목적은 몰아내기가 아니라 누구나 알아듣게 하기',ARRAY['[6국04-03]']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C7','kor',6,2,'u4',2,'고유어로 이루어진 관용 표현 — 둘 이상의 낱말이 어울려 새로운 뜻을 만드는 표현(손이 크다=씀씀이가 넉넉하다 · 입이 짧다=음식을 심하게 가리거나 적게 먹다 · 낯을 가리다=낯선 사람을 어려워하다)으로, 낱말 뜻을 하나씩 더해서는 뜻이 나오지 않으며 우리 문화와 정서를 담는다',ARRAY['[6국04-03]']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C8','kor',6,2,'u4',4,'고유어를 활용한 사례 찾기 — 동네·길·가게·음식 이름에는 고유어를 살려 지은 것이 많으며(너른들·나루터길·새참·수제비), 여러 낱말로 이루어진 이름은 낱말을 나누어(나루터 + 길) 그 낱말이 고유어인지 사전에서 확인한다',ARRAY['[6국04-03]']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C9','kor',6,2,'u4',4,'조사 계획과 정리 · 확인과 짐작 가르기 — 조사 대상·범위(손이 닿는 곳으로 좁게)·방법(국어사전·믿을 만한 누리집·어른께 여쭙기)을 먼저 정하고, 유형·사례·고유어·고유어의 뜻 네 칸으로 정리하며, 사전에서 찾은 것·짐작한 것·아직 확인하지 못한 것을 갈라 말하고 지어내지 않는다',ARRAY['[6국04-03]']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C10','kor',6,2,'u4',4,'매체를 활용한 발표와 듣기 — 알릴 내용을 정한 뒤 그에 맞는 매체(사진·그림·지도·표·종이 자료)를 고르고, 출처가 믿을 만한가·양이 시간에 알맞은가·매체가 도움이 되는가를 점검하며, 발표하는 사람은 유형·사례·뜻을 차례대로 말하고 출처를 밝히고, 듣는 사람은 정리하며 듣고 궁금한 점을 까닭과 함께 묻는다(묻고 답하기까지가 발표)',ARRAY['[6국04-03]']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C11','kor',6,2,'u4',6,'우리말을 지키기 위한 노력 — 말은 저절로 남지 않으며, 우리말을 마음껏 쓰지 못하던 때에도 흩어진 낱말과 고장마다 다른 말까지 모아 우리말 사전을 만들려던 사람들이 있었고 그 기록이 오늘 국어사전의 바탕이 되었다 — 사전에서 확인하기·쉬운 말로 바꾸기·고장 말을 여쭈어 적기·다른 고장 말을 웃음거리로 삼지 않기도 지키는 일',ARRAY['[6국02-02][6국04-02]']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C12','kor',6,2,'u4',6,'생략된 내용 추론하며 읽기 — 글쓴이가 적지 않은 부분을 글의 단서(인물의 말과 행동·때와 곳·되풀이되거나 눈에 띄는 부분)와 내가 가진 경험·지식으로 메우는 일이며, 까닭은 반드시 글 안에 있어야 하고(마음대로 상상하기와 다름), 글에 적힌 것과 추론한 것을 가르고, 처음 보는 낱말은 앞뒤 문맥으로 뜻을 짐작한다',ARRAY['[6국02-02]']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C13','kor',6,2,'u4',6,'표준어와 방언 — 표준어는 온 나라 사람이 두루 통하게 쓰도록 정한 말로 사는 곳이 달라도 서로 통하게 해 주고, 방언은 어느 고장에서 주로 쓰는 표준어가 아닌 말로 그 고장의 정과 역사를 담아 전하며(부엌-정지 · 무-무시 · 김치-짐치), 둘 사이에 등수는 없고 공식적인 자리에서는 표준어로, 고장 사람과는 고장 말로 상황에 맞게 쓴다',ARRAY['[6국04-02]']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C14','kor',6,2,'u4',8,'언어생활 점검하기 — 여러 사람에게 전하는 글일수록 누구나 알아듣게 써야 하며, 굳이 외국어로 쓴 말·지나치게 줄인 말·기분을 상하게 하는 말·즐겨 쓰는 고유어를 스스로 표시해 우리 반의 실태로 정리하고, 점검은 친구를 흠잡는 일이 아니라 먼저 내가 쓴 말부터 적고 함께 고치려는 일이다',ARRAY['[6국04-02][6국04-03]']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C15','kor',6,2,'u4',8,'실천 다짐문 쓰기와 고쳐 쓰기 — 목적·구체적인 실천 약속(언제·어디에서·무엇을)·전하고 싶은 말·날짜와 쓴 사람 네 부분을 갖추고, 크게 말하는 다짐보다 지킬 수 있는 다짐을 쓰며, 친구 다짐문은 잘 쓴 부분 먼저·고칠 점은 내용에서·바꾸어 볼 문장과 함께 말하고, 나누고 실천한 뒤 되돌아본다',ARRAY['[6국04-02][6국04-03]']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C16','kor',6,2,'u4',11,'우리말 지킴이 활동 — 알릴 내용에 맞는 방법(알림 영상·인쇄물·만화·우리말 일기·지킴이 도전)을 고르고, 주제·내용·역할·시간을 정해 계획하며, 홍보 문구는 읽는 사람이 알아들을 수 있고 할 일이 보이게 쓰고(어려운 외국어·탓하는 말·꾸밈에 가려진 내용 금지), 하루 행사로 끝내지 않고 이어서 실천한다',ARRAY['[6국04-02][6국04-03]']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C18','kor',6,2,'u4',1,'시 「조각하늘」(권지영 글)의 내용과 고유어 ‘조각하늘’ — 하늘이 구름 뒤에 숨어 나오지 않으려 해 숨바꼭질하고 싶은 것처럼 보이고, 호수에 비친 얼굴을 살펴본 뒤 구름 뒤로 숨음 · ‘조각하늘’은 구름이 온통 덮인 가운데서 드문드문 빠끔히 보이는 하늘(시의 정보로 뜻 짐작)',ARRAY['[6국04-03]']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C19','kor',6,2,'u4',2,'「세린이의 즐거운 하루」 속 낱말과 갈래 — 시나브로(모르는 사이에 조금씩 조금씩)·군침·뒤쓰레질 · 사전에서 찾아 고유어(모둠·줄넘기·벌개미취·둘레)·한자어(수업·친구·미술)·외래어(피자·벤치)로 가르기 · 하루 생활을 시간순으로 서술한 글',ARRAY['[6국04-03]']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C20','kor',6,2,'u4',2,'「고유어의 가치」 글의 내용 — 오래전부터 있던 고유어(어버이·하늘·아름답다)와 고유어를 바탕으로 만들어진 낱말(떡볶이·낚싯대·할미꽃) · 한글 표기만 있으면 고유어 · 고유어 관용 표현은 우리 고유의 문화와 정서를 보여 줌 · 새우잠·샛길·함박눈·도랑은 뜻을 쉽게 짐작하고 아름다운 느낌 · 우리말의 기본 바탕',ARRAY['[6국04-03]']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C21','kor',6,2,'u4',6,'「큰사전이 필요하다」(남상욱 글)의 내용 — 일본어만 쓰게 한 시대 · 철자법이 없어 사전이 필요 · 보퉁이 선생님 주시경과 ‘한글’이라는 이름 · 『말모이』 · 조선어연구회→조선어학회(문맹 퇴치 운동·한글 사전 편찬) · 1942년 원고 압수 · 1945년 서울역 창고에서 원고를 찾음 · 『조선말 큰사전』 완간',ARRAY['[6국02-02]']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C22','kor',6,2,'u4',6,'「큰사전이 필요하다」 속 낱말 — 문맹·절호·천금·섣부르다(보기의 직결되다)와 보퉁이·집대성하다·손색없다·망명하다·상흔·완간되다 — 앞뒤 문맥에서 뜻을 짐작하고 낱말 풀이로 확인',ARRAY['[6국02-02]']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C23','kor',6,2,'u4',6,'「우리말의 보물을 찾아서, ‘시골말 캐기’」의 내용 — 사전을 만들려고 전국의 우리말을 모으던 시절의 시골말 캐기 운동 · 구멍(구먹·구명·구녕·구무)·부추(세우리·정구지) · 방학을 맞은 학생들이 고향의 말을 써 보냄 · 방언도 소중한 보물 · 『큰사전』의 든든한 뿌리',ARRAY['[6국04-02]']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C24','kor',6,2,'u4',11,'시 「야, 겨울 온다」(강순예 글) 속 고유어 — 방그레(입만 예쁘게 조금 벌리고 소리 없이 보드랍게 웃는 모양)·길섶(길의 가장자리)·따습다(알맞게 따뜻하다)·바삭바삭 — 뜻을 사전에서 찾고 한 가지를 골라 문장 만들기 · 고유어 표현의 분위기와 느낌',ARRAY['[6국04-03]']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C25','kor',6,2,'u4',11,'교과 학습에 사용되는 낱말 — 강수량·교류·기후·소화·연소의 뜻과 쓰인 예(기초 다지기) · 뜻을 생각하며 문장 만들기',ARRAY['기초 다지기 교과 낱말(성취기준 표기 없음)']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u4-C26','kor',6,2,'u4',6,'편지를 읽고 내용과 글쓴이의 의도 추론하기 — 주시경 선생님이 쓴 편지(한힌샘의 뜻 · 우리말과 글을 지킨 일 · 한글은 겨레의 숨결이 담긴 보물 · 10월 9일)에서 단서와 경험·지식으로 내용을 추론하고 의도를 나눔(평가 예시 2)',ARRAY['[6국02-02]']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X01','kor',6,'u4',ARRAY['K6-2-u4-C1','K6-2-u4-C4','K6-2-u4-C8']::text[],'낱말의 갈래를 헷갈린다(한자어·외래어를 자주 쓰거나 익숙하다는 까닭으로 고유어로 여기는 등)','처음부터 있던 말? 한자? 다른 나라에서 온 말?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X02','kor',6,'u4',ARRAY['K6-2-u4-C2','K6-2-u4-C6','K6-2-u4-C16']::text[],'우리말을 바르게 쓰는 것을 고유어만 쓰는 것, 한자어와 외래어를 몰아내는 것으로 여긴다','알아들을 수 있게 · 뜻에 맞게 · 바꿀 수 있는 말만 쉽게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X03','kor',6,'u4',ARRAY['K6-2-u4-C2','K6-2-u4-C3','K6-2-u4-C14']::text[],'어려운 말·외국어·줄인 말을 많이 쓰면 더 많이 알거나 멋있어 보인다고 여겨, 듣는 사람이 알아듣지 못하는 문제를 보지 않는다','말은 뜻을 주고받으려고 써요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X04','kor',6,'u4',ARRAY['K6-2-u4-C3','K6-2-u4-C14']::text[],'말이 잘 통하지 않는 네 경우와 그 결과를 헷갈리거나, 뜻만 통하면 마음이 다쳐도 괜찮다고 여긴다','줄인 말 · 새말 · 기분 상하는 말 · 어려운 외국어') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X05','kor',6,'u4',ARRAY['K6-2-u4-C4']::text[],'국어사전의 표시를 보지 않고 소리나 글자 모양으로 갈래를 짐작한다','낱말 뒤에 무엇이 붙어 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X06','kor',6,'u4',ARRAY['K6-2-u4-C5']::text[],'고유어를 옛날에만 쓰던 말로 여기거나, 고유어를 바탕으로 새로 만든 낱말은 고유어가 아니라고 여긴다','처음부터 있던 말 + 그것으로 만든 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X07','kor',6,'u4',ARRAY['K6-2-u4-C5','K6-2-u4-C6','K6-2-u4-C13']::text[],'낱말의 갈래나 표준어·방언에 등수를 매겨 고유어(표준어)는 훌륭한 말, 다른 말은 못한 말로 여긴다','하는 일이 다를 뿐, 등수는 없어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X08','kor',6,'u4',ARRAY['K6-2-u4-C6']::text[],'다듬기의 목적을 글자 수 줄이기나 모든 한자어·외래어 바꾸기로 여겨, 바꿀 말이 마땅치 않은 말까지 바꾸려 한다','다듬기 = 누구나 알아듣게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X09','kor',6,'u4',ARRAY['K6-2-u4-C7']::text[],'관용 표현을 낱말 뜻을 하나씩 더해 글자 그대로 풀이한다','둘 이상이 어울려 새로운 뜻') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X10','kor',6,'u4',ARRAY['K6-2-u4-C8']::text[],'이름을 낱말로 나누어 보지 않거나, 외국어·한자어로 지은 이름을 고유어 활용 사례로 든다','이름을 낱말로 나누고 사전에서 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X11','kor',6,'u4',ARRAY['K6-2-u4-C9']::text[],'조사 대상과 범위를 너무 넓게 잡거나 방법을 정하지 않아 뜻까지 알아볼 시간이 없다','손이 닿는 곳으로 좁게, 방법 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X12','kor',6,'u4',ARRAY['K6-2-u4-C9','K6-2-u4-C10']::text[],'확인한 것·짐작한 것·모르는 것을 섞어 지어내 말하거나, 출처를 밝히지 않고 친구 말을 그대로 옮긴다','「찾은 뜻」·「짐작」·「아직 확인 못 함」 가르기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X13','kor',6,'u4',ARRAY['K6-2-u4-C10','K6-2-u4-C16']::text[],'알릴 내용보다 매체나 꾸밈을 먼저 정하거나, 화려하고 많은 자료가 좋은 자료라고 여긴다','내용 먼저, 매체와 꾸밈은 그다음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X14','kor',6,'u4',ARRAY['K6-2-u4-C10']::text[],'듣는 사람의 할 일(정리하며 듣기·까닭 있는 질문)을 하지 않거나 묻고 답하기를 발표가 아니라고 여긴다','궁금한 점 + 그것이 궁금한 까닭') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X15','kor',6,'u4',ARRAY['K6-2-u4-C11']::text[],'말은 쓰는 사람이 있으면 저절로 남는다고 여기거나, 사전 만들기를 낱말을 모으는 일로만 보고 말을 지키는 일과 잇지 못한다','적어 두고 이어 주어야 남아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X16','kor',6,'u4',ARRAY['K6-2-u4-C12']::text[],'추론을 글에 없는 일을 마음대로 상상하는 것으로 여기거나, 까닭 없이 「그냥 그럴 것 같아서」라고 말한다','글의 어느 부분을 보고 그렇게 생각했나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X17','kor',6,'u4',ARRAY['K6-2-u4-C12']::text[],'글에 그대로 적힌 것과 단서로 추론한 것을 가르지 못하거나, 글에 적혀 있지 않으면 아무것도 알 수 없다고 여긴다','적힌 것 → 단서 → 메운 생각') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X18','kor',6,'u4',ARRAY['K6-2-u4-C12','K6-2-u4-C5']::text[],'처음 보는 낱말의 뜻을 앞뒤 문맥을 살피지 않고 글자 모양이나 느낌만으로 짐작한다','앞뒤 말에서 실마리 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X19','kor',6,'u4',ARRAY['K6-2-u4-C13','K6-2-u4-C11']::text[],'방언을 고쳐야 할 틀린 말·배우지 못한 사람의 말·웃음거리로 여기거나, 표준어와 방언의 뜻을 헷갈린다','방언도 소중한 우리말 — 쓰이는 자리가 다를 뿐') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X20','kor',6,'u4',ARRAY['K6-2-u4-C13','K6-2-u4-C2']::text[],'상황과 듣는 사람을 살피지 않고 어디에서나 한 가지 말만 쓰려 한다(공식적인 자리에서도 고장 말만, 고장 사람과도 표준어만)','누구에게 · 어디에서?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X21','kor',6,'u4',ARRAY['K6-2-u4-C14']::text[],'언어생활 점검을 친구를 흠잡거나 누가 더 많이 썼는지 세어 견주는 일로 여긴다','내가 쓴 말부터, 우리 반의 일로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X22','kor',6,'u4',ARRAY['K6-2-u4-C15']::text[],'실천 다짐문의 네 부분(목적·실천 약속·전하고 싶은 말·날짜와 쓴 사람)을 빠뜨리거나 하는 일을 헷갈린다','무엇을 위해 · 무엇을 · 부탁 · 누가 언제') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X23','kor',6,'u4',ARRAY['K6-2-u4-C15','K6-2-u4-C16']::text[],'「열심히」·「하나도」·「다들」처럼 무엇을 할지 없거나 지킬 수 없을 만큼 크거나 내가 할 일이 없는 다짐을 좋은 다짐으로 여긴다','언제 · 어디에서 · 무엇을 — 내가') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X24','kor',6,'u4',ARRAY['K6-2-u4-C15']::text[],'고쳐 쓸 점을 글씨·종이 같은 겉모습에서 찾거나, 잘 쓴 부분은 말하지 않고 흠만 말한다(또는 반대로 고칠 점을 말하지 않는다)','잘 쓴 곳 먼저, 고칠 점은 내용에서, 바꿀 문장과 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X25','kor',6,'u4',ARRAY['K6-2-u4-C16']::text[],'우리말 홍보물을 어려운 외국어 문구·누군가를 탓하는 말·꾸밈으로 채우거나 역할·계획 없이 꾸미기부터 한다','알릴 것이 한눈에, 할 일이 보이게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X26','kor',6,'u4',ARRAY['K6-2-u4-C16','K6-2-u4-C15']::text[],'홍보물을 만들거나 다짐문을 쓴 날 하루로 실천이 끝났다고 여긴다','행사가 아니라 실천 — 이어서 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X27','kor',6,'u4',ARRAY['K6-2-u4-C16']::text[],'알릴 내용과 맞지 않는 활동 방법을 고른다(여러 번 보게 할 낱말을 한 번 틀고 마는 영상으로 등)','이 방법이 잘 살리는 점은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X29','kor',6,'u4',ARRAY['K6-2-u4-C18']::text[],'시 「조각하늘」에서 하늘이 한 일(구름 뒤에 숨기 · 호수에 비친 얼굴 살피기)이나 ‘조각하늘’이 나타내는 모습을 시와 다르게 안다','그 줄을 다시 읽어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X30','kor',6,'u4',ARRAY['K6-2-u4-C21']::text[],'「큰사전이 필요하다」의 사건과 인물이 한 일(보퉁이 선생님 · 『말모이』 · 조선어학회의 목표 · 원고 압수와 되찾음)이나 일이 일어난 차례를 글과 다르게 안다','그 부분을 다시 읽어 보면?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X31','kor',6,'u4',ARRAY['K6-2-u4-C22']::text[],'문맹 · 절호 · 천금 · 섣부르다 · 직결되다 · 보퉁이 · 완간되다 같은 이야기 속 낱말의 뜻을 엇갈리게 안다','낱말이 쓰인 문장을 다시 읽어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X32','kor',6,'u4',ARRAY['K6-2-u4-C5','K6-2-u4-C20']::text[],'고유어의 가치를 한 가지(옛말이라서 · 짧아서 등)로만 여기고, 뜻을 쉽게 짐작함 · 아름다운 느낌 · 문화와 정서 · 우리말의 바탕 같은 여러 가치를 놓친다','고유어의 좋은 점이 하나뿐일까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X33','kor',6,'u4',ARRAY['K6-2-u4-C23','K6-2-u4-C13']::text[],'「시골말 캐기」의 내용(누가 · 무엇을 · 왜 모았나)이나 표준어와 방언의 짝(구멍 · 부추 · 옥수수 · 개구리 · 가위 · 부침개)을 다르게 안다','글과 표를 다시 보아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X34','kor',6,'u4',ARRAY['K6-2-u4-C24']::text[],'「야, 겨울 온다」의 고유어(방그레 · 길섶 · 따습다 · 바삭바삭)의 뜻을 엇갈리게 알거나 문장에 알맞지 않게 쓴다','뜻을 넣어 다시 읽어 보면?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X35','kor',6,'u4',ARRAY['K6-2-u4-C25']::text[],'교과 학습 낱말(강수량 · 교류 · 기후 · 소화 · 연소)의 뜻을 서로 헷갈리거나 문장에 알맞지 않게 쓴다','낱말 뜻을 넣어 읽어 보면?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X36','kor',6,'u4',ARRAY['K6-2-u4-C12','K6-2-u4-C26']::text[],'추론에는 정답이 하나뿐이라고 여겨, 근거를 갖춘 친구의 추론도 나와 다르면 틀렸다고 한다','친구는 무엇을 근거로 그렇게 생각했을까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X37','kor',6,'u4',ARRAY['K6-2-u4-C19','K6-2-u4-C20']::text[],'「세린이의 즐거운 하루」나 「고유어의 가치」의 내용(글의 짜임 · 든 예 · 고유어의 가치)을 글과 다르게 안다','그 문단을 다시 읽어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u4-X38','kor',6,'u4',ARRAY['K6-2-u4-C26']::text[],'편지의 내용이나 글쓴이의 의도를 잘못 파악하거나, 글 내용을 그대로 옮긴 것을 의도라고 여긴다','글쓴이는 읽는 사람이 무엇을 하기를 바랐을까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L01_basic#1','kor',6,2,'u4','L01','tb_g6_2_kor_u4_L01_basic','lesson_basic','K6-2-u4-C2',1,'mc','auto','『국어』 179쪽 「생각 열기」예요. 아이가 할머니의 말을 잘 알아듣지 못한 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u4-X01','K6-2-u4-X04','K6-2-u4-X03']::text[],false,'{"seq":1,"concept":"K6-2-u4-C2","difficulty":1,"kind":"mc","stem":"『국어』 179쪽 「생각 열기」예요. 아이가 할머니의 말을 잘 알아듣지 못한 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"‘비설거지’, ‘뒤란’처럼 뜻을 모르는 낱말이 있어서","correct":true},{"t":"할머니가 외국어를 섞어 빠르게 말해서","mis":"K6-2-u4-X01"},{"t":"비가 와서 밖에 나가 심부름하기 싫어서","mis":"K6-2-u4-X04"},{"t":"할머니가 친구들끼리 쓰는 줄임말을 써서","mis":"K6-2-u4-X03"}],"explanation":["아이는 “비설거지가 뭐지? 뒤란은 어디일까?” 하고 되물었어요.","두 낱말의 뜻을 몰라서 할머니의 말을 다 알아듣지 못했어요.","우리말을 바르게 이해하려면 낱말의 뜻을 알아야 해요."],"asset":{"type":"speech","turns":[{"who":"할머니","text":"“얼른 비설거지 해야겠다. 그래야 비를 안 맞지.”"},{"who":"할머니","text":"“뒤란에 가서 장독대를 덮고 오겠니?”"},{"who":"아이","text":"“비설거지가 뭐지? 뒤란은 어디일까?”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L01_basic#2','kor',6,2,'u4','L01','tb_g6_2_kor_u4_L01_basic','lesson_basic','K6-2-u4-C1',1,'mc','auto','할머니가 쓴 ‘비설거지’, ‘뒤란’처럼 우리말에 처음부터 있던 낱말이나 그것을 바탕으로 만들어진 낱말을 무엇이라고 하나요?',ARRAY['K6-2-u4-X01','K6-2-u4-X03']::text[],false,'{"seq":2,"concept":"K6-2-u4-C1","difficulty":1,"kind":"mc","stem":"할머니가 쓴 ‘비설거지’, ‘뒤란’처럼 우리말에 처음부터 있던 낱말이나 그것을 바탕으로 만들어진 낱말을 무엇이라고 하나요?","options":[{"t":"고유어","correct":true},{"t":"한자어","mis":"K6-2-u4-X01"},{"t":"외래어","mis":"K6-2-u4-X01"},{"t":"줄임말","mis":"K6-2-u4-X03"}],"explanation":["고유어는 우리말에 처음부터 있던 낱말이에요.","그것을 바탕으로 만들어진 낱말도 고유어예요.","한자어는 한자로, 외래어는 외국에서 들어온 말로 이루어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L01_basic#3','kor',6,2,'u4','L01','tb_g6_2_kor_u4_L01_basic','lesson_basic','K6-2-u4-C18',1,'mc','auto','「조각하늘」에서 하늘이 숨바꼭질하고 싶은 것처럼 보이는 까닭은 무엇인가요?',ARRAY['K6-2-u4-X29']::text[],false,'{"seq":3,"concept":"K6-2-u4-C18","difficulty":1,"kind":"mc","stem":"「조각하늘」에서 하늘이 숨바꼭질하고 싶은 것처럼 보이는 까닭은 무엇인가요?","options":[{"t":"구름 뒤에 숨어 나오지 않으려 하기 때문","correct":true},{"t":"호수에 빠져 보이지 않기 때문","mis":"K6-2-u4-X29"},{"t":"바람이 하늘을 멀리 날려 보냈기 때문","mis":"K6-2-u4-X29"},{"t":"밤이 되어 하늘이 어두워졌기 때문","mis":"K6-2-u4-X29"}],"explanation":["시의 둘째 줄을 다시 읽어요.","하늘이 구름 뒤에 숨어서 나올 생각을 안 한다고 했어요.","그래서 숨바꼭질하고 싶은 것처럼 보여요."],"asset":{"type":"passage","lines":["하늘이 숨바꼭질하고 싶은가 봐요.","구름 뒤에 숨어서 나올 생각을 안 해요.","호수에 비친 자기 얼굴만","빠끔히 내다보고","구름 뒤로 쏘옥 숨어요.","(간추림) 바람이 호수를 간지럽혀도 조각하늘은 구름 뒤에서 좀처럼 나오지 않는다."],"title":"「조각하늘」(권지영 글) — 『국어』 180쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L01_basic#4','kor',6,2,'u4','L01','tb_g6_2_kor_u4_L01_basic','lesson_basic','K6-2-u4-C3',1,'ox','auto','친구가 ‘점메추’라는 줄임말을 써서 알아듣지 못한 일은 일상생활에서 우리말을 바르게 사용하지 못한 경우예요.',ARRAY['K6-2-u4-X03']::text[],false,'{"seq":4,"concept":"K6-2-u4-C3","difficulty":1,"kind":"ox","stem":"친구가 ‘점메추’라는 줄임말을 써서 알아듣지 못한 일은 일상생활에서 우리말을 바르게 사용하지 못한 경우예요.","answer":"O","reason_options":[{"t":"지나치게 줄인 말은 아는 사람끼리만 통해 듣는 사람이 알아듣지 못해요.","correct":true},{"t":"줄임말은 짧아서 누구에게나 더 잘 통해요.","mis":"K6-2-u4-X03"}],"mis":"K6-2-u4-X03","explanation":["『국어』 181쪽 2번에서 친구 1이 말한 경우예요.","줄임말을 모르는 사람은 무슨 뜻인지 알 수 없어요.","말은 듣는 사람이 알아들을 수 있게 써야 해요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"“나는 친구가 ‘점메추’라는 줄임말을 써서 알아듣지 못한 적이 있어.”"},{"who":"친구 2","text":"“친구들이 비속어를 쓰면 대화할 때 불쾌하고 기분이 좋지 않아.”"},{"who":"친구 3","text":"“줄임말과 비속어를 줄이고 우리말을 바르게 사용하는 습관을 길러야 해.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L01_basic#5','kor',6,2,'u4','L01','tb_g6_2_kor_u4_L01_basic','lesson_basic','K6-2-u4-C18',2,'mc','auto','「조각하늘」에서 호수에 비친 하늘은 어떤 행동을 하나요?',ARRAY['K6-2-u4-X29']::text[],false,'{"seq":5,"concept":"K6-2-u4-C18","difficulty":2,"kind":"mc","stem":"「조각하늘」에서 호수에 비친 하늘은 어떤 행동을 하나요?","options":[{"t":"자기 얼굴을 살펴본 뒤 구름 뒤로 숨어 버린다","correct":true},{"t":"호수에 내려와 물놀이를 한다","mis":"K6-2-u4-X29"},{"t":"바람과 함께 술래잡기를 한다","mis":"K6-2-u4-X29"},{"t":"구름을 밀어내고 환하게 웃는다","mis":"K6-2-u4-X29"}],"explanation":["시의 둘째 연을 다시 읽어요.","호수에 비친 자기 얼굴만 빠끔히 내다보고 구름 뒤로 숨는다고 했어요.","하늘을 사람처럼 나타냈어요."],"asset":{"type":"passage","lines":["하늘이 숨바꼭질하고 싶은가 봐요.","구름 뒤에 숨어서 나올 생각을 안 해요.","호수에 비친 자기 얼굴만","빠끔히 내다보고","구름 뒤로 쏘옥 숨어요.","(간추림) 바람이 호수를 간지럽혀도 조각하늘은 구름 뒤에서 좀처럼 나오지 않는다."],"title":"「조각하늘」(권지영 글) — 『국어』 180쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L01_basic#6','kor',6,2,'u4','L01','tb_g6_2_kor_u4_L01_basic','lesson_basic','K6-2-u4-C18',2,'mc','auto','「조각하늘」의 ‘조각하늘’은 하늘의 어떤 모습을 나타내는 낱말일까요?',ARRAY['K6-2-u4-X29']::text[],false,'{"seq":6,"concept":"K6-2-u4-C18","difficulty":2,"kind":"mc","stem":"「조각하늘」의 ‘조각하늘’은 하늘의 어떤 모습을 나타내는 낱말일까요?","options":[{"t":"구름이 온통 덮인 가운데서 드문드문 빠끔히 보이는 하늘","correct":true},{"t":"구름 한 점 없이 맑게 갠 파란 하늘","mis":"K6-2-u4-X29"},{"t":"해가 지며 붉게 물들어 가는 저녁 하늘","mis":"K6-2-u4-X29"},{"t":"호수 바닥에 가라앉아 보이지 않는 하늘","mis":"K6-2-u4-X29"}],"explanation":["시에서 하늘은 늘 구름 뒤에 숨어 있어요.","구름 사이로 조각처럼 조금씩 보이는 하늘을 떠올릴 수 있어요.","시의 정보를 중심으로 고유어의 뜻을 짐작했어요."],"asset":{"type":"passage","lines":["하늘이 숨바꼭질하고 싶은가 봐요.","구름 뒤에 숨어서 나올 생각을 안 해요.","호수에 비친 자기 얼굴만","빠끔히 내다보고","구름 뒤로 쏘옥 숨어요.","(간추림) 바람이 호수를 간지럽혀도 조각하늘은 구름 뒤에서 좀처럼 나오지 않는다."],"title":"「조각하늘」(권지영 글) — 『국어』 180쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L01_basic#7','kor',6,2,'u4','L01','tb_g6_2_kor_u4_L01_basic','lesson_basic','K6-2-u4-C3',2,'mc','auto','『국어』 181쪽 2번에서 친구들이 비속어를 쓸 때 생기는 일로 말한 것은 무엇인가요?',ARRAY['K6-2-u4-X04','K6-2-u4-X03']::text[],false,'{"seq":7,"concept":"K6-2-u4-C3","difficulty":2,"kind":"mc","stem":"『국어』 181쪽 2번에서 친구들이 비속어를 쓸 때 생기는 일로 말한 것은 무엇인가요?","options":[{"t":"대화할 때 불쾌하고 기분이 좋지 않다","correct":true},{"t":"뜻이 통하니 아무 문제가 없다","mis":"K6-2-u4-X04"},{"t":"말이 짧아져서 대화가 빨라진다","mis":"K6-2-u4-X03"},{"t":"멋있어 보여서 친구가 많아진다","mis":"K6-2-u4-X03"}],"explanation":["친구 2는 비속어를 들으면 불쾌하고 기분이 좋지 않다고 했어요.","뜻이 통해도 마음이 다치면 말이 잘 통한 것이 아니에요.","그래서 비속어를 줄여야 해요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"“나는 친구가 ‘점메추’라는 줄임말을 써서 알아듣지 못한 적이 있어.”"},{"who":"친구 2","text":"“친구들이 비속어를 쓰면 대화할 때 불쾌하고 기분이 좋지 않아.”"},{"who":"친구 3","text":"“줄임말과 비속어를 줄이고 우리말을 바르게 사용하는 습관을 길러야 해.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L01_basic#8','kor',6,2,'u4','L01','tb_g6_2_kor_u4_L01_basic','lesson_basic','K6-2-u4-C2',2,'mc','auto','『국어』 181쪽 2번에서 친구 3이 말한 개선할 점은 무엇인가요?',ARRAY['K6-2-u4-X03','K6-2-u4-X02','K6-2-u4-X04']::text[],false,'{"seq":8,"concept":"K6-2-u4-C2","difficulty":2,"kind":"mc","stem":"『국어』 181쪽 2번에서 친구 3이 말한 개선할 점은 무엇인가요?","options":[{"t":"줄임말과 비속어를 줄이고 우리말을 바르게 사용하는 습관을 기른다","correct":true},{"t":"줄임말과 비속어를 새롭게 더 만들어 쓴다","mis":"K6-2-u4-X03"},{"t":"한자어와 외래어를 모두 쓰지 않는다","mis":"K6-2-u4-X02"},{"t":"듣기 불편한 말은 아예 하지 않고 입을 다문다","mis":"K6-2-u4-X04"}],"explanation":["친구 3은 줄임말과 비속어를 줄이자고 했어요.","우리말을 바르게 사용하는 습관을 기르자고 했어요.","한자어나 외래어를 모두 없애자는 말은 아니에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"“나는 친구가 ‘점메추’라는 줄임말을 써서 알아듣지 못한 적이 있어.”"},{"who":"친구 2","text":"“친구들이 비속어를 쓰면 대화할 때 불쾌하고 기분이 좋지 않아.”"},{"who":"친구 3","text":"“줄임말과 비속어를 줄이고 우리말을 바르게 사용하는 습관을 길러야 해.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L01_basic#9','kor',6,2,'u4','L01','tb_g6_2_kor_u4_L01_basic','lesson_basic','K6-2-u4-C2',2,'blank','auto','『국어』 180쪽 「조각하늘」 아래에 실린 풀이예요. 시의 ‘쏘옥’은 (     )이/가 바른 표기예요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K6-2-u4-X05']::text[],false,'{"seq":9,"concept":"K6-2-u4-C2","difficulty":2,"kind":"blank","stem":"『국어』 180쪽 「조각하늘」 아래에 실린 풀이예요. 시의 ‘쏘옥’은 (     )이/가 바른 표기예요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"쏙","correct":true},{"t":"쏘옥","mis":"K6-2-u4-X05"},{"t":"쏘오옥","mis":"K6-2-u4-X05"},{"t":"쑤욱","mis":"K6-2-u4-X05"}],"explanation":["시에서는 느낌을 살리려고 ‘쏘옥’이라고 썼어요.","바른 표기는 ‘쏙’이에요.","바른 표기는 사전에서 확인할 수 있어요."],"asset":{"type":"passage","lines":["하늘이 숨바꼭질하고 싶은가 봐요.","구름 뒤에 숨어서 나올 생각을 안 해요.","호수에 비친 자기 얼굴만","빠끔히 내다보고","구름 뒤로 쏘옥 숨어요.","(간추림) 바람이 호수를 간지럽혀도 조각하늘은 구름 뒤에서 좀처럼 나오지 않는다."],"title":"「조각하늘」(권지영 글) — 『국어』 180쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L01_basic#10','kor',6,2,'u4','L01','tb_g6_2_kor_u4_L01_basic','lesson_basic','K6-2-u4-C2',3,'mc','auto','「생각 열기」의 물음 “우리말을 바르게 이해하고 상황에 맞게 사용하려면 어떤 노력을 해야 할까요?”에 대한 답으로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u4-X03','K6-2-u4-X02','K6-2-u4-X20']::text[],false,'{"seq":10,"concept":"K6-2-u4-C2","difficulty":3,"kind":"mc","stem":"「생각 열기」의 물음 “우리말을 바르게 이해하고 상황에 맞게 사용하려면 어떤 노력을 해야 할까요?”에 대한 답으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"우리말의 의미와 가치를 알고, 그 말을 사용할 때 어떤 효과가 있는지 생각한다","correct":true},{"t":"어려운 한자어와 외래어를 많이 외워 두고 자주 섞어 쓴다","mis":"K6-2-u4-X03"},{"t":"고유어만 쓰고 한자어와 외래어는 모두 버리고 쓰지 않는다","mis":"K6-2-u4-X02"},{"t":"듣는 사람이 누구든, 어디에서든 늘 같은 말만 쓴다","mis":"K6-2-u4-X20"}],"explanation":["우리말을 바르게 이해하려면 낱말의 의미와 가치를 알아야 해요.","그 말을 쓸 때 어떤 효과가 있는지도 생각해요.","이 단원에서 고유어의 가치와 우리말을 지키는 태도를 배워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L01_challenge#1','kor',6,2,'u4','L01','tb_g6_2_kor_u4_L01_challenge','lesson_challenge','K6-2-u4-C18',2,'match','auto','『국어』 181쪽 1번이에요. 「조각하늘」에 대한 물음과 알맞은 답을 이으세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u4-C18","difficulty":2,"kind":"match","stem":"『국어』 181쪽 1번이에요. 「조각하늘」에 대한 물음과 알맞은 답을 이으세요.","pairs":[{"l":"하늘이 숨바꼭질하고 싶은 것처럼 보이는 까닭","r":"구름 뒤에 숨어 나오지 않으려 하기 때문"},{"l":"호수에 비친 하늘이 하는 행동","r":"얼굴을 살펴본 뒤 구름 뒤로 숨어 버림"},{"l":"‘조각하늘’이 나타내는 모습","r":"구름 사이로 드문드문 빠끔히 보이는 하늘"}],"mis":"K6-2-u4-X29","explanation":["시의 첫째 연에서 숨바꼭질하는 까닭을 찾아요.","둘째 연에서 호수에 비친 하늘의 행동을 찾아요.","시 전체의 정보로 ‘조각하늘’의 뜻을 짐작해요."],"asset":{"type":"passage","lines":["하늘이 숨바꼭질하고 싶은가 봐요.","구름 뒤에 숨어서 나올 생각을 안 해요.","호수에 비친 자기 얼굴만","빠끔히 내다보고","구름 뒤로 쏘옥 숨어요.","(간추림) 바람이 호수를 간지럽혀도 조각하늘은 구름 뒤에서 좀처럼 나오지 않는다."],"title":"「조각하늘」(권지영 글) — 『국어』 180쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L01_challenge#2','kor',6,2,'u4','L01','tb_g6_2_kor_u4_L01_challenge','lesson_challenge','K6-2-u4-C1',2,'mc','auto','고유어의 뜻을 한자어나 외래어와 대비해 살피면 어떤 점이 좋은가요?',ARRAY['K6-2-u4-X07','K6-2-u4-X02','K6-2-u4-X06']::text[],false,'{"seq":2,"concept":"K6-2-u4-C1","difficulty":2,"kind":"mc","stem":"고유어의 뜻을 한자어나 외래어와 대비해 살피면 어떤 점이 좋은가요?","options":[{"t":"고유어가 지닌 가치에 관심을 둘 수 있다","correct":true},{"t":"고유어가 가장 훌륭한 말임을 증명할 수 있다","mis":"K6-2-u4-X07"},{"t":"한자어와 외래어를 쓰지 않아도 됨을 알 수 있다","mis":"K6-2-u4-X02"},{"t":"고유어는 옛날에만 쓰던 말임을 알 수 있다","mis":"K6-2-u4-X06"}],"explanation":["고유어를 다른 갈래의 낱말과 견주어 보면 고유어의 특징이 잘 보여요.","그래서 고유어가 지닌 가치에 관심을 두게 돼요.","어느 갈래가 더 훌륭한지 등수를 매기는 일은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L01_challenge#3','kor',6,2,'u4','L01','tb_g6_2_kor_u4_L01_challenge','lesson_challenge','K6-2-u4-C3',3,'error','auto','『국어』 181쪽 2번처럼 우리말을 바르게 사용하지 못한 경우를 이야기했어요. 알맞지 않게 말한 것은 무엇인가요?',ARRAY['K6-2-u4-X04','K6-2-u4-X03']::text[],false,'{"seq":3,"concept":"K6-2-u4-C3","difficulty":3,"kind":"error","stem":"『국어』 181쪽 2번처럼 우리말을 바르게 사용하지 못한 경우를 이야기했어요. 알맞지 않게 말한 것은 무엇인가요?","options":[{"t":"㉮ “뜻만 통하면 비속어를 써도 괜찮아.”","correct":true,"mis_target":"K6-2-u4-X04"},{"t":"㉯ “줄임말은 아는 사람끼리만 통해서 다른 사람이 알아듣지 못할 수 있어.”","mis":"K6-2-u4-X03"},{"t":"㉰ “비속어를 들으면 뜻은 알아도 기분이 상해.”","mis":"K6-2-u4-X04"}],"explanation":["비속어는 뜻이 통해도 듣는 사람의 마음을 다치게 해요.","마음이 다치면 말이 잘 통한 것이 아니에요.","그래서 ㉮가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L01_challenge#4','kor',6,2,'u4','L01','tb_g6_2_kor_u4_L01_challenge','lesson_challenge','K6-2-u4-C1',3,'mc','auto','할머니의 말에서 아이가 ‘비설거지’의 뜻을 짐작할 수 있는 단서로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u4-X18','K6-2-u4-X05','K6-2-u4-X17']::text[],false,'{"seq":4,"concept":"K6-2-u4-C1","difficulty":3,"kind":"mc","stem":"할머니의 말에서 아이가 ‘비설거지’의 뜻을 짐작할 수 있는 단서로 가장 알맞은 것은 무엇인가요?","options":[{"t":"“그래야 비를 안 맞지.”, “장독대를 덮고 오겠니?”라는 앞뒤 말","correct":true},{"t":"‘설거지’는 그릇을 씻는 일이니 빗물로 그릇을 씻는다는 뜻","mis":"K6-2-u4-X18"},{"t":"낱말이 길어서 어려운 일이라는 뜻","mis":"K6-2-u4-X05"},{"t":"단서가 없으니 짐작할 수 없다","mis":"K6-2-u4-X17"}],"explanation":["할머니는 비를 안 맞게 장독대를 덮으라고 했어요.","앞뒤 말을 보면 비에 맞지 않게 물건을 덮는 일임을 짐작할 수 있어요.","정확한 뜻은 국어사전에서 확인해요."],"asset":{"type":"speech","turns":[{"who":"할머니","text":"“얼른 비설거지 해야겠다. 그래야 비를 안 맞지.”"},{"who":"할머니","text":"“뒤란에 가서 장독대를 덮고 오겠니?”"},{"who":"아이","text":"“비설거지가 뭐지? 뒤란은 어디일까?”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L01_challenge#5','kor',6,2,'u4','L01','tb_g6_2_kor_u4_L01_challenge','lesson_challenge','K6-2-u4-C2',3,'mc','auto','『국어』 181쪽 「알고 싶어요」의 빈칸에 이 단원에서 알고 싶은 내용을 쓰려고 해요. 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u4-X03','K6-2-u4-X02']::text[],false,'{"seq":5,"concept":"K6-2-u4-C2","difficulty":3,"kind":"mc","stem":"『국어』 181쪽 「알고 싶어요」의 빈칸에 이 단원에서 알고 싶은 내용을 쓰려고 해요. 가장 알맞은 것은 무엇인가요?","options":[{"t":"우리말을 지키기 위한 노력 알아보기","correct":true},{"t":"다른 나라 말을 빨리 배우는 방법","mis":"K6-2-u4-X03"},{"t":"새로운 줄임말을 만드는 방법","mis":"K6-2-u4-X03"},{"t":"고유어가 아닌 낱말을 모두 찾아 없애는 방법","mis":"K6-2-u4-X02"}],"explanation":["가운데에 ‘소중한 우리말’이 있어요.","고유어의 가치, 고유어 활용 사례, 우리말 바르게 사용하기와 이어지는 내용을 써요.","우리말을 지키기 위한 노력 알아보기가 잘 어울려요."],"asset":{"type":"passage","lines":["[가운데] 소중한 우리말","[가지] 우리말 바르게 사용하기 · 고유어의 가치 · 고유어 활용 사례","[빈칸 둘] (          ) · (          )"],"numbered":false,"title":"알고 싶어요 — 이 단원에서 알고 싶은 내용 『국어』 181쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L01_challenge#6','kor',6,2,'u4','L01','tb_g6_2_kor_u4_L01_challenge','lesson_challenge','K6-2-u4-C18',3,'mc','auto','「조각하늘」을 읽고 ‘조각하늘’의 뜻을 짐작하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u4-X18','K6-2-u4-X29','K6-2-u4-X17']::text[],false,'{"seq":6,"concept":"K6-2-u4-C18","difficulty":3,"kind":"mc","stem":"「조각하늘」을 읽고 ‘조각하늘’의 뜻을 짐작하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"시에서 하늘이 구름 뒤에 숨어 있다는 정보로 뜻을 짐작한다","correct":true},{"t":"낱말의 글자 모양만 보고 떠오르는 느낌대로 정한다","mis":"K6-2-u4-X18"},{"t":"시는 읽지 않고 제목만 보고 뜻을 정해 버린다","mis":"K6-2-u4-X29"},{"t":"뜻을 짐작할 수 없으니 그냥 넘어가고 읽지 않는다","mis":"K6-2-u4-X17"}],"explanation":["시에는 하늘이 구름 뒤에 숨어 빠끔히 내다본다는 정보가 있어요.","이 정보를 모으면 ‘조각하늘’의 뜻을 짐작할 수 있어요.","짐작한 뜻은 사전에서 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L01_challenge#7','kor',6,2,'u4','L01','tb_g6_2_kor_u4_L01_challenge','lesson_challenge','K6-2-u4-C3',3,'match','auto','말이 잘 통하지 않은 경우와 그 까닭을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u4-C3","difficulty":3,"kind":"match","stem":"말이 잘 통하지 않은 경우와 그 까닭을 알맞게 이으세요.","pairs":[{"l":"할머니의 ‘비설거지’를 아이가 알아듣지 못함","r":"고유어의 뜻을 몰라서"},{"l":"친구의 ‘점메추’를 알아듣지 못함","r":"지나치게 줄인 말이라서"},{"l":"친구의 비속어에 기분이 상함","r":"뜻은 통해도 마음을 다치게 해서"}],"mis":"K6-2-u4-X04","explanation":["「생각 열기」에서 아이는 낱말의 뜻을 몰랐어요.","줄임말은 아는 사람끼리만 통해요.","비속어는 듣는 사람의 기분을 상하게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L01_challenge#8','kor',6,2,'u4','L01','tb_g6_2_kor_u4_L01_challenge','lesson_challenge','K6-2-u4-C2',4,'essay','teacher','『국어』 181쪽 2번처럼 일상생활에서 우리말을 바르게 사용하지 못한 경우를 하나 찾아 쓰고, 개선할 점을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K6-2-u4-C2","difficulty":4,"kind":"essay","stem":"『국어』 181쪽 2번처럼 일상생활에서 우리말을 바르게 사용하지 못한 경우를 하나 찾아 쓰고, 개선할 점을 쓰세요.","answer_guide":{"answer":"예: 친구들과 이야기할 때 뜻을 알기 어려운 줄임말을 써서 다른 친구가 대화에 끼지 못한 적이 있다. 앞으로는 줄임말 대신 모두가 알아들을 수 있는 우리말로 바꾸어 말하겠다.","scoring_points":["우리말을 바르게 사용하지 못한 경우를 구체적으로 썼는가","그 경우에 생기는 문제를 썼는가","실천할 수 있는 개선할 점을 썼는가"]},"explanation":["줄임말, 비속어처럼 생활에서 겪은 일을 떠올려요.","그 말 때문에 어떤 일이 생겼는지 써요.","어떻게 고칠지 구체적으로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L01_challenge#9','kor',6,2,'u4','L01','tb_g6_2_kor_u4_L01_challenge','lesson_challenge','K6-2-u4-C18',4,'essay','teacher','‘조각하늘’처럼 뜻을 짐작할 수 있는 고유어는 어떤 점이 좋은지 「조각하늘」의 내용과 관련지어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u4-C18","difficulty":4,"kind":"essay","stem":"‘조각하늘’처럼 뜻을 짐작할 수 있는 고유어는 어떤 점이 좋은지 「조각하늘」의 내용과 관련지어 쓰세요.","answer_guide":{"answer":"예: ‘조각하늘’은 ‘조각’과 ‘하늘’이 합쳐진 말이라 구름 사이로 조각처럼 조금 보이는 하늘이 그림처럼 떠오른다. 시에서 구름 뒤에 숨은 하늘과 잘 어울려 뜻을 쉽게 짐작할 수 있고 느낌도 아름답다.","scoring_points":["‘조각하늘’의 뜻을 시의 내용과 이어 썼는가","고유어의 좋은 점(뜻 짐작·아름다운 느낌 등)을 썼는가","자신의 생각을 분명히 썼는가"]},"explanation":["‘조각하늘’을 이루는 낱말을 나누어 보아요.","시에서 하늘이 어떻게 그려졌는지 떠올려요.","고유어가 주는 느낌을 함께 써요."],"asset":{"type":"passage","lines":["하늘이 숨바꼭질하고 싶은가 봐요.","구름 뒤에 숨어서 나올 생각을 안 해요.","호수에 비친 자기 얼굴만","빠끔히 내다보고","구름 뒤로 쏘옥 숨어요.","(간추림) 바람이 호수를 간지럽혀도 조각하늘은 구름 뒤에서 좀처럼 나오지 않는다."],"title":"「조각하늘」(권지영 글) — 『국어』 180쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L01_challenge#10','kor',6,2,'u4','L01','tb_g6_2_kor_u4_L01_challenge','lesson_challenge','K6-2-u4-C1',4,'essay','teacher','『국어』 181쪽 「알고 싶어요」의 빈칸 두 곳에 들어갈 내용을 쓰고, 그것을 알고 싶은 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u4-C1","difficulty":4,"kind":"essay","stem":"『국어』 181쪽 「알고 싶어요」의 빈칸 두 곳에 들어갈 내용을 쓰고, 그것을 알고 싶은 까닭을 쓰세요.","answer_guide":{"answer":"예: ① 우리말을 지키기 위한 노력 — 옛날 사람들이 우리말을 어떻게 지켜 왔는지 궁금하기 때문이다. ② 우리 동네 이름에 담긴 고유어 — 매일 지나가는 길 이름의 뜻을 알고 싶기 때문이다.","scoring_points":["빈칸 두 곳에 단원 내용과 이어지는 것을 썼는가","알고 싶은 까닭을 썼는가","호기심이 드러나게 썼는가"]},"explanation":["가운데 ‘소중한 우리말’과 이어지는 내용을 떠올려요.","정확한 답을 쓰는 활동이 아니라 궁금한 것을 쓰는 활동이에요.","왜 알고 싶은지 함께 써요."],"asset":{"type":"passage","lines":["[가운데] 소중한 우리말","[가지] 우리말 바르게 사용하기 · 고유어의 가치 · 고유어 활용 사례","[빈칸 둘] (          ) · (          )"],"numbered":false,"title":"알고 싶어요 — 이 단원에서 알고 싶은 내용 『국어』 181쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L02_basic#1','kor',6,2,'u4','L02','tb_g6_2_kor_u4_L02_basic','lesson_basic','K6-2-u4-C19',1,'mc','auto','「세린이의 즐거운 하루」에 나오는 ‘뒤쓰레질’의 뜻은 무엇인가요?',ARRAY['K6-2-u4-X18']::text[],false,'{"seq":1,"concept":"K6-2-u4-C19","difficulty":1,"kind":"mc","stem":"「세린이의 즐거운 하루」에 나오는 ‘뒤쓰레질’의 뜻은 무엇인가요?","options":[{"t":"어떤 일을 마친 뒤에 그 자리의 쓰레기를 쓸어 내는 일","correct":true},{"t":"쓰레기를 뒤로 던져 버리는 일","mis":"K6-2-u4-X18"},{"t":"뒷자리 친구에게 청소를 미루는 일","mis":"K6-2-u4-X18"},{"t":"미술 활동을 처음 시작하는 일","mis":"K6-2-u4-X18"}],"explanation":["글 아래의 낱말 풀이를 보아요.","뒤쓰레질은 일을 마친 뒤 쓰레기를 쓸어 내는 일이에요.","세린이는 미술 활동을 마치고 뒤쓰레질을 했어요."],"asset":{"type":"passage","lines":["(간추림) 미술은 세린이가 가장 좋아하는 과목이다.","시나브로 미술 활동을 마칠 시간이 되었고","세린이는 뒤쓰레질을 얼른 하고 다른 친구들과 모둠 근처를 청소했습니다.","(간추림) 점심 급식에 나온 피자를 생각하니 군침을 흘릴 뻔했다.","(간추림) 점심을 먹고 운동장에서 친구들과 함께 줄넘기 연습을 했다.","[낱말] 뒤쓰레질 — 어떤 일을 마친 뒤에 그 자리의 쓰레기를 쓸어 내는 일."],"numbered":false,"title":"「세린이의 즐거운 하루」 앞부분 — 『국어』 182쪽","hi":["시나브로","뒤쓰레질"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L02_basic#2','kor',6,2,'u4','L02','tb_g6_2_kor_u4_L02_basic','lesson_basic','K6-2-u4-C4',1,'mc','auto','국어사전에서 ‘벤치’를 찾으면 낱말 뒤에 ‘bench’라는 영어가 붙어 있어요. ‘벤치’는 어떤 갈래의 낱말인가요?',ARRAY['K6-2-u4-X05','K6-2-u4-X01']::text[],false,'{"seq":2,"concept":"K6-2-u4-C4","difficulty":1,"kind":"mc","stem":"국어사전에서 ‘벤치’를 찾으면 낱말 뒤에 ‘bench’라는 영어가 붙어 있어요. ‘벤치’는 어떤 갈래의 낱말인가요?","options":[{"t":"외래어","correct":true},{"t":"고유어","mis":"K6-2-u4-X05"},{"t":"한자어","mis":"K6-2-u4-X01"}],"explanation":["외래어는 외국에서 들어와 우리 생활에서 널리 쓰이는 낱말이에요.","사전에서 외래어를 찾으면 낱말 뒤에 영어 등의 외국어가 함께 있어요.","그래서 ‘벤치’는 외래어예요."],"asset":{"type":"passage","lines":["미술(美術) — 공간 및 시각의 미를 표현하는 예술.","벤치(bench) — 여러 사람이 함께 앉을 수 있는 긴 의자.","시나브로 — 모르는 사이에 조금씩 조금씩.","군침 — 음식이 먹고 싶어서 입안에 도는 침."],"title":"국어사전에서 찾은 낱말 — 『국어』 183쪽 2번 (1)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L02_basic#3','kor',6,2,'u4','L02','tb_g6_2_kor_u4_L02_basic','lesson_basic','K6-2-u4-C4',1,'ox','auto','국어사전에서 찾았을 때 낱말 뒤에 아무것도 붙어 있지 않은 ‘시나브로’, ‘군침’은 고유어예요.',ARRAY['K6-2-u4-X05']::text[],false,'{"seq":3,"concept":"K6-2-u4-C4","difficulty":1,"kind":"ox","stem":"국어사전에서 찾았을 때 낱말 뒤에 아무것도 붙어 있지 않은 ‘시나브로’, ‘군침’은 고유어예요.","answer":"O","reason_options":[{"t":"한글 표기만 있는 낱말이 고유어예요.","correct":true},{"t":"낱말 뒤에 한자가 붙어 있어야 고유어예요.","mis":"K6-2-u4-X05"}],"mis":"K6-2-u4-X05","explanation":["친구 3은 ‘시나브로’와 ‘군침’ 뒤에는 아무것도 붙어 있지 않다고 했어요.","한글 표기만 있으면 고유어예요.","한자가 붙어 있으면 한자어예요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"“글에 나온 여러 낱말을 사전에서 찾아보니 각각의 종류가 다른 것 같아.”"},{"who":"친구 2","text":"“그래. ‘미술’을 사전에서 찾아보니 낱말 뒤에 ‘美術’이라는 한자가 붙어 있네.”"},{"who":"친구 3","text":"“‘벤치’라는 낱말 뒤에는 ‘bench’라는 영어가 붙어 있는데, ‘시나브로’와 ‘군침’ 뒤에는 아무것도 붙어 있지 않아.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L02_basic#4','kor',6,2,'u4','L02','tb_g6_2_kor_u4_L02_basic','lesson_basic','K6-2-u4-C7',1,'mc','auto','㉮ 대화에서 쓰인 “눈도 깜짝 안 하다.”의 뜻은 무엇인가요?',ARRAY['K6-2-u4-X09']::text[],false,'{"seq":4,"concept":"K6-2-u4-C7","difficulty":1,"kind":"mc","stem":"㉮ 대화에서 쓰인 “눈도 깜짝 안 하다.”의 뜻은 무엇인가요?","options":[{"t":"조금도 놀라지 않고 태연하다","correct":true},{"t":"눈을 오랫동안 감고 있다","mis":"K6-2-u4-X09"},{"t":"눈이 아파 깜빡이지 못하다","mis":"K6-2-u4-X09"},{"t":"깜짝 놀라서 눈을 크게 뜨다","mis":"K6-2-u4-X09"}],"explanation":["치과 치료를 받을 때 놀라지 않았냐는 물음에 한 대답이에요.","“눈도 깜짝 안 하다.”는 조금도 놀라지 않고 태연하다는 뜻이에요.","낱말 뜻을 하나씩 더해서는 이 뜻이 나오지 않아요."],"asset":{"type":"speech","turns":[{"who":"㉮ 친구 1","text":"“치과 치료를 받을 때 놀라지 않았어?”"},{"who":"㉮ 친구 2","text":"“응, 눈도 깜짝 안 했어.”"},{"who":"㉯ 친구 1","text":"“학교 알뜰 장터에서 무엇을 샀어?”"},{"who":"㉯ 친구 2","text":"“예쁜 물건은 날개 돋친 듯이 팔려 나가서 이걸 겨우 샀어.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L02_basic#5','kor',6,2,'u4','L02','tb_g6_2_kor_u4_L02_basic','lesson_basic','K6-2-u4-C6',2,'mc','auto','『국어』 186쪽 4번 (1)에서 한자어 ‘계주’를 고유어를 살려 다듬은 말은 무엇인가요?',ARRAY['K6-2-u4-X08']::text[],false,'{"seq":5,"concept":"K6-2-u4-C6","difficulty":2,"kind":"mc","stem":"『국어』 186쪽 4번 (1)에서 한자어 ‘계주’를 고유어를 살려 다듬은 말은 무엇인가요?","options":[{"t":"이어달리기","correct":true},{"t":"릴레이","mis":"K6-2-u4-X08"},{"t":"계속 달리기","mis":"K6-2-u4-X08"},{"t":"달리기 대회","mis":"K6-2-u4-X08"}],"explanation":["‘계주’는 한자어예요.","여러 명이 차례대로 이어서 달리는 활동이라 ‘이어달리기’로 다듬었어요.","외래어 ‘릴레이’로 바꾸는 것은 고유어로 다듬은 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L02_basic#6','kor',6,2,'u4','L02','tb_g6_2_kor_u4_L02_basic','lesson_basic','K6-2-u4-C20',2,'mc','auto','「고유어의 가치」에서 고유어를 바탕으로 만들어진 낱말로 든 것은 무엇인가요?',ARRAY['K6-2-u4-X06','K6-2-u4-X01']::text[],false,'{"seq":6,"concept":"K6-2-u4-C20","difficulty":2,"kind":"mc","stem":"「고유어의 가치」에서 고유어를 바탕으로 만들어진 낱말로 든 것은 무엇인가요?","options":[{"t":"떡볶이, 낚싯대, 할미꽃","correct":true},{"t":"어버이, 하늘, 아름답다","mis":"K6-2-u4-X06"},{"t":"미술, 수업, 친구","mis":"K6-2-u4-X01"},{"t":"피자, 벤치, 스티커","mis":"K6-2-u4-X01"}],"explanation":["글에서 ‘어버이’, ‘하늘’, ‘아름답다’는 오래전부터 있던 낱말이라고 했어요.","‘떡볶이’, ‘낚싯대’, ‘할미꽃’은 고유어를 바탕으로 만들어진 낱말이에요.","두 가지 모두 고유어예요."],"asset":{"type":"passage","lines":["우리가 사용하는 낱말을 분류하면 크게 고유어, 한자어, 외래어로 가를 수 있다.","(간추림) ‘어버이’, ‘하늘’, ‘아름답다’는 오래전부터 있던 낱말이다.","(간추림) ‘떡볶이’, ‘낚싯대’, ‘할미꽃’은 고유어를 바탕으로 만들어진 낱말이다.","(간추림) 국어사전에서 ‘하늘’을 찾으면 한글 표기만 볼 수 있다.","이렇게 한글 표기만 있는 낱말이 바로 고유어이다."],"title":"「고유어의 가치」 앞부분 — 『국어』 184쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L02_basic#7','kor',6,2,'u4','L02','tb_g6_2_kor_u4_L02_basic','lesson_basic','K6-2-u4-C19',2,'mc','auto','『국어』 183쪽 2번 (2)의 낱말을 사전에서 찾아보았어요. 고유어만 모두 고른 것은 무엇인가요?',ARRAY['K6-2-u4-X01','K6-2-u4-X05']::text[],false,'{"seq":7,"concept":"K6-2-u4-C19","difficulty":2,"kind":"mc","stem":"『국어』 183쪽 2번 (2)의 낱말을 사전에서 찾아보았어요. 고유어만 모두 고른 것은 무엇인가요?","options":[{"t":"모둠, 줄넘기, 벌개미취, 둘레","correct":true},{"t":"수업, 친구, 둘레","mis":"K6-2-u4-X01"},{"t":"피자, 모둠, 줄넘기","mis":"K6-2-u4-X01"},{"t":"수업, 피자, 친구","mis":"K6-2-u4-X05"}],"explanation":["사전에서 한글 표기만 있는 낱말을 찾아요.","‘모둠, 줄넘기, 벌개미취, 둘레’가 고유어예요.","‘수업, 친구’는 한자어, ‘피자’는 외래어예요."],"asset":{"type":"passage","lines":["수업 · 피자 · 친구 · 둘레 · 모둠 · 줄넘기 · 벌개미취"],"title":"『국어』 183쪽 2번 (2) — 사전에서 찾아볼 낱말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L02_basic#8','kor',6,2,'u4','L02','tb_g6_2_kor_u4_L02_basic','lesson_basic','K6-2-u4-C20',2,'blank','auto','「고유어의 가치」에서 “고유어로 이루어진 관용 표현은 우리 고유의 (     )을/를 잘 보여 준다.”라고 했어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K6-2-u4-X32','K6-2-u4-X03','K6-2-u4-X01']::text[],false,'{"seq":8,"concept":"K6-2-u4-C20","difficulty":2,"kind":"blank","stem":"「고유어의 가치」에서 “고유어로 이루어진 관용 표현은 우리 고유의 (     )을/를 잘 보여 준다.”라고 했어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"문화와 정서","correct":true},{"t":"짧은 글자 수","mis":"K6-2-u4-X32"},{"t":"외국어의 멋","mis":"K6-2-u4-X03"},{"t":"한자의 뜻","mis":"K6-2-u4-X01"}],"explanation":["글에서 “눈도 깜짝 안 하다.”, “날개 돋치다.”를 예로 들었어요.","이런 관용 표현은 우리 고유의 문화와 정서를 잘 보여 줘요.","『국어』 185쪽 3번 (2)의 답이에요."],"asset":{"type":"passage","lines":["(간추림) “눈도 깜짝 안 하다.”, “날개 돋치다.” 같은 고유어 관용 표현은","(간추림) 우리 고유의 문화와 정서를 잘 보여 준다.","(간추림) ‘새우잠’, ‘샛길’, ‘함박눈’, ‘도랑’은 뜻을 쉽게 짐작할 수 있다.","(간추림) 그러면서도 사용할 때 아름다운 느낌을 준다.","(간추림) ‘새우잠’은 새우처럼 등을 구부리고 자는 듯한 모습을 비유적으로 알려 준다.","(간추림) 고유어는 우리말의 기본 바탕을 이루고 있다."],"title":"「고유어의 가치」 뒷부분 — 『국어』 184쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L02_basic#9','kor',6,2,'u4','L02','tb_g6_2_kor_u4_L02_basic','lesson_basic','K6-2-u4-C5',2,'mc','auto','「고유어의 가치」에서 ‘새우잠’, ‘샛길’, ‘함박눈’, ‘도랑’을 예로 들어 말한 고유어의 가치는 무엇인가요?',ARRAY['K6-2-u4-X06','K6-2-u4-X32','K6-2-u4-X07']::text[],false,'{"seq":9,"concept":"K6-2-u4-C5","difficulty":2,"kind":"mc","stem":"「고유어의 가치」에서 ‘새우잠’, ‘샛길’, ‘함박눈’, ‘도랑’을 예로 들어 말한 고유어의 가치는 무엇인가요?","options":[{"t":"뜻을 쉽게 짐작할 수 있으면서도 사용할 때 아름다운 느낌을 준다","correct":true},{"t":"옛날에만 쓰던 말이라 지금은 귀하게 모셔 두어야 한다","mis":"K6-2-u4-X06"},{"t":"글자 수가 적어 다른 말보다 빨리 쓸 수 있다","mis":"K6-2-u4-X32"},{"t":"한자어보다 훌륭한 말이라 높이 쳐야 한다","mis":"K6-2-u4-X07"}],"explanation":["‘새우잠’은 새우처럼 등을 구부리고 자는 모습을 떠올리게 해요.","그래서 뜻을 쉽게 짐작할 수 있어요.","말에 담긴 아름다움도 느낄 수 있어요."],"asset":{"type":"passage","lines":["(간추림) “눈도 깜짝 안 하다.”, “날개 돋치다.” 같은 고유어 관용 표현은","(간추림) 우리 고유의 문화와 정서를 잘 보여 준다.","(간추림) ‘새우잠’, ‘샛길’, ‘함박눈’, ‘도랑’은 뜻을 쉽게 짐작할 수 있다.","(간추림) 그러면서도 사용할 때 아름다운 느낌을 준다.","(간추림) ‘새우잠’은 새우처럼 등을 구부리고 자는 듯한 모습을 비유적으로 알려 준다.","(간추림) 고유어는 우리말의 기본 바탕을 이루고 있다."],"title":"「고유어의 가치」 뒷부분 — 『국어』 184쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L02_basic#10','kor',6,2,'u4','L02','tb_g6_2_kor_u4_L02_basic','lesson_basic','K6-2-u4-C6',3,'mc','auto','‘리플’을 ‘댓글’로 다듬은 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u4-X02','K6-2-u4-X08','K6-2-u4-X06']::text[],false,'{"seq":10,"concept":"K6-2-u4-C6","difficulty":3,"kind":"mc","stem":"‘리플’을 ‘댓글’로 다듬은 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"원래 있던 글에 의견을 달아 주는 글이라는 뜻이 잘 드러나기 때문","correct":true},{"t":"외래어는 모두 나쁜 말이라 우리말에서 몰아내야 해서","mis":"K6-2-u4-X02"},{"t":"글자 수를 줄여 더 빨리 쓰고 읽기 위해서","mis":"K6-2-u4-X08"},{"t":"‘리플’보다 ‘댓글’이 더 옛날부터 쓰던 말이라서","mis":"K6-2-u4-X06"}],"explanation":["‘댓글’은 글에 대어 다는 글이라는 뜻이 잘 보여요.","고유어를 살리면 누구나 뜻을 쉽게 알 수 있어요.","다듬기는 외래어를 미워해서가 아니라 알아듣기 쉽게 하려는 것이에요."],"asset":{"type":"passage","lines":["리플 → 댓글","계주 → 이어달리기","스티커 → 붙임딱지","서클 → 동아리"],"title":"고유어를 살려 다듬은 사례 — 『국어』 186쪽 4번 (1)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L02_challenge#1','kor',6,2,'u4','L02','tb_g6_2_kor_u4_L02_challenge','lesson_challenge','K6-2-u4-C6',2,'match','auto','『국어』 186쪽 4번 (1)이에요. 한자어나 외래어와 고유어를 살려 다듬은 말을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u4-C6","difficulty":2,"kind":"match","stem":"『국어』 186쪽 4번 (1)이에요. 한자어나 외래어와 고유어를 살려 다듬은 말을 알맞게 이으세요.","pairs":[{"l":"리플","r":"댓글"},{"l":"계주","r":"이어달리기"},{"l":"스티커","r":"붙임딱지"},{"l":"서클","r":"동아리"}],"mis":"K6-2-u4-X08","explanation":["‘계주’는 한자어, ‘리플’·‘스티커’·‘서클’은 외래어예요.","고유어를 살려 뜻이 잘 드러나게 다듬었어요.","‘서클’은 함께 모여 활동하는 모임이라 ‘동아리’로 다듬었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L02_challenge#2','kor',6,2,'u4','L02','tb_g6_2_kor_u4_L02_challenge','lesson_challenge','K6-2-u4-C7',2,'mc','auto','㉯ 대화의 “날개 돋친 듯이 팔려 나가서”에서 ‘날개 돋치다’의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u4-X09']::text[],false,'{"seq":2,"concept":"K6-2-u4-C7","difficulty":2,"kind":"mc","stem":"㉯ 대화의 “날개 돋친 듯이 팔려 나가서”에서 ‘날개 돋치다’의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"상품이 빠른 속도로 팔려 나가다","correct":true},{"t":"물건에 날개를 달아 팔다","mis":"K6-2-u4-X09"},{"t":"새 모양 물건만 팔리다","mis":"K6-2-u4-X09"},{"t":"물건이 하나도 팔리지 않다","mis":"K6-2-u4-X09"}],"explanation":["예쁜 물건이 빨리 팔려서 겨우 샀다는 말이에요.","‘날개 돋치다’는 상품이 빠른 속도로 팔려 나간다는 뜻이에요.","관용 표현은 글자 그대로 풀이하지 않아요."],"asset":{"type":"speech","turns":[{"who":"㉮ 친구 1","text":"“치과 치료를 받을 때 놀라지 않았어?”"},{"who":"㉮ 친구 2","text":"“응, 눈도 깜짝 안 했어.”"},{"who":"㉯ 친구 1","text":"“학교 알뜰 장터에서 무엇을 샀어?”"},{"who":"㉯ 친구 2","text":"“예쁜 물건은 날개 돋친 듯이 팔려 나가서 이걸 겨우 샀어.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L02_challenge#3','kor',6,2,'u4','L02','tb_g6_2_kor_u4_L02_challenge','lesson_challenge','K6-2-u4-C4',3,'mc','auto','『국어』 183쪽 2번 (2)의 낱말을 사전에서 찾은 결과를 바르게 말한 것은 무엇인가요?',ARRAY['K6-2-u4-X01','K6-2-u4-X05']::text[],false,'{"seq":3,"concept":"K6-2-u4-C4","difficulty":3,"kind":"mc","stem":"『국어』 183쪽 2번 (2)의 낱말을 사전에서 찾은 결과를 바르게 말한 것은 무엇인가요?","options":[{"t":"‘수업’·‘친구’는 한자가, ‘피자’는 외국어가 함께 있어 한자어·외래어이다","correct":true},{"t":"‘친구’는 자주 쓰는 말이니 사전을 찾지 않아도 고유어이다","mis":"K6-2-u4-X01"},{"t":"‘피자’는 급식에 자주 나오니 우리말인 고유어이다","mis":"K6-2-u4-X01"},{"t":"‘모둠’은 소리가 낯서니 외국에서 들어온 외래어이다","mis":"K6-2-u4-X05"}],"explanation":["갈래는 자주 쓰는지, 소리가 어떤지로 정하지 않아요.","사전에서 낱말 뒤에 무엇이 붙어 있는지 확인해요.","한자가 있으면 한자어, 외국어가 있으면 외래어, 한글만 있으면 고유어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L02_challenge#4','kor',6,2,'u4','L02','tb_g6_2_kor_u4_L02_challenge','lesson_challenge','K6-2-u4-C20',3,'mc','auto','「고유어의 가치」에서 고유어를 사랑해야 하는 까닭으로 든 것은 무엇인가요?',ARRAY['K6-2-u4-X02','K6-2-u4-X07','K6-2-u4-X06']::text[],false,'{"seq":4,"concept":"K6-2-u4-C20","difficulty":3,"kind":"mc","stem":"「고유어의 가치」에서 고유어를 사랑해야 하는 까닭으로 든 것은 무엇인가요?","options":[{"t":"고유어가 우리말의 기본 바탕을 이루고 있기 때문","correct":true},{"t":"고유어만 바른 우리말이기 때문","mis":"K6-2-u4-X02"},{"t":"한자어와 외래어는 틀린 말이기 때문","mis":"K6-2-u4-X07"},{"t":"고유어는 옛날 말이라 지켜야 하기 때문","mis":"K6-2-u4-X06"}],"explanation":["글은 고유어가 우리말의 기본 바탕을 이룬다고 했어요.","그래서 한자어와 외래어를 대신할 고유어를 찾아보자고 했어요.","『국어』 185쪽 3번 (3)의 답이에요."],"asset":{"type":"passage","lines":["(간추림) “눈도 깜짝 안 하다.”, “날개 돋치다.” 같은 고유어 관용 표현은","(간추림) 우리 고유의 문화와 정서를 잘 보여 준다.","(간추림) ‘새우잠’, ‘샛길’, ‘함박눈’, ‘도랑’은 뜻을 쉽게 짐작할 수 있다.","(간추림) 그러면서도 사용할 때 아름다운 느낌을 준다.","(간추림) ‘새우잠’은 새우처럼 등을 구부리고 자는 듯한 모습을 비유적으로 알려 준다.","(간추림) 고유어는 우리말의 기본 바탕을 이루고 있다."],"title":"「고유어의 가치」 뒷부분 — 『국어』 184쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L02_challenge#5','kor',6,2,'u4','L02','tb_g6_2_kor_u4_L02_challenge','lesson_challenge','K6-2-u4-C5',3,'error','auto','고유어의 가치를 탐구하며 친구들이 나눈 말이에요. 알맞지 않은 것은 무엇인가요?',ARRAY['K6-2-u4-X32','K6-2-u4-X37','K6-2-u4-X09']::text[],false,'{"seq":5,"concept":"K6-2-u4-C5","difficulty":3,"kind":"error","stem":"고유어의 가치를 탐구하며 친구들이 나눈 말이에요. 알맞지 않은 것은 무엇인가요?","options":[{"t":"㉰ “고유어의 가치는 옛날 말이라는 것 하나뿐이야.”","correct":true,"mis_target":"K6-2-u4-X32"},{"t":"㉮ “‘함박눈’에는 굵고 탐스럽게 내리는 모양이 생동감 있게 담겨 있어.”","mis":"K6-2-u4-X37"},{"t":"㉯ “고유어 관용 표현은 짧으면서도 뜻을 효과적으로 나타내.”","mis":"K6-2-u4-X09"}],"explanation":["고유어의 가치는 한 가지가 아니에요.","뜻을 쉽게 짐작함, 아름다운 느낌, 문화와 정서, 우리말의 바탕 같은 여러 가치가 있어요.","고유어는 옛말만이 아니라 지금도 만들어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L02_challenge#6','kor',6,2,'u4','L02','tb_g6_2_kor_u4_L02_challenge','lesson_challenge','K6-2-u4-C7',3,'mc','auto','“눈도 깜짝 안 하다.”와 그 뜻인 “조금도 놀라지 않고 태연하다.”를 비교했어요. 고유어 관용 표현의 특징으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u4-X09','K6-2-u4-X32','K6-2-u4-X01']::text[],false,'{"seq":6,"concept":"K6-2-u4-C7","difficulty":3,"kind":"mc","stem":"“눈도 깜짝 안 하다.”와 그 뜻인 “조금도 놀라지 않고 태연하다.”를 비교했어요. 고유어 관용 표현의 특징으로 알맞은 것은 무엇인가요?","options":[{"t":"뜻을 모두 담으면서도 누군가의 표정까지 함께 나타낸다","correct":true},{"t":"낱말 뜻을 하나씩 더하면 뜻이 그대로 나온다","mis":"K6-2-u4-X09"},{"t":"뜻을 풀어 쓴 말보다 길고 어렵다","mis":"K6-2-u4-X32"},{"t":"외국에서 들어온 표현이라 낯설다","mis":"K6-2-u4-X01"}],"explanation":["눈 하나 깜빡이지 않는 얼굴이 떠올라요.","짧은 표현에 뜻과 표정이 함께 담겨 있어요.","이것이 고유어 관용 표현의 좋은 점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L02_challenge#7','kor',6,2,'u4','L02','tb_g6_2_kor_u4_L02_challenge','lesson_challenge','K6-2-u4-C19',3,'mc','auto','「세린이의 즐거운 하루」는 어떤 글인가요?',ARRAY['K6-2-u4-X37']::text[],false,'{"seq":7,"concept":"K6-2-u4-C19","difficulty":3,"kind":"mc","stem":"「세린이의 즐거운 하루」는 어떤 글인가요?","options":[{"t":"세린이의 하루 생활을 시간 순서대로 이야기하는 글","correct":true},{"t":"세린이가 꾼 꿈을 이야기하는 글","mis":"K6-2-u4-X37"},{"t":"고유어의 뜻을 차례대로 설명하는 글","mis":"K6-2-u4-X37"},{"t":"세린이와 지유가 다툰 일을 이야기하는 글","mis":"K6-2-u4-X37"}],"explanation":["미술 시간, 점심시간, 운동장, 수업이 끝난 뒤 차례로 이야기해요.","세린이의 하루 생활을 시간 순서대로 썼어요.","이 글에 나온 여러 낱말의 갈래를 살펴보았어요."],"asset":{"type":"passage","lines":["(간추림) 수업이 끝나자 세린이는 지유와 자전거를 타고 호수 공원에 갔다.","(간추림) 야생화 공원 벤치에 앉아 구절초, 벌개미취, 쑥부쟁이를 보았다.","(간추림) 호수 공원 둘레의 자전거 길을 따라 자전거를 탔다.","“나도 그래. 가을바람이 시원해서 더 기분이 좋아.”"],"title":"「세린이의 즐거운 하루」 뒷부분 — 『국어』 182쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L02_challenge#8','kor',6,2,'u4','L02','tb_g6_2_kor_u4_L02_challenge','lesson_challenge','K6-2-u4-C5',4,'essay','teacher','『국어』 185쪽 3번 (4)의 ‘샛길’, ‘함박눈’, ‘도랑’ 가운데 하나를 골라 뜻을 쓰고, 그 낱말에서 느껴지는 고유어의 가치를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K6-2-u4-C5","difficulty":4,"kind":"essay","stem":"『국어』 185쪽 3번 (4)의 ‘샛길’, ‘함박눈’, ‘도랑’ 가운데 하나를 골라 뜻을 쓰고, 그 낱말에서 느껴지는 고유어의 가치를 쓰세요.","answer_guide":{"answer":"예: 도랑 — 매우 좁고 작은 개울. ‘도랑’에는 어디에서나 볼 수 있는 개울을 정겹고 아름답게 나타내려는 느낌이 담겨 있다. 뜻을 쉽게 짐작할 수 있고 부르기에도 정겹다.","scoring_points":["고른 낱말의 뜻을 바르게 썼는가(샛길 — 사이에 난 길 · 함박눈 — 굵고 탐스럽게 내리는 눈 · 도랑 — 매우 좁고 작은 개울)","그 낱말에서 느껴지는 가치를 썼는가","자신의 생각을 분명히 썼는가"]},"explanation":["세 낱말의 뜻은 국어사전에서 찾을 수 있어요.","낱말이 주는 느낌이나 모습을 떠올려요.","고유어의 가치는 하나로 정해져 있지 않아요."],"asset":{"type":"passage","lines":["(1) 국어사전에서 찾은 낱말이 고유어인지 어떻게 확인할 수 있나요?","(2) 고유어로 이루어진 관용 표현을 사용하면 좋은 점은 무엇인가요?","(3) 고유어를 사랑해야 하는 까닭은 무엇인가요?","(4) 고유어의 뜻을 국어사전에서 찾아 써 보세요. — 샛길 · 함박눈 · 도랑"],"numbered":false,"title":"『국어』 185쪽 3번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L02_challenge#9','kor',6,2,'u4','L02','tb_g6_2_kor_u4_L02_challenge','lesson_challenge','K6-2-u4-C6',4,'essay','teacher','『국어』 186쪽 4번 (1)의 다듬은 사례 가운데 하나를 골라, 다듬은 고유어에 어떤 뜻과 느낌이 담겼는지와 그렇게 다듬은 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u4-C6","difficulty":4,"kind":"essay","stem":"『국어』 186쪽 4번 (1)의 다듬은 사례 가운데 하나를 골라, 다듬은 고유어에 어떤 뜻과 느낌이 담겼는지와 그렇게 다듬은 까닭을 쓰세요.","answer_guide":{"answer":"예: 스티커 → 붙임딱지. 접착제가 있어 쉽게 붙일 수 있는 작은 조각이라는 뜻이 낱말에 그대로 드러난다. 외래어를 모르는 사람도 뜻을 쉽게 알 수 있게 하려고 다듬었을 것이다.","scoring_points":["다듬은 사례 하나를 바르게 골랐는가","고유어에 담긴 뜻이나 느낌을 썼는가","다듬은 까닭을 알아듣기 쉬움과 이어 썼는가"]},"explanation":["다듬은 고유어를 낱말로 나누어 뜻을 살펴요.","원래 낱말과 견주어 어떤 느낌이 드는지 생각해요.","다듬기는 누구나 알아듣게 하려는 것이에요."],"asset":{"type":"passage","lines":["리플 → 댓글","계주 → 이어달리기","스티커 → 붙임딱지","서클 → 동아리"],"title":"고유어를 살려 다듬은 사례 — 『국어』 186쪽 4번 (1)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L02_challenge#10','kor',6,2,'u4','L02','tb_g6_2_kor_u4_L02_challenge','lesson_challenge','K6-2-u4-C7',4,'essay','teacher','『국어』 187쪽 5번처럼 일상생활에서 고유어를 사용하면 좋은 까닭을 두 가지 쓰고, “눈도 깜짝 안 하다.”나 “날개 돋치다.”를 넣어 짧은 문장을 만드세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u4-C7","difficulty":4,"kind":"essay","stem":"『국어』 187쪽 5번처럼 일상생활에서 고유어를 사용하면 좋은 까닭을 두 가지 쓰고, “눈도 깜짝 안 하다.”나 “날개 돋치다.”를 넣어 짧은 문장을 만드세요.","answer_guide":{"answer":"예: 까닭 — ① 우리말을 더욱 아름답게 사용할 수 있다. ② 우리말이 담긴 관용 표현으로 전하고 싶은 생각이나 느낌을 효과적으로 표현할 수 있다. 문장 — 우리 반이 만든 쿠키가 날개 돋친 듯이 팔렸다.","scoring_points":["고유어를 사용하면 좋은 까닭을 두 가지 썼는가","관용 표현을 뜻에 맞게 넣어 문장을 만들었는가","문장이 자연스러운가"]},"explanation":["친구들이 말한 까닭을 떠올려요.","관용 표현의 뜻을 생각하며 알맞은 상황을 정해요.","뜻에 맞게 쓰였는지 다시 읽어 보아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L04_basic#1','kor',6,2,'u4','L04','tb_g6_2_kor_u4_L04_basic','lesson_basic','K6-2-u4-C8',1,'mc','auto','『국어』 189쪽 (4) 표에서 ‘아름동’의 고유어 ‘아름’의 뜻은 무엇인가요?',ARRAY['K6-2-u4-X18','K6-2-u4-X10']::text[],false,'{"seq":1,"concept":"K6-2-u4-C8","difficulty":1,"kind":"mc","stem":"『국어』 189쪽 (4) 표에서 ‘아름동’의 고유어 ‘아름’의 뜻은 무엇인가요?","options":[{"t":"두 팔을 둥글게 모아서 만든 둘레","correct":true},{"t":"아름다운 꽃이 피는 곳","mis":"K6-2-u4-X18"},{"t":"옛 우리말에서 큰 밭","mis":"K6-2-u4-X10"},{"t":"둥근 켜로 된 시루떡 덩어리 모양","mis":"K6-2-u4-X10"}],"explanation":["‘아름동’은 동네 이름이에요.","그 속 고유어 ‘아름’은 두 팔을 둥글게 모아서 만든 둘레라는 뜻이에요.","‘아름답다’와 소리가 비슷해도 뜻은 사전에서 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L04_basic#2','kor',6,2,'u4','L04','tb_g6_2_kor_u4_L04_basic','lesson_basic','K6-2-u4-C8',1,'mc','auto','『국어』 189쪽 (2)에서 일상생활 속 고유어를 활용한 사례로 든 것은 무엇인가요?',ARRAY['K6-2-u4-X10']::text[],false,'{"seq":2,"concept":"K6-2-u4-C8","difficulty":1,"kind":"mc","stem":"『국어』 189쪽 (2)에서 일상생활 속 고유어를 활용한 사례로 든 것은 무엇인가요?","options":[{"t":"안다미로, 비빔밥, 두레길","correct":true},{"t":"피자, 벤치, 스티커","mis":"K6-2-u4-X10"},{"t":"미술, 수업, 친구","mis":"K6-2-u4-X10"},{"t":"리플, 계주, 서클","mis":"K6-2-u4-X10"}],"explanation":["예시 답안은 ‘안다미로, 비빔밥, 두레길, 개나리, 찔레나무, 코끼리, 불고기, 나물’이에요.","가게, 음식, 길, 식물, 동물 이름에서 고유어를 찾았어요.","외래어나 한자어로 된 이름은 고유어 활용 사례가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L04_basic#3','kor',6,2,'u4','L04','tb_g6_2_kor_u4_L04_basic','lesson_basic','K6-2-u4-C9',1,'ox','auto','고유어를 활용한 사례를 조사한 내용은 ‘유형, 사례, 고유어, 고유어의 뜻’으로 정리해요.',ARRAY['K6-2-u4-X11']::text[],false,'{"seq":3,"concept":"K6-2-u4-C9","difficulty":1,"kind":"ox","stem":"고유어를 활용한 사례를 조사한 내용은 ‘유형, 사례, 고유어, 고유어의 뜻’으로 정리해요.","answer":"O","reason_options":[{"t":"『국어』 189쪽 (4)의 표처럼 네 칸으로 정리하면 사례를 한눈에 볼 수 있어요.","correct":true},{"t":"사례 이름만 많이 모으면 되고 뜻은 정리하지 않아도 돼요.","mis":"K6-2-u4-X11"}],"mis":"K6-2-u4-X11","explanation":["조사한 내용은 항목에 따라 정리해요.","유형, 사례, 고유어, 고유어의 뜻 네 칸이에요.","뜻까지 알아보아야 발표할 때 설명할 수 있어요."],"asset":{"type":"passage","lines":["[표] 유형 · 사례 · 고유어 · 고유어의 뜻","동네 이름 · 아름동 · 아름 · 두 팔을 둥글게 모아서 만든 둘레.","음식 · 비빔밥 · 비빔, 밥 · 고기나 나물 따위와 여러 가지 양념을 넣어 비벼 먹는 밥.","도로 · 두레길 · 두레, 길 · 두레: 둥근 켜로 된 시루떡 덩어리 모양."],"numbered":false,"title":"조사한 자료 정리 — 『국어』 189쪽 (4)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L04_basic#4','kor',6,2,'u4','L04','tb_g6_2_kor_u4_L04_basic','lesson_basic','K6-2-u4-C10',1,'mc','auto','『국어』 192쪽 (2)에서 친구가 발표한 ‘한밭수목원’의 고유어 ‘한밭’의 뜻은 무엇인가요?',ARRAY['K6-2-u4-X18','K6-2-u4-X10']::text[],false,'{"seq":4,"concept":"K6-2-u4-C10","difficulty":1,"kind":"mc","stem":"『국어』 192쪽 (2)에서 친구가 발표한 ‘한밭수목원’의 고유어 ‘한밭’의 뜻은 무엇인가요?","options":[{"t":"옛 우리말에서 ‘큰 밭’이란 뜻이다","correct":true},{"t":"한 개의 밭이라는 뜻이다","mis":"K6-2-u4-X18"},{"t":"밭이 없는 곳이라는 뜻이다","mis":"K6-2-u4-X18"},{"t":"두 팔을 둥글게 모아서 만든 둘레라는 뜻이다","mis":"K6-2-u4-X10"}],"explanation":["‘한밭’은 옛 우리말에서 ‘큰 밭’이란 뜻이에요.","친구는 장소 이름 속 고유어를 발표했어요.","듣는 사람은 새롭게 안 고유어와 그 뜻을 표에 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L04_basic#5','kor',6,2,'u4','L04','tb_g6_2_kor_u4_L04_basic','lesson_basic','K6-2-u4-C8',2,'mc','auto','『국어』 189쪽 (3)에서 “여러 낱말로 이루어진 사례도 있네.”라고 말한 뒤에 할 일로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u4-X10','K6-2-u4-X12']::text[],false,'{"seq":5,"concept":"K6-2-u4-C8","difficulty":2,"kind":"mc","stem":"『국어』 189쪽 (3)에서 “여러 낱말로 이루어진 사례도 있네.”라고 말한 뒤에 할 일로 알맞은 것은 무엇인가요?","options":[{"t":"각 사례 속 낱말을 꼼꼼히 나누어 살펴본다","correct":true},{"t":"이름 전체를 한 낱말로 보고 넘어간다","mis":"K6-2-u4-X10"},{"t":"외국어로 된 이름을 더 찾는다","mis":"K6-2-u4-X10"},{"t":"이름의 뜻을 마음대로 지어 쓴다","mis":"K6-2-u4-X12"}],"explanation":["‘두레길’은 ‘두레’와 ‘길’로 이루어졌어요.","여러 낱말로 이루어진 이름은 낱말을 나누어 살펴봐요.","나눈 낱말이 고유어인지 사전에서 확인해요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"“우리 학교 이름에 ‘꽃’과 ‘빛’이라는 고유어를 활용했어.”"},{"who":"친구 2","text":"“어제 먹은 ‘갈비찜’이 고유어인지 찾아봐야겠어.”"},{"who":"친구 3","text":"“여러 낱말로 이루어진 사례도 있네.”"},{"who":"친구 4","text":"“각 사례 속 낱말을 꼼꼼히 나누어 살펴봐야겠어.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L04_basic#6','kor',6,2,'u4','L04','tb_g6_2_kor_u4_L04_basic','lesson_basic','K6-2-u4-C9',2,'mc','auto','『국어』 188쪽 ‘계획하기’에서 조사 대상이나 범위를 정할 때 함께 생각해야 할 것은 무엇인가요?',ARRAY['K6-2-u4-X13','K6-2-u4-X11']::text[],false,'{"seq":6,"concept":"K6-2-u4-C9","difficulty":2,"kind":"mc","stem":"『국어』 188쪽 ‘계획하기’에서 조사 대상이나 범위를 정할 때 함께 생각해야 할 것은 무엇인가요?","options":[{"t":"국어사전이나 인터넷 검색처럼 알맞은 조사 방법","correct":true},{"t":"발표 자료를 꾸밀 색깔","mis":"K6-2-u4-X13"},{"t":"조사할 사례를 될 수 있는 대로 많게","mis":"K6-2-u4-X11"},{"t":"친구들이 좋아할 만한 그림","mis":"K6-2-u4-X13"}],"explanation":["조사 대상이나 범위를 정할 때는 조사 방법도 함께 정해요.","국어사전이나 인터넷 검색 등 다양한 방법이 있어요.","꾸미는 일은 내용을 정한 다음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L04_basic#7','kor',6,2,'u4','L04','tb_g6_2_kor_u4_L04_basic','lesson_basic','K6-2-u4-C10',2,'mc','auto','『국어』 191쪽 (2) 표에서 ‘노랫말에 사용된 고유어’를 발표할 때 컴퓨터를 매체로 고른 까닭은 무엇인가요?',ARRAY['K6-2-u4-X13','K6-2-u4-X27']::text[],false,'{"seq":7,"concept":"K6-2-u4-C10","difficulty":2,"kind":"mc","stem":"『국어』 191쪽 (2) 표에서 ‘노랫말에 사용된 고유어’를 발표할 때 컴퓨터를 매체로 고른 까닭은 무엇인가요?","options":[{"t":"직접 노래를 들려주어 친구들이 쉽게 이해할 수 있어서","correct":true},{"t":"화면이 화려해서 눈길을 끌 수 있어서","mis":"K6-2-u4-X13"},{"t":"발표할 내용과 상관없이 늘 쓰는 매체라서","mis":"K6-2-u4-X27"},{"t":"글자를 많이 넣을 수 있어서","mis":"K6-2-u4-X13"}],"explanation":["노랫말 속 고유어는 노래를 직접 들으면 잘 알 수 있어요.","컴퓨터로 노래를 들려주면 친구들의 이해를 도울 수 있어요.","매체는 발표할 내용에 맞게 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L04_basic#8','kor',6,2,'u4','L04','tb_g6_2_kor_u4_L04_basic','lesson_basic','K6-2-u4-C10',2,'mc','auto','발표 자료를 점검했더니 조사한 자료의 출처를 믿을 수 없었어요. 어떻게 해야 하나요?',ARRAY['K6-2-u4-X12','K6-2-u4-X13']::text[],false,'{"seq":8,"concept":"K6-2-u4-C10","difficulty":2,"kind":"mc","stem":"발표 자료를 점검했더니 조사한 자료의 출처를 믿을 수 없었어요. 어떻게 해야 하나요?","options":[{"t":"출처를 점검하고 믿을 만한 자료로 바꾼다","correct":true},{"t":"출처는 밝히지 않고 그대로 발표한다","mis":"K6-2-u4-X12"},{"t":"자료의 양을 더 늘린다","mis":"K6-2-u4-X13"},{"t":"매체를 더 화려한 것으로 바꾼다","mis":"K6-2-u4-X13"}],"explanation":["『국어』 191쪽 (3)의 첫째 점검 질문이에요.","출처가 믿을 만하지 않으면 믿을 만한 자료로 바꿔요.","믿을 만한 자료여야 친구들에게 바른 뜻을 전할 수 있어요."],"asset":{"type":"passage","lines":["① 조사한 자료의 출처는 믿을 만한가요?","→ 아니요: 출처를 점검하고 믿을 만한 자료로 바꿔요.","② 발표 자료의 양은 적절한가요?","→ 아니요: 발표 여건을 생각하며 발표 자료의 양을 줄이거나 추가해요.","③ 정한 매체는 발표에 효과적인가요?","→ 아니요: (                    )","모두 ‘예’ → 완성한 발표 자료를 다시 한번 살펴보고 발표를 준비해요."],"numbered":false,"title":"발표 자료 점검하기 — 『국어』 191쪽 (3)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L04_basic#9','kor',6,2,'u4','L04','tb_g6_2_kor_u4_L04_basic','lesson_basic','K6-2-u4-C10',2,'blank','auto','『국어』 190쪽 안내 “발표할 내용에 따라 활용할 (     )이/가 달라질 수 있어요.”에서 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K6-2-u4-X27','K6-2-u4-X13','K6-2-u4-X12']::text[],false,'{"seq":9,"concept":"K6-2-u4-C10","difficulty":2,"kind":"blank","stem":"『국어』 190쪽 안내 “발표할 내용에 따라 활용할 (     )이/가 달라질 수 있어요.”에서 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"매체","correct":true},{"t":"고유어","mis":"K6-2-u4-X27"},{"t":"발표 순서","mis":"K6-2-u4-X13"},{"t":"출처","mis":"K6-2-u4-X12"}],"explanation":["노래는 컴퓨터로, 도로 모양은 태블릿 피시로 보여 줄 수 있어요.","발표할 내용에 따라 알맞은 매체가 달라요.","종이 자료, 컴퓨터 화면, 태블릿 피시 가운데에서 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L04_basic#10','kor',6,2,'u4','L04','tb_g6_2_kor_u4_L04_basic','lesson_basic','K6-2-u4-C10',3,'mc','auto','발표를 마친 뒤 발표를 들은 학생이 할 일로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u4-X14']::text[],false,'{"seq":10,"concept":"K6-2-u4-C10","difficulty":3,"kind":"mc","stem":"발표를 마친 뒤 발표를 들은 학생이 할 일로 가장 알맞은 것은 무엇인가요?","options":[{"t":"정리한 내용을 바탕으로 궁금한 점이나 더 알고 싶은 점을 발표자에게 질문한다","correct":true},{"t":"발표가 끝났으니 조용히 다음 발표를 기다리기만 한다","mis":"K6-2-u4-X14"},{"t":"발표자의 목소리 크기와 자세만 보고 점수를 매긴다","mis":"K6-2-u4-X14"},{"t":"질문은 발표가 아니므로 궁금해도 하지 않고 넘어간다","mis":"K6-2-u4-X14"}],"explanation":["발표를 들을 때는 유형, 사례, 고유어, 뜻을 정리해요.","정리한 내용을 바탕으로 궁금한 점을 질문해요.","묻고 답하기까지 함께하면 고유어를 더 잘 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L04_challenge#1','kor',6,2,'u4','L04','tb_g6_2_kor_u4_L04_challenge','lesson_challenge','K6-2-u4-C8',2,'mc','auto','『국어』 192쪽 (2) 예시 답안처럼 ‘생생불고기’를 정리했어요. 알맞은 것은 무엇인가요?',ARRAY['K6-2-u4-X10']::text[],false,'{"seq":1,"concept":"K6-2-u4-C8","difficulty":2,"kind":"mc","stem":"『국어』 192쪽 (2) 예시 답안처럼 ‘생생불고기’를 정리했어요. 알맞은 것은 무엇인가요?","options":[{"t":"유형: 가게 이름 · 고유어: 불고기","correct":true},{"t":"유형: 장소 · 고유어: 생생","mis":"K6-2-u4-X10"},{"t":"유형: 음식 · 고유어: 생생불고기 전체","mis":"K6-2-u4-X10"},{"t":"유형: 도로 · 고유어: 고기","mis":"K6-2-u4-X10"}],"explanation":["‘생생불고기’는 가게 이름이에요.","그 속에서 고유어 ‘불고기’를 찾았어요.","불고기는 살코기를 저며 양념하여 재었다가 불에 구운 음식이에요."],"asset":{"type":"passage","lines":["[표] 유형 · 사례 · 고유어 · 고유어의 뜻","장소 · 한밭수목원 · 한밭 · 옛 우리말에서 ‘큰 밭’이란 뜻이다.","가게 이름 · 생생불고기 · 불고기 · 쇠고기 따위의 살코기를 저며 양념하여 재었다가 불에 구운 음식."],"numbered":false,"title":"친구의 발표에서 새롭게 안 고유어 — 『국어』 192쪽 (2)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L04_challenge#2','kor',6,2,'u4','L04','tb_g6_2_kor_u4_L04_challenge','lesson_challenge','K6-2-u4-C9',2,'mc','auto','『국어』 190쪽 (1)에서 “조사한 자료 가운데에서 동네 이름에 해당하는 것만 고르면 좋겠어.”라고 말한 친구가 하려는 일은 무엇인가요?',ARRAY['K6-2-u4-X11','K6-2-u4-X12','K6-2-u4-X13']::text[],false,'{"seq":2,"concept":"K6-2-u4-C9","difficulty":2,"kind":"mc","stem":"『국어』 190쪽 (1)에서 “조사한 자료 가운데에서 동네 이름에 해당하는 것만 고르면 좋겠어.”라고 말한 친구가 하려는 일은 무엇인가요?","options":[{"t":"조사한 자료에서 발표에 필요한 내용을 선택한다","correct":true},{"t":"조사한 자료를 모두 발표한다","mis":"K6-2-u4-X11"},{"t":"발표에 필요한 자료를 지어낸다","mis":"K6-2-u4-X12"},{"t":"매체부터 정하고 내용은 나중에 정한다","mis":"K6-2-u4-X13"}],"explanation":["발표 자료를 만들 때는 조사한 자료에서 필요한 내용을 골라요.","이 친구는 동네 이름만 골라 발표하려고 해요.","고른 내용에 맞는 매체를 정해요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"“조사한 자료 가운데에서 동네 이름에 해당하는 것만 고르면 좋겠어.”"},{"who":"친구 2","text":"“나는 뜻이 비슷한 고유어를 모으고 싶어.”"},{"who":"친구 3","text":"“발표할 고유어와 관련 있는 영상 자료를 추가하면 좋겠어.”"},{"who":"친구 4","text":"“발표할 고유어를 다른 문장에 넣어 설명하고 싶어.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L04_challenge#3','kor',6,2,'u4','L04','tb_g6_2_kor_u4_L04_challenge','lesson_challenge','K6-2-u4-C10',3,'match','auto','『국어』 191쪽 (3)이에요. 점검 질문과 ‘아니요’일 때 할 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":3,"concept":"K6-2-u4-C10","difficulty":3,"kind":"match","stem":"『국어』 191쪽 (3)이에요. 점검 질문과 ‘아니요’일 때 할 일을 알맞게 이으세요.","pairs":[{"l":"조사한 자료의 출처는 믿을 만한가요?","r":"출처를 점검하고 믿을 만한 자료로 바꿔요."},{"l":"발표 자료의 양은 적절한가요?","r":"발표 여건을 생각하며 양을 줄이거나 추가해요."},{"l":"정한 매체는 발표에 효과적인가요?","r":"이해하는 데 도움이 되는 매체로 바꿔요."}],"mis":"K6-2-u4-X13","explanation":["세 가지를 차례대로 점검해요.","‘아니요’이면 고친 뒤 다음 질문으로 가요.","모두 ‘예’이면 발표 자료를 다시 살펴보고 발표를 준비해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L04_challenge#4','kor',6,2,'u4','L04','tb_g6_2_kor_u4_L04_challenge','lesson_challenge','K6-2-u4-C10',3,'mc','auto','『국어』 191쪽 (2) 예시 답안에서 ‘도로 이름에 사용된 고유어’를 태블릿 피시로 발표하면 좋은 점은 무엇인가요?',ARRAY['K6-2-u4-X13','K6-2-u4-X14','K6-2-u4-X12']::text[],false,'{"seq":4,"concept":"K6-2-u4-C10","difficulty":3,"kind":"mc","stem":"『국어』 191쪽 (2) 예시 답안에서 ‘도로 이름에 사용된 고유어’를 태블릿 피시로 발표하면 좋은 점은 무엇인가요?","options":[{"t":"도로의 모양을 살펴보며 고유어의 뜻을 추론하게 할 수 있다","correct":true},{"t":"태블릿 피시가 가장 새로운 기계라서 좋다","mis":"K6-2-u4-X13"},{"t":"고유어의 뜻을 설명하지 않아도 된다","mis":"K6-2-u4-X14"},{"t":"자료의 출처를 밝히지 않아도 된다","mis":"K6-2-u4-X12"}],"explanation":["태블릿 피시로 도로의 모습을 보여 줄 수 있어요.","도로 모양을 보며 이름 속 고유어의 뜻을 짐작하게 할 수 있어요.","매체 사용 효과는 발표 내용과 이어져야 해요."],"asset":{"type":"passage","lines":["[표] 발표할 내용 · 매체 · 매체 사용 효과","노랫말에 사용된 고유어 · 컴퓨터 · 직접 노래를 들려주어 친구들이 쉽게 이해할 수 있음.","도로 이름에 사용된 고유어 · 태블릿 피시 · (          )"],"numbered":false,"title":"발표할 내용에 적합한 매체 — 『국어』 191쪽 (2)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L04_challenge#5','kor',6,2,'u4','L04','tb_g6_2_kor_u4_L04_challenge','lesson_challenge','K6-2-u4-C9',3,'error','auto','고유어를 활용한 사례를 조사하며 친구들이 한 말이에요. 알맞지 않은 것은 무엇인가요?',ARRAY['K6-2-u4-X05','K6-2-u4-X10']::text[],false,'{"seq":5,"concept":"K6-2-u4-C9","difficulty":3,"kind":"error","stem":"고유어를 활용한 사례를 조사하며 친구들이 한 말이에요. 알맞지 않은 것은 무엇인가요?","options":[{"t":"㉰ “‘갈비찜’은 익숙한 말이니 사전을 찾지 않고 고유어라고 정리할래.”","correct":true,"mis_target":"K6-2-u4-X05"},{"t":"㉮ “우리 학교 이름에 ‘꽃’과 ‘빛’이라는 고유어를 활용했어.”","mis":"K6-2-u4-X10"},{"t":"㉯ “각 사례 속 낱말을 꼼꼼히 나누어 살펴봐야겠어.”","mis":"K6-2-u4-X10"}],"explanation":["『국어』 189쪽에서 친구는 ‘갈비찜’이 고유어인지 찾아보겠다고 했어요.","익숙한 말이라도 갈래는 사전에서 확인해야 해요.","헷갈리는 낱말은 국어사전을 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L04_challenge#6','kor',6,2,'u4','L04','tb_g6_2_kor_u4_L04_challenge','lesson_challenge','K6-2-u4-C10',3,'mc','auto','『국어』 193쪽 ‘점검하기’ (1)에서 스스로 확인하는 내용이 아닌 것은 무엇인가요?',ARRAY['K6-2-u4-X13','K6-2-u4-X14']::text[],false,'{"seq":6,"concept":"K6-2-u4-C10","difficulty":3,"kind":"mc","stem":"『국어』 193쪽 ‘점검하기’ (1)에서 스스로 확인하는 내용이 아닌 것은 무엇인가요?","options":[{"t":"발표 자료를 가장 화려하게 꾸몄나요?","correct":true},{"t":"발표에 적절한 매체를 활용했나요?","mis":"K6-2-u4-X13"},{"t":"친구들이 고유어의 뜻을 이해할 수 있게 설명했나요?","mis":"K6-2-u4-X14"}],"explanation":["점검하기에서는 내용 고르기, 매체, 효과적인 발표, 뜻 설명을 확인해요.","화려하게 꾸몄는지는 점검 내용에 없어요.","계획부터 발표까지 전체 과정을 되돌아봐요."],"asset":{"type":"passage","lines":["발표에 필요한 내용을 골라 발표 자료를 제작했나요?","발표에 적절한 매체를 활용했나요?","친구들에게 고유어를 활용한 사례를 효과적으로 발표했나요?","친구들이 고유어의 뜻을 이해할 수 있게 설명했나요?"],"title":"점검하기 — 『국어』 193쪽 (1)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L04_challenge#7','kor',6,2,'u4','L04','tb_g6_2_kor_u4_L04_challenge','lesson_challenge','K6-2-u4-C10',3,'mc','auto','『국어』 193쪽 (2)에서 발표 과정에서 느낀 점을 고유어의 가치와 이어 말한 것은 무엇인가요?',ARRAY['K6-2-u4-X13','K6-2-u4-X14']::text[],false,'{"seq":7,"concept":"K6-2-u4-C10","difficulty":3,"kind":"mc","stem":"『국어』 193쪽 (2)에서 발표 과정에서 느낀 점을 고유어의 가치와 이어 말한 것은 무엇인가요?","options":[{"t":"“친구의 발표를 들으며 우리 지역의 역사가 고유어에 담겨 있다는 것을 알아서 좋았어.”","correct":true},{"t":"“발표 시간이 다른 모둠보다 짧아서 일찍 끝나 좋았어.”","mis":"K6-2-u4-X13"},{"t":"“내 발표 자료가 제일 화려하고 색깔이 예뻐서 좋았어.”","mis":"K6-2-u4-X13"},{"t":"“발표를 빨리 끝내고 쉬는 시간을 오래 가져서 좋았어.”","mis":"K6-2-u4-X14"}],"explanation":["느낀 점은 고유어의 가치와 이어 이야기해요.","고유어에 지역의 역사가 담겨 있다는 것은 고유어의 가치예요.","발표 시간이나 꾸밈은 고유어의 가치와 상관없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L04_challenge#8','kor',6,2,'u4','L04','tb_g6_2_kor_u4_L04_challenge','lesson_challenge','K6-2-u4-C9',4,'essay','teacher','내 주변에서 고유어를 활용한 사례를 조사하려고 해요. 조사 대상과 범위, 조사 방법을 정하고, 조사한 내용을 어떤 칸으로 정리할지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K6-2-u4-C9","difficulty":4,"kind":"essay","stem":"내 주변에서 고유어를 활용한 사례를 조사하려고 해요. 조사 대상과 범위, 조사 방법을 정하고, 조사한 내용을 어떤 칸으로 정리할지 쓰세요.","answer_guide":{"answer":"예: 조사 대상 — 우리 동네 가게 이름 / 범위 — 학교 앞 큰길에 있는 가게 / 방법 — 국어사전과 믿을 만한 누리집에서 확인 / 정리 — 유형, 사례, 고유어, 고유어의 뜻 네 칸.","scoring_points":["조사 대상과 범위를 알맞게 정했는가","국어사전 등 확인할 수 있는 조사 방법을 썼는가","유형, 사례, 고유어, 고유어의 뜻으로 정리하겠다고 썼는가"]},"explanation":["조사 범위는 직접 살펴볼 수 있게 정해요.","조사 방법도 함께 정해요.","『국어』 189쪽 (4)의 표처럼 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L04_challenge#9','kor',6,2,'u4','L04','tb_g6_2_kor_u4_L04_challenge','lesson_challenge','K6-2-u4-C10',4,'essay','teacher','『국어』 191쪽 (2)의 표처럼 발표할 내용을 하나 정하고, 알맞은 매체와 그 매체를 쓰면 좋은 점을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u4-C10","difficulty":4,"kind":"essay","stem":"『국어』 191쪽 (2)의 표처럼 발표할 내용을 하나 정하고, 알맞은 매체와 그 매체를 쓰면 좋은 점을 쓰세요.","answer_guide":{"answer":"예: 발표할 내용 — 우리 동네 길 이름에 쓰인 고유어 / 매체 — 컴퓨터 프레젠테이션 / 매체 사용 효과 — 길 사진과 지도를 함께 보여 주어 친구들이 고유어의 뜻을 쉽게 떠올릴 수 있다.","scoring_points":["발표할 내용을 정했는가","내용에 알맞은 매체를 골랐는가","매체 사용 효과를 내용과 이어 썼는가"]},"explanation":["먼저 발표할 내용을 정해요.","그 내용을 가장 잘 보여 줄 매체를 골라요.","매체가 듣는 사람에게 어떤 도움이 되는지 써요."],"asset":{"type":"passage","lines":["[표] 발표할 내용 · 매체 · 매체 사용 효과","노랫말에 사용된 고유어 · 컴퓨터 · 직접 노래를 들려주어 친구들이 쉽게 이해할 수 있음.","도로 이름에 사용된 고유어 · 태블릿 피시 · (          )"],"numbered":false,"title":"발표할 내용에 적합한 매체 — 『국어』 191쪽 (2)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L04_challenge#10','kor',6,2,'u4','L04','tb_g6_2_kor_u4_L04_challenge','lesson_challenge','K6-2-u4-C8',4,'essay','teacher','가족과 관련 있는 고유어 가운데 하나를 골라 뜻을 쓰고, 그 낱말을 넣어 문장을 만드세요. 그리고 친구들 앞에서 발표할 때 뜻을 잘 전할 방법을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u4-C8","difficulty":4,"kind":"essay","stem":"가족과 관련 있는 고유어 가운데 하나를 골라 뜻을 쓰고, 그 낱말을 넣어 문장을 만드세요. 그리고 친구들 앞에서 발표할 때 뜻을 잘 전할 방법을 쓰세요.","answer_guide":{"answer":"예: 띠앗 — 형제나 자매 사이의 우애심. 문장 — 동생과의 띠앗이 참 좋구나. 발표 방법 — 동생과 사이좋게 지내는 사진을 보여 주며 뜻을 설명하고, 문장에 넣어 한 번 더 들려준다.","scoring_points":["고유어의 뜻을 바르게 썼는가","뜻에 맞게 문장을 만들었는가","뜻을 잘 전할 발표 방법을 썼는가"]},"explanation":["고유어의 뜻은 사전 풀이를 그대로 옮겨요.","뜻에 맞는 상황을 떠올려 문장을 만들어요.","듣는 사람이 이해할 수 있게 설명할 방법을 생각해요."],"asset":{"type":"passage","lines":["내리사랑 — 손윗사람이 손아랫사람을 사랑하는 것.","치사랑 — 손아랫사람이 손윗사람을 사랑하는 것.","안갚음 — 자식이 커서 부모를 봉양하는 일.","도탑다 — 사랑이나 인정이 많고 깊다.","띠앗 — 형제나 자매 사이의 우애심.","꽃등 — 맨 처음."],"title":"가족과 관련 있는 고유어(『표준국어대사전』)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L06_basic#1','kor',6,2,'u4','L06','tb_g6_2_kor_u4_L06_basic','lesson_basic','K6-2-u4-C21',1,'mc','auto','「큰사전이 필요하다」에서 주시경이 ‘보퉁이 선생님’으로 불린 까닭은 무엇인가요?',ARRAY['K6-2-u4-X30']::text[],false,'{"seq":1,"concept":"K6-2-u4-C21","difficulty":1,"kind":"mc","stem":"「큰사전이 필요하다」에서 주시경이 ‘보퉁이 선생님’으로 불린 까닭은 무엇인가요?","options":[{"t":"조선어책을 항상 보퉁이에 싸서 들고 다녀서","correct":true},{"t":"보자기를 파는 가게를 해서","mis":"K6-2-u4-X30"},{"t":"학생들에게 보자기를 나누어 주어서","mis":"K6-2-u4-X30"},{"t":"늘 큰 가방을 메고 운동을 해서","mis":"K6-2-u4-X30"}],"explanation":["학생들은 늘 책 꾸러미를 들고 다니는 그를 보퉁이 선생님이라 불렀어요.","보퉁이는 물건을 보자기에 싸서 꾸려 놓은 것이에요.","『국어』 201쪽 4번 (1)의 답이에요."],"asset":{"type":"passage","lines":["“저기 보퉁이 선생님 오신다.”","(간추림) 학생들은 늘 조선어책을 들고 다니는 그를 ‘보퉁이 선생님’이라 불렀다.","(간추림) 그가 근대 한국어 연구의 아버지, 주시경이다.","(간추림) 집안은 가난했지만 한글 연구에 필요한 책은 천금을 마다하고 샀다.","[낱말] 보퉁이 — 물건을 보자기에 싸서 꾸려 놓은 것."],"numbered":false,"title":"「큰사전이 필요하다」 보퉁이 선생님 — 『국어』 195쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L06_basic#2','kor',6,2,'u4','L06','tb_g6_2_kor_u4_L06_basic','lesson_basic','K6-2-u4-C21',1,'mc','auto','「큰사전이 필요하다」에서 조선어학회의 두 가지 목표는 무엇이었나요?',ARRAY['K6-2-u4-X30']::text[],false,'{"seq":2,"concept":"K6-2-u4-C21","difficulty":1,"kind":"mc","stem":"「큰사전이 필요하다」에서 조선어학회의 두 가지 목표는 무엇이었나요?","options":[{"t":"문맹 퇴치 운동과 한글 사전의 편찬","correct":true},{"t":"일본어 교육과 외국 유학","mis":"K6-2-u4-X30"},{"t":"신문 발행과 학교 세우기","mis":"K6-2-u4-X30"},{"t":"한자 교육과 역사책 편찬","mis":"K6-2-u4-X30"}],"explanation":["첫째는 글을 모르는 민중에게 한글을 가르치는 문맹 퇴치 운동이에요.","둘째는 주시경의 뜻을 이은 한글 사전의 편찬이에요.","『국어』 201쪽 4번 (2)의 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L06_basic#3','kor',6,2,'u4','L06','tb_g6_2_kor_u4_L06_basic','lesson_basic','K6-2-u4-C13',1,'mc','auto','『국어』 205쪽에서 말한 ‘표준어’의 뜻은 무엇인가요?',ARRAY['K6-2-u4-X19','K6-2-u4-X33','K6-2-u4-X06']::text[],false,'{"seq":3,"concept":"K6-2-u4-C13","difficulty":1,"kind":"mc","stem":"『국어』 205쪽에서 말한 ‘표준어’의 뜻은 무엇인가요?","options":[{"t":"우리나라 사람들이 공통으로 사용하도록 정한 말","correct":true},{"t":"특정 지역에서 주로 사용하는 표준어가 아닌 말","mis":"K6-2-u4-X19"},{"t":"서울에 사는 사람들만 쓰도록 정한 말","mis":"K6-2-u4-X33"},{"t":"옛날에 쓰다가 지금은 쓰지 않는 말","mis":"K6-2-u4-X06"}],"explanation":["표준어는 우리나라 사람들이 공통으로 사용하도록 정한 말이에요.","특정 지역에서 주로 사용하며 표준어가 아닌 말은 방언이에요.","두 말 모두 소중한 우리말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L06_basic#4','kor',6,2,'u4','L06','tb_g6_2_kor_u4_L06_basic','lesson_basic','K6-2-u4-C22',1,'mc','auto','『국어』 201쪽 3번이에요. “배우지 못하여 글을 읽거나 쓸 줄을 모름. 또는 그런 사람.”이라는 뜻의 낱말은 무엇인가요?',ARRAY['K6-2-u4-X31']::text[],false,'{"seq":4,"concept":"K6-2-u4-C22","difficulty":1,"kind":"mc","stem":"『국어』 201쪽 3번이에요. “배우지 못하여 글을 읽거나 쓸 줄을 모름. 또는 그런 사람.”이라는 뜻의 낱말은 무엇인가요?","options":[{"t":"문맹","correct":true},{"t":"절호","mis":"K6-2-u4-X31"},{"t":"천금","mis":"K6-2-u4-X31"},{"t":"섣부르다","mis":"K6-2-u4-X31"}],"explanation":["조선어학회는 문맹 퇴치 운동을 펼쳤어요.","문맹은 배우지 못하여 글을 읽거나 쓸 줄을 모르는 것이에요.","그래서 쉬운 한글부터 가르치려고 했어요."],"asset":{"type":"passage","lines":["보기 — 문맹 · 절호 · 천금 · 직결되다 · 섣부르다","㉠ 배우지 못하여 글을 읽거나 쓸 줄을 모름. 또는 그런 사람.","㉡ 많은 돈이나 아주 귀중한 것을 비유적으로 이르는 말.","㉢ 솜씨가 익숙하지 못하고 어설프다.","㉣ 무엇을 하기에 기회나 시기가 더할 수 없이 좋음을 이르는 말."],"numbered":false,"title":"『국어』 201쪽 3번 — 낱말의 뜻"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L06_basic#5','kor',6,2,'u4','L06','tb_g6_2_kor_u4_L06_basic','lesson_basic','K6-2-u4-C21',2,'mc','auto','「큰사전이 필요하다」에서 주시경이 만들던 사전의 이름을 ‘말모이’라고 정한 까닭은 무엇인가요?',ARRAY['K6-2-u4-X30']::text[],false,'{"seq":5,"concept":"K6-2-u4-C21","difficulty":2,"kind":"mc","stem":"「큰사전이 필요하다」에서 주시경이 만들던 사전의 이름을 ‘말모이’라고 정한 까닭은 무엇인가요?","options":[{"t":"“말을 모아 놓았다.”라는 뜻에서","correct":true},{"t":"말을 타고 다니며 모은 원고라서","mis":"K6-2-u4-X30"},{"t":"모이를 주듯 나누어 준 책이라서","mis":"K6-2-u4-X30"},{"t":"주시경의 다른 이름이라서","mis":"K6-2-u4-X30"}],"explanation":["사전의 이름에는 “말을 모아 놓았다.”라는 뜻이 담겼어요.","세상에서 쓰이는 단어들을 찾아 모으는 일은 쉽지 않았어요.","주시경은 차근차근 원고를 만들어 갔어요."],"asset":{"type":"passage","lines":["(간추림) 1908년 주시경은 ‘국어연구학회’를 만들어 제자들과 사전을 만들기 시작했다.","사전의 이름은 “말을 모아 놓았다.”라는 뜻에서 ‘말모이’라 정했다.","(간추림) 1914년 원고를 가지고 외국으로 나갈 계획이었지만 그 전에 생을 마쳤다.","(간추림) 참여한 사람들도 떠나가 『말모이』는 빛을 보지 못하고 묻혔다."],"title":"「큰사전이 필요하다」 『말모이』 — 『국어』 196~197쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L06_basic#6','kor',6,2,'u4','L06','tb_g6_2_kor_u4_L06_basic','lesson_basic','K6-2-u4-C21',2,'mc','auto','「큰사전이 필요하다」에서 당시 지식인들이 사전을 만드는 것을 가장 좋은 방법으로 꼽은 까닭은 무엇인가요?',ARRAY['K6-2-u4-X30','K6-2-u4-X15']::text[],false,'{"seq":6,"concept":"K6-2-u4-C21","difficulty":2,"kind":"mc","stem":"「큰사전이 필요하다」에서 당시 지식인들이 사전을 만드는 것을 가장 좋은 방법으로 꼽은 까닭은 무엇인가요?","options":[{"t":"한글에 체계적인 문법이나 철자법이 없어 통일된 체계를 세워야 했기 때문","correct":true},{"t":"일본어를 더 잘 배워서 일본 사람처럼 쓰기 위해서","mis":"K6-2-u4-X30"},{"t":"낱말을 모아 두기만 하면 말이 저절로 지켜지기 때문","mis":"K6-2-u4-X15"},{"t":"사전을 많이 팔아 연구에 쓸 돈을 벌기 위해서","mis":"K6-2-u4-X30"}],"explanation":["그때는 같은 말도 사람마다 제각각 소리 나는 대로 썼어요.","그래서 통일된 체계를 세우는 것이 중요했어요.","문법과 철자법을 모은 사전이 있으면 모두 똑같은 언어를 쓸 수 있었어요."],"asset":{"type":"passage","lines":["(간추림) 1910년 한일 합병 조약 뒤 일본은 공식적인 자리에서 일본어만 쓰게 했다.","(간추림) 지식인들은 언어가 민족혼과 직결된다는 것을 알고 한글을 연구했다.","(간추림) 철자법이 없어 ‘덮으면’을 ‘더프면, 덥흐면, 덥프면’처럼 제각각 썼다.","(간추림) 그래서 통일된 체계를 세울 가장 좋은 방법으로 사전 만들기를 꼽았다."],"title":"「큰사전이 필요하다」(남상욱 글) 처음 부분 — 『국어』 194~195쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L06_basic#7','kor',6,2,'u4','L06','tb_g6_2_kor_u4_L06_basic','lesson_basic','K6-2-u4-C23',2,'mc','auto','「우리말의 보물을 찾아서, ‘시골말 캐기’」에서 시골말 캐기 운동에 앞장서 참여한 사람들은 누구인가요?',ARRAY['K6-2-u4-X33']::text[],false,'{"seq":7,"concept":"K6-2-u4-C23","difficulty":2,"kind":"mc","stem":"「우리말의 보물을 찾아서, ‘시골말 캐기’」에서 시골말 캐기 운동에 앞장서 참여한 사람들은 누구인가요?","options":[{"t":"방학을 맞아 고향 집으로 내려간 전국의 학생들","correct":true},{"t":"서울에 사는 학자들만 직접 나서서","mis":"K6-2-u4-X33"},{"t":"사전을 만들어 파는 출판사의 상인들","mis":"K6-2-u4-X33"},{"t":"우리말을 배우러 외국에서 온 여행자들","mis":"K6-2-u4-X33"}],"explanation":["방학을 맞은 전국의 학생들이 앞장섰어요.","학생들은 고향에서 실제 쓰는 정겨운 말을 종이에 써 보냈어요.","모인 말은 『큰사전』의 뿌리가 되었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L06_basic#8','kor',6,2,'u4','L06','tb_g6_2_kor_u4_L06_basic','lesson_basic','K6-2-u4-C13',2,'blank','auto','「우리말의 보물을 찾아서, ‘시골말 캐기’」에서 표준어 ‘부추’의 방언으로 든 말은 ‘세우리’와 (     )이에요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K6-2-u4-X33']::text[],false,'{"seq":8,"concept":"K6-2-u4-C13","difficulty":2,"kind":"blank","stem":"「우리말의 보물을 찾아서, ‘시골말 캐기’」에서 표준어 ‘부추’의 방언으로 든 말은 ‘세우리’와 (     )이에요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"정구지","correct":true},{"t":"구무","mis":"K6-2-u4-X33"},{"t":"깡냉이","mis":"K6-2-u4-X33"},{"t":"옥시기","mis":"K6-2-u4-X33"}],"explanation":["글에서 부추 대신 세우리, 정구지 같은 말을 쓴다고 했어요.","구무는 구멍, 깡냉이와 옥시기는 옥수수의 방언이에요.","방언에는 지역의 특성이 담겨 있어요."],"asset":{"type":"passage","lines":["(간추림) 사전을 만들려고 전국의 우리말을 모으던 시절, 학자들은 ‘시골말 캐기’를 펼쳤다.","(간추림) 구멍 대신 구먹·구명·구녕·구무, 부추 대신 세우리·정구지 같은 말을 모았다.","(간추림) 방학을 맞은 전국의 학생들이 고향에서 실제 쓰는 말을 종이에 써 보냈다.","(간추림) 학자들은 각 지역의 개성이 담긴 방언도 우리 민족의 소중한 보물이라고 생각했다.","(간추림) 모인 수많은 말은 『큰사전』을 만드는 든든한 뿌리가 되었다."],"title":"「우리말의 보물을 찾아서, ‘시골말 캐기’」 — 『국어』 204쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L06_basic#9','kor',6,2,'u4','L06','tb_g6_2_kor_u4_L06_basic','lesson_basic','K6-2-u4-C12',2,'mc','auto','『국어』 203쪽 안내처럼 글의 내용을 추론할 때 해야 할 일은 무엇인가요?',ARRAY['K6-2-u4-X16','K6-2-u4-X17','K6-2-u4-X36']::text[],false,'{"seq":9,"concept":"K6-2-u4-C12","difficulty":2,"kind":"mc","stem":"『국어』 203쪽 안내처럼 글의 내용을 추론할 때 해야 할 일은 무엇인가요?","options":[{"t":"글에서 단서를 찾거나 글과 관련 있는 자신의 경험이나 지식을 떠올린다","correct":true},{"t":"글은 보지 않고 머릿속에 떠오르는 대로 마음껏 상상한다","mis":"K6-2-u4-X16"},{"t":"글에 그대로 적힌 내용만 찾아서 그대로 옮겨 쓴다","mis":"K6-2-u4-X17"},{"t":"친구가 추론한 내용을 그대로 따라 내 생각으로 쓴다","mis":"K6-2-u4-X36"}],"explanation":["추론은 글에 생략된 내용을 짐작하는 일이에요.","인물의 말과 행동, 시간과 장소 같은 단서를 찾아요.","내가 아는 것이나 겪은 일도 함께 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L06_basic#10','kor',6,2,'u4','L06','tb_g6_2_kor_u4_L06_basic','lesson_basic','K6-2-u4-C12',3,'blank','auto','『국어』 203쪽 5번 ②예요. 추론한 내용의 빈칸에 들어갈 말로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u4-X16','K6-2-u4-X17']::text[],false,'{"seq":10,"concept":"K6-2-u4-C12","difficulty":3,"kind":"blank","stem":"『국어』 203쪽 5번 ②예요. 추론한 내용의 빈칸에 들어갈 말로 알맞은 것은 무엇인가요?","options":[{"t":"사전을 편찬하는 것","correct":true},{"t":"일본어를 배우는 것","mis":"K6-2-u4-X16"},{"t":"외국으로 망명하는 것","mis":"K6-2-u4-X17"},{"t":"보퉁이를 들고 다니는 것","mis":"K6-2-u4-X16"}],"explanation":["조선어학회는 『말모이』의 뜻을 이어 사전 편찬을 시작했어요.","앞에서 사전이 꼭 필요했던 까닭을 읽었어요.","그래서 사전을 편찬하는 것이 중요한 일이었다고 추론할 수 있어요."],"asset":{"type":"passage","lines":["[글 내용] 『말모이』는 출간되지 못했으나 그 뜻이 이어진 조선어학회에서","사전 편찬 작업을 이어받았다.","[질문] 조선어학회에서 사전 편찬 작업을 이어받은 까닭은 무엇일까요?","[추론한 내용] 그 당시 우리말을 연구하는 사람에게 (          )은/는 중요한 일이었을 것이다."],"numbered":false,"title":"『국어』 203쪽 5번 — 글 내용 추론하기 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L06_challenge#1','kor',6,2,'u4','L06','tb_g6_2_kor_u4_L06_challenge','lesson_challenge','K6-2-u4-C22',2,'mc','auto','『국어』 201쪽 3번 보기의 다섯 낱말 가운데 네 가지 뜻풀이(㉠~㉣) 어디에도 들어가지 않는 낱말은 무엇인가요?',ARRAY['K6-2-u4-X31']::text[],false,'{"seq":1,"concept":"K6-2-u4-C22","difficulty":2,"kind":"mc","stem":"『국어』 201쪽 3번 보기의 다섯 낱말 가운데 네 가지 뜻풀이(㉠~㉣) 어디에도 들어가지 않는 낱말은 무엇인가요?","options":[{"t":"직결되다","correct":true},{"t":"문맹","mis":"K6-2-u4-X31"},{"t":"천금","mis":"K6-2-u4-X31"},{"t":"섣부르다","mis":"K6-2-u4-X31"}],"explanation":["㉠ 문맹, ㉡ 천금, ㉢ 섣부르다, ㉣ 절호예요.","‘직결되다’는 남는 낱말이에요.","글에서 언어가 민족혼과 직결된다고 했던 낱말이에요."],"asset":{"type":"passage","lines":["보기 — 문맹 · 절호 · 천금 · 직결되다 · 섣부르다","㉠ 배우지 못하여 글을 읽거나 쓸 줄을 모름. 또는 그런 사람.","㉡ 많은 돈이나 아주 귀중한 것을 비유적으로 이르는 말.","㉢ 솜씨가 익숙하지 못하고 어설프다.","㉣ 무엇을 하기에 기회나 시기가 더할 수 없이 좋음을 이르는 말."],"numbered":false,"title":"『국어』 201쪽 3번 — 낱말의 뜻"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L06_challenge#2','kor',6,2,'u4','L06','tb_g6_2_kor_u4_L06_challenge','lesson_challenge','K6-2-u4-C13',2,'mc','auto','『국어』 205쪽 낱말 카드에서 표준어 ‘가위’의 방언으로 든 말은 무엇인가요?',ARRAY['K6-2-u4-X33']::text[],false,'{"seq":2,"concept":"K6-2-u4-C13","difficulty":2,"kind":"mc","stem":"『국어』 205쪽 낱말 카드에서 표준어 ‘가위’의 방언으로 든 말은 무엇인가요?","options":[{"t":"가새, 가시개, 까깨","correct":true},{"t":"부치개, 지지미, 찌짐","mis":"K6-2-u4-X33"},{"t":"개고리, 깨고리, 깨고락지","mis":"K6-2-u4-X33"},{"t":"구먹, 구명, 구녕","mis":"K6-2-u4-X33"}],"explanation":["낱말 카드에는 표준어, 뜻, 방언이 들어가요.","가위의 방언은 가새, 가시개, 까깨예요.","부치개, 지지미, 찌짐은 부침개의 방언이에요."],"asset":{"type":"passage","lines":["[낱말 카드] 가위 — 옷감, 종이, 머리털 따위를 자르는 기구.","방언: 가새, 가시개, 까깨","[낱말 카드] 부침개 — 기름에 부쳐서 만드는 빈대떡, 전, 누름적, 전병 따위의 음식.","방언: 부치개, 지지미, 찌짐"],"numbered":false,"title":"우리말 사전 낱말 카드 예시 — 『국어』 205쪽 6번 (3)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L06_challenge#3','kor',6,2,'u4','L06','tb_g6_2_kor_u4_L06_challenge','lesson_challenge','K6-2-u4-C12',3,'mc','auto','『국어』 203쪽 5번 ③이에요. 질문의 빈칸에 들어갈 말로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u4-X17','K6-2-u4-X16']::text[],false,'{"seq":3,"concept":"K6-2-u4-C12","difficulty":3,"kind":"mc","stem":"『국어』 203쪽 5번 ③이에요. 질문의 빈칸에 들어갈 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"회원들이 『큰사전』의 원고를 찾아다닌 까닭은 무엇일까요?","correct":true},{"t":"『큰사전』은 모두 몇 권으로 완간되었나요?","mis":"K6-2-u4-X17"},{"t":"원고를 찾은 서울역은 어느 도시에 있나요?","mis":"K6-2-u4-X17"},{"t":"원고는 어떤 종이에 무엇으로 썼나요?","mis":"K6-2-u4-X16"}],"explanation":["추론한 내용은 회원들이 왜 원고를 찾아다녔는지에 대한 답이에요.","그러니 질문은 원고를 찾아다닌 까닭을 묻는 것이어야 해요.","글에 적힌 사실을 묻는 질문으로는 생략된 내용을 추론할 수 없어요."],"asset":{"type":"passage","lines":["[글 내용] 우리나라가 광복을 맞은 이후, 조선어학회 회원들은","『큰사전』의 원고를 찾아다녔다.","[질문] (                    )","[추론한 내용] 『큰사전』의 원고를 찾아 한글 사전을 완성해야 한다고 생각했을 것이다."],"numbered":false,"title":"『국어』 203쪽 5번 — 글 내용 추론하기 ③"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L06_challenge#4','kor',6,2,'u4','L06','tb_g6_2_kor_u4_L06_challenge','lesson_challenge','K6-2-u4-C21',3,'mc','auto','『국어』 202쪽 4번 (4)예요. ㉠~㉣에 들어갈 말을 바르게 짝지은 것은 무엇인가요?',ARRAY['K6-2-u4-X30']::text[],false,'{"seq":4,"concept":"K6-2-u4-C21","difficulty":3,"kind":"mc","stem":"『국어』 202쪽 4번 (4)예요. ㉠~㉣에 들어갈 말을 바르게 짝지은 것은 무엇인가요?","options":[{"t":"㉠ 사전 · ㉡ 조선어연구회 · ㉢ 조선어학회 · ㉣ 서울역","correct":true},{"t":"㉠ 신문 · ㉡ 조선어학회 · ㉢ 조선어연구회 · ㉣ 함흥역","mis":"K6-2-u4-X30"},{"t":"㉠ 사전 · ㉡ 국어연구학회 · ㉢ 조선어학회 · ㉣ 서울역","mis":"K6-2-u4-X30"},{"t":"㉠ 사전 · ㉡ 조선어연구회 · ㉢ 조선어학회 · ㉣ 상하이","mis":"K6-2-u4-X30"}],"explanation":["1908년 주시경은 국어연구학회를 만들어 사전을 만들기 시작했어요.","1921년 조선어연구회가 세워지고 1931년 조선어학회로 이름을 바꾸었어요.","1945년 9월 8일 서울역 창고에서 원고를 찾았어요."],"asset":{"type":"passage","lines":["1908년, 주시경은 ‘국어연구학회’를 만들어 제자들과 (  ㉠  )을/를 만들기 시작했다.","1910년 8월 29일, 한일 합병 조약이 발표되었다.","1914년 7월 27일 주시경이 생을 마친 뒤, 1921년에 (  ㉡  )이/가 설립되었다.","1931년, (  ㉢  )(으)로 이름을 바꾸고 사전 편찬을 시작했다.","1942년, 조선어학회가 편찬하던 사전 원고를 전부 압수당했다.","1945년 9월 8일, (  ㉣  ) 창고에서 『큰사전』 원고를 찾았다.","1957년, 사전이 6권으로 완간되었다."],"numbered":false,"title":"『국어』 202쪽 4번 (4) — 일어난 차례대로 정리하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L06_challenge#5','kor',6,2,'u4','L06','tb_g6_2_kor_u4_L06_challenge','lesson_challenge','K6-2-u4-C12',3,'mc','auto','「큰사전이 필요하다」에서 일본이 조선어학회를 탄압한 까닭을 추론한 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u4-X30','K6-2-u4-X16']::text[],false,'{"seq":5,"concept":"K6-2-u4-C12","difficulty":3,"kind":"mc","stem":"「큰사전이 필요하다」에서 일본이 조선어학회를 탄압한 까닭을 추론한 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"우리말을 지키는 조선어학회가 한글 사용을 막으려는 일본에 방해가 되어서","correct":true},{"t":"조선어학회가 일본어 사전을 몰래 만들었다는 것이 밝혀졌기 때문","mis":"K6-2-u4-X30"},{"t":"함흥의 학생들이 일본어를 너무 잘해서 경찰이 놀랐기 때문","mis":"K6-2-u4-X16"},{"t":"조선어학회 회원들이 함흥으로 가는 기차를 멈추게 했기 때문","mis":"K6-2-u4-X16"}],"explanation":["일본은 일본어 상용화를 발표하며 한글 사용을 금지했어요.","글은 조선어학회가 일본에게 눈엣가시와 같았다고 했어요.","이 단서들로 탄압한 까닭을 추론할 수 있어요."],"asset":{"type":"passage","lines":["(간추림) 1942년 함흥에서 기차 안에서 우리말을 쓴 학생들이 일본 경찰에 붙잡혔다.","(간추림) 학생의 일기장을 단서로 교사 정태진이 조선어학회 회원임이 밝혀졌다.","(간추림) 일제는 이를 빌미로 조선어학회를 탄압하고 『큰사전』 원고를 모두 압수했다.","(간추림) 1945년 광복 뒤 회원들은 원고를 찾아 전국을 뒤졌지만 찾지 못했다.","“『큰사전』의 원고를 찾아야 합니다!”"],"title":"「큰사전이 필요하다」 빼앗긴 원고 — 『국어』 199쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L06_challenge#6','kor',6,2,'u4','L06','tb_g6_2_kor_u4_L06_challenge','lesson_challenge','K6-2-u4-C11',3,'mc','auto','『국어』 199쪽 「생각하며 읽기」 “사전 편찬과 독립운동이 연결된다고 생각한 까닭은 무엇인가요?”에 대한 답으로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u4-X15','K6-2-u4-X16']::text[],false,'{"seq":6,"concept":"K6-2-u4-C11","difficulty":3,"kind":"mc","stem":"『국어』 199쪽 「생각하며 읽기」 “사전 편찬과 독립운동이 연결된다고 생각한 까닭은 무엇인가요?”에 대한 답으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"언어가 민족혼과 직결되어, 우리말을 지키는 일이 곧 겨레의 얼을 지키는 일이었기 때문","correct":true},{"t":"사전을 만들기만 하면 나라를 저절로 되찾을 수 있었기 때문","mis":"K6-2-u4-X15"},{"t":"사전을 많이 팔아 그 돈을 독립 자금으로 모았기 때문","mis":"K6-2-u4-X16"},{"t":"독립운동가는 모두 한 권씩 사전을 써서 남겼기 때문","mis":"K6-2-u4-X16"}],"explanation":["글의 처음에 언어가 민족혼과 직결된다고 했어요.","일본은 우리말을 쓰지 못하게 해 겨레의 얼을 없애려 했어요.","그래서 우리말 사전을 만드는 일은 나라를 지키는 일과 이어졌어요."],"asset":{"type":"passage","lines":["(간추림) 1910년 한일 합병 조약 뒤 일본은 공식적인 자리에서 일본어만 쓰게 했다.","(간추림) 지식인들은 언어가 민족혼과 직결된다는 것을 알고 한글을 연구했다.","(간추림) 철자법이 없어 ‘덮으면’을 ‘더프면, 덥흐면, 덥프면’처럼 제각각 썼다.","(간추림) 그래서 통일된 체계를 세울 가장 좋은 방법으로 사전 만들기를 꼽았다."],"title":"「큰사전이 필요하다」(남상욱 글) 처음 부분 — 『국어』 194~195쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L06_challenge#7','kor',6,2,'u4','L06','tb_g6_2_kor_u4_L06_challenge','lesson_challenge','K6-2-u4-C13',3,'error','auto','표준어와 방언에 대해 친구들이 한 말이에요. 알맞지 않은 것은 무엇인가요?',ARRAY['K6-2-u4-X19','K6-2-u4-X33','K6-2-u4-X20']::text[],false,'{"seq":7,"concept":"K6-2-u4-C13","difficulty":3,"kind":"error","stem":"표준어와 방언에 대해 친구들이 한 말이에요. 알맞지 않은 것은 무엇인가요?","options":[{"t":"㉯ “방언은 표준어가 아니니까 고쳐야 할 틀린 말이야.”","correct":true,"mis_target":"K6-2-u4-X19"},{"t":"㉮ “학자들은 각 지역의 개성이 담긴 방언도 우리 민족의 소중한 보물이라고 생각했어.”","mis":"K6-2-u4-X33"},{"t":"㉰ “방언을 찾을 때에는 어느 지역에서 사용하는 방언인지도 함께 살펴보면 좋아.”","mis":"K6-2-u4-X20"}],"explanation":["방언은 틀린 말이 아니라 지역의 특성을 담은 우리말이에요.","학자들은 방언도 소중한 보물이라고 여겨 『큰사전』에 모았어요.","표준어와 방언 모두 소중한 우리말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L06_challenge#8','kor',6,2,'u4','L06','tb_g6_2_kor_u4_L06_challenge','lesson_challenge','K6-2-u4-C12',4,'essay','teacher','『국어』 203쪽 5번 표처럼 「큰사전이 필요하다」에서 글 내용 하나를 골라 질문을 만들고, 단서나 자신의 경험·지식을 바탕으로 추론한 내용을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K6-2-u4-C12","difficulty":4,"kind":"essay","stem":"『국어』 203쪽 5번 표처럼 「큰사전이 필요하다」에서 글 내용 하나를 골라 질문을 만들고, 단서나 자신의 경험·지식을 바탕으로 추론한 내용을 쓰세요.","answer_guide":{"answer":"예: 글 내용 — 일본은 모든 공식적인 자리에서 일본어만 쓸 수 있게 했다. / 질문 — 일본은 왜 일본어만 쓰게 했을까요? / 추론한 내용 — 언어가 민족혼과 직결된다는 글의 내용을 보면, 우리말을 없애 우리 민족의 정신을 약하게 만들려고 했을 것이다.","scoring_points":["글에 있는 내용을 골랐는가","생략된 내용을 묻는 질문을 만들었는가","글의 단서나 경험·지식을 근거로 추론했는가"]},"explanation":["글에 적혀 있지 않은 까닭이나 마음을 묻는 질문을 만들어요.","단서는 인물의 말과 행동, 때와 장소에서 찾아요.","추론한 근거를 함께 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L06_challenge#9','kor',6,2,'u4','L06','tb_g6_2_kor_u4_L06_challenge','lesson_challenge','K6-2-u4-C26',4,'essay','teacher','주시경 선생님이 쓴 편지를 읽고, 글쓴이가 이 편지를 쓴 의도를 쓰세요. 그렇게 생각한 근거가 된 문장도 함께 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u4-C26","difficulty":4,"kind":"essay","stem":"주시경 선생님이 쓴 편지를 읽고, 글쓴이가 이 편지를 쓴 의도를 쓰세요. 그렇게 생각한 근거가 된 문장도 함께 쓰세요.","answer_guide":{"answer":"예: 어린이들이 한글을 우리 겨레의 숨결이 담긴 소중한 보물로 여기고 아끼고 가꾸기를 바라는 마음에서 썼다. “보물은 소중히 아끼고 가꿀수록 더욱 빛이 날 거예요.”라는 문장에서 알 수 있다.","scoring_points":["글쓴이의 의도를 썼는가","편지에서 근거가 되는 문장을 찾아 썼는가","글 내용을 옮기는 데 그치지 않고 바라는 점을 추론했는가"]},"explanation":["글쓴이의 생각이 드러난 문장을 찾아요.","글쓴이가 읽는 사람에게 무엇을 바라는지 생각해요.","추론은 사람마다 조금씩 다를 수 있지만 근거가 있어야 해요."],"asset":{"type":"passage","lines":["저는 주시경이라고 해요. 예전에는 ‘한힌샘’이라는 이름으로도 불렸어요.","(간추림) ‘한’은 하나뿐인 크고 위대한 나라, ‘힌샘’은 맑고 깨끗한 샘물처럼","(간추림) 지혜롭고 밝은 생각이 흘러나오는 곳을 뜻한다.","(간추림) 나라를 빼앗겼을 때 우리말 사전을 만들고 한글을 가르치는 데 온 마음을 다했다.","한글은 우리 겨레의 숨결이 담긴 소중한 보물이에요.","보물은 소중히 아끼고 가꿀수록 더욱 빛이 날 거예요.","[날짜와 쓴 사람] ○○○○년 10월 9일 · 우리말을 사랑하는 주시경 선생님이"],"numbered":false,"title":"주시경 선생님이 쓴 편지 — 글을 읽고 추론하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L06_challenge#10','kor',6,2,'u4','L06','tb_g6_2_kor_u4_L06_challenge','lesson_challenge','K6-2-u4-C11',4,'essay','teacher','『국어』 205쪽 7번처럼 우리말을 사랑하고 지키기 위해 자신이 할 수 있는 일을 두 가지 쓰세요. 실천으로 이어질 수 있게 구체적으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u4-C11","difficulty":4,"kind":"essay","stem":"『국어』 205쪽 7번처럼 우리말을 사랑하고 지키기 위해 자신이 할 수 있는 일을 두 가지 쓰세요. 실천으로 이어질 수 있게 구체적으로 쓰세요.","answer_guide":{"answer":"예: ① 평소 나의 언어 습관을 되돌아보고 우리말을 더 아끼고 자주 사용하려고 노력하겠다. ② 처음 보는 낱말은 국어사전에서 뜻과 갈래를 찾아보고 공책에 정리하겠다.","scoring_points":["우리말을 지키는 일과 이어지는가","두 가지를 썼는가","실천할 수 있게 구체적으로 썼는가"]},"explanation":["주시경과 조선어학회의 노력을 떠올려요.","오늘의 내가 할 수 있는 일로 바꾸어 생각해요.","언제, 무엇을 할지 구체적으로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L08_basic#1','kor',6,2,'u4','L08','tb_g6_2_kor_u4_L08_basic','lesson_basic','K6-2-u4-C14',1,'mc','auto','『국어』 206쪽 (1)처럼 자신과 모둠원의 언어생활 점검표를 쓰는 목적으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u4-X21','K6-2-u4-X03']::text[],false,'{"seq":1,"concept":"K6-2-u4-C14","difficulty":1,"kind":"mc","stem":"『국어』 206쪽 (1)처럼 자신과 모둠원의 언어생활 점검표를 쓰는 목적으로 알맞은 것은 무엇인가요?","options":[{"t":"자신과 모둠원의 언어생활을 돌아보고 함께 바르게 고쳐 나가려고","correct":true},{"t":"말을 가장 많이 틀린 친구를 찾아내려고","mis":"K6-2-u4-X21"},{"t":"줄임말을 많이 쓴 사람에게 벌을 주려고","mis":"K6-2-u4-X21"},{"t":"외래어를 많이 아는 친구를 칭찬하려고","mis":"K6-2-u4-X03"}],"explanation":["점검표는 평소 언어생활을 돌아보려고 써요.","친구를 비난하거나 놀리려는 것이 아니에요.","점검한 결과로 우리 반이 함께 고칠 점을 찾아요."],"asset":{"type":"passage","lines":["[점검표] 사용하는 말 — 외래어 · 줄임말 · 고유어","[표시] 하루에 네 번 이상 · 두세 번 · 한 번 이하","[조사 항목] 많이 사용하는 말 — 조사 결과"],"numbered":false,"title":"자신과 모둠원의 언어생활 점검 — 『국어』 206쪽 (1)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L08_basic#2','kor',6,2,'u4','L08','tb_g6_2_kor_u4_L08_basic','lesson_basic','K6-2-u4-C14',1,'mc','auto','『국어』 206쪽 (1)의 언어생활 점검표에는 외래어, 줄임말, 고유어마다 무엇을 표시하나요?',ARRAY['K6-2-u4-X21','K6-2-u4-X08']::text[],false,'{"seq":2,"concept":"K6-2-u4-C14","difficulty":1,"kind":"mc","stem":"『국어』 206쪽 (1)의 언어생활 점검표에는 외래어, 줄임말, 고유어마다 무엇을 표시하나요?","options":[{"t":"하루 동안 그 말을 사용하는 정도","correct":true},{"t":"그 말을 쓴 친구의 이름","mis":"K6-2-u4-X21"},{"t":"그 말을 처음 배운 날짜","mis":"K6-2-u4-X21"},{"t":"그 말의 글자 수","mis":"K6-2-u4-X08"}],"explanation":["점검표에는 하루에 네 번 이상, 두세 번, 한 번 이하로 표시해요.","말을 얼마나 자주 쓰는지 돌아보는 표예요.","많이 사용하는 외래어, 줄임말, 고유어도 직접 써 보아요."],"asset":{"type":"passage","lines":["[점검표] 사용하는 말 — 외래어 · 줄임말 · 고유어","[표시] 하루에 네 번 이상 · 두세 번 · 한 번 이하","[조사 항목] 많이 사용하는 말 — 조사 결과"],"numbered":false,"title":"자신과 모둠원의 언어생활 점검 — 『국어』 206쪽 (1)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L08_basic#3','kor',6,2,'u4','L08','tb_g6_2_kor_u4_L08_basic','lesson_basic','K6-2-u4-C15',1,'ox','auto','실천 다짐문의 마지막 부분에는 실천 다짐문을 쓴 날짜와 쓴 사람을 써요.',ARRAY['K6-2-u4-X22']::text[],false,'{"seq":3,"concept":"K6-2-u4-C15","difficulty":1,"kind":"ox","stem":"실천 다짐문의 마지막 부분에는 실천 다짐문을 쓴 날짜와 쓴 사람을 써요.","answer":"O","reason_options":[{"t":"『국어』 209쪽 안내처럼 날짜와 쓴 사람으로 다짐문을 마무리해요.","correct":true},{"t":"날짜와 이름은 쓰지 않아도 다짐문이 완성돼요.","mis":"K6-2-u4-X22"}],"mis":"K6-2-u4-X22","explanation":["다짐문 예시의 맨 끝에는 날짜와 이름이 있어요.","누가 언제 다짐했는지 밝혀야 실천을 되돌아볼 수 있어요.","날짜와 쓴 사람도 다짐문의 한 부분이에요."],"asset":{"type":"passage","lines":["우리말 지킴이 실천 다짐문","나는 아름답고 소중한 우리말을 지키고 바르게 사용하고자 다음과 같이 다짐합니다.","하나, 나는 일상생활에서 불필요한 외래어 사용을 줄이고, 고유어를 적극적으로 찾아 사용하겠습니다.","하나, 나는 뜻을 알기 어려운 말이나 지나친 줄임말보다는 표준어를 사용하려고 노력하겠습니다.","하나, 나는 비속어나 욕설을 사용하지 않고, 긍정적이고 예쁜 말을 사용해 상대를 존중하겠습니다.","소중한 우리말을 바르게 사용하려고 열심히 노력할 것을 약속합니다.","20○○년 ○○월 ○○일 · ○○○"],"numbered":false,"title":"실천 다짐문 예시 — 『국어』 209쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L08_basic#4','kor',6,2,'u4','L08','tb_g6_2_kor_u4_L08_basic','lesson_basic','K6-2-u4-C15',1,'mc','auto','『국어』 209쪽 안내에서 실천 다짐문에 쓸 수 있다고 한 세 가지는 무엇인가요?',ARRAY['K6-2-u4-X22']::text[],false,'{"seq":4,"concept":"K6-2-u4-C15","difficulty":1,"kind":"mc","stem":"『국어』 209쪽 안내에서 실천 다짐문에 쓸 수 있다고 한 세 가지는 무엇인가요?","options":[{"t":"목적, 구체적인 실천 약속, 전하고 싶은 말","correct":true},{"t":"등장인물, 사건, 배경과 줄거리","mis":"K6-2-u4-X22"},{"t":"주장과 근거, 반대 의견","mis":"K6-2-u4-X22"},{"t":"날씨, 오늘 있었던 일, 느낀 점","mis":"K6-2-u4-X22"}],"explanation":["실천 다짐문에는 목적, 구체적인 실천 약속, 전하고 싶은 말을 써요.","마지막 부분에는 날짜와 쓴 사람을 써요.","네 부분을 갖추면 다짐문이 완성돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L08_basic#5','kor',6,2,'u4','L08','tb_g6_2_kor_u4_L08_basic','lesson_basic','K6-2-u4-C14',2,'mc','auto','『국어』 207쪽 (3) 예시 답안에서 우리 반 언어생활 실태를 정리하려고 더한 조사 항목은 무엇인가요?',ARRAY['K6-2-u4-X21','K6-2-u4-X27']::text[],false,'{"seq":5,"concept":"K6-2-u4-C14","difficulty":2,"kind":"mc","stem":"『국어』 207쪽 (3) 예시 답안에서 우리 반 언어생활 실태를 정리하려고 더한 조사 항목은 무엇인가요?","options":[{"t":"알아들을 수 없는 신조어","correct":true},{"t":"친구들의 별명","mis":"K6-2-u4-X21"},{"t":"좋아하는 노래 제목","mis":"K6-2-u4-X27"},{"t":"고유어 시험 점수","mis":"K6-2-u4-X21"}],"explanation":["조사 항목은 많이 사용하는 외래어, 많이 사용하는 줄임말이에요.","예시 답안에서는 알아들을 수 없는 신조어를 더했어요.","우리 반 언어생활을 돌아보는 데 필요한 항목이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L08_basic#6','kor',6,2,'u4','L08','tb_g6_2_kor_u4_L08_basic','lesson_basic','K6-2-u4-C14',2,'mc','auto','『국어』 206쪽 (2)에서 “외래어를 무분별하게 사용하는 까닭은 무엇인가요?”처럼 언어생활 실태를 묻고 답하는 까닭은 무엇인가요?',ARRAY['K6-2-u4-X21','K6-2-u4-X03']::text[],false,'{"seq":6,"concept":"K6-2-u4-C14","difficulty":2,"kind":"mc","stem":"『국어』 206쪽 (2)에서 “외래어를 무분별하게 사용하는 까닭은 무엇인가요?”처럼 언어생활 실태를 묻고 답하는 까닭은 무엇인가요?","options":[{"t":"우리 반 언어생활의 까닭과 고칠 점을 함께 생각해 보려고","correct":true},{"t":"외래어를 많이 쓴 친구를 찾아 놀리려고","mis":"K6-2-u4-X21"},{"t":"외래어가 멋있다는 것을 친구들에게 알리려고","mis":"K6-2-u4-X03"},{"t":"점검표의 빈칸을 빠짐없이 채워 내려고","mis":"K6-2-u4-X21"}],"explanation":["점검표를 보고 분석하는 데서 나아가 까닭을 물어요.","고칠 점과 바라는 점까지 이야기를 넓혀요.","친구를 탓하지 않고 함께 생각해요."],"asset":{"type":"passage","lines":["[질문] 어떤 점을 고쳐야 할까요?","[질문] 줄임말을 많이 사용하는 까닭은 무엇인가요?","[질문] 외래어를 무분별하게 사용하는 까닭은 무엇인가요?"],"numbered":false,"title":"언어생활 실태를 묻고 답하는 질문 — 『국어』 206쪽 (2)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L08_basic#7','kor',6,2,'u4','L08','tb_g6_2_kor_u4_L08_basic','lesson_basic','K6-2-u4-C14',2,'mc','auto','『국어』 207쪽 (4)에서 앞으로의 언어생활에 대해 고유어와 이어 말한 것은 무엇인가요?',ARRAY['K6-2-u4-X02','K6-2-u4-X04','K6-2-u4-X03']::text[],false,'{"seq":7,"concept":"K6-2-u4-C14","difficulty":2,"kind":"mc","stem":"『국어』 207쪽 (4)에서 앞으로의 언어생활에 대해 고유어와 이어 말한 것은 무엇인가요?","options":[{"t":"“무분별하게 사용하는 외래어를 고유어로 바꿀 수 있는지 생각해 보면 좋겠어.”","correct":true},{"t":"“외래어는 모두 없애고 앞으로 고유어만 써야 해.”","mis":"K6-2-u4-X02"},{"t":"“줄임말은 친구끼리만 쓰니 아무리 많이 써도 괜찮아.”","mis":"K6-2-u4-X04"},{"t":"“어려운 외국어를 많이 섞어 써야 똑똑해 보여.”","mis":"K6-2-u4-X03"}],"explanation":["친구 2는 외래어를 고유어로 바꿀 수 있는지 생각해 보자고 했어요.","바꿀 수 있는 것만 바꾸자는 말이에요.","외래어를 모두 없애자는 말과는 달라요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"“줄임말을 무분별하게 사용하지 않아야 해.”"},{"who":"친구 2","text":"“무분별하게 사용하는 외래어를 고유어로 바꿀 수 있는지 생각해 보면 좋겠어.”"},{"who":"친구 3","text":"“바른 우리말을 사용해야 해.”"},{"who":"친구 4","text":"“알아들을 수 없는 신조어 사용을 줄이고 바르고 고운 말을 쓰면 좋겠어.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L08_basic#8','kor',6,2,'u4','L08','tb_g6_2_kor_u4_L08_basic','lesson_basic','K6-2-u4-C15',2,'blank','auto','다짐문 예시의 “나는 아름답고 소중한 우리말을 지키고 바르게 사용하고자 다음과 같이 다짐합니다.”는 실천 다짐문의 어느 부분인가요?',ARRAY['K6-2-u4-X22']::text[],false,'{"seq":8,"concept":"K6-2-u4-C15","difficulty":2,"kind":"blank","stem":"다짐문 예시의 “나는 아름답고 소중한 우리말을 지키고 바르게 사용하고자 다음과 같이 다짐합니다.”는 실천 다짐문의 어느 부분인가요?","options":[{"t":"목적","correct":true},{"t":"구체적인 실천 약속","mis":"K6-2-u4-X22"},{"t":"전하고 싶은 말","mis":"K6-2-u4-X22"},{"t":"쓴 날짜와 쓴 사람","mis":"K6-2-u4-X22"}],"explanation":["이 문장은 무엇을 위해 다짐하는지 밝혀요.","그래서 다짐문의 목적에 해당해요.","그다음에 ‘하나,’로 시작하는 실천 약속이 이어져요."],"asset":{"type":"passage","lines":["우리말 지킴이 실천 다짐문","나는 아름답고 소중한 우리말을 지키고 바르게 사용하고자 다음과 같이 다짐합니다.","하나, 나는 일상생활에서 불필요한 외래어 사용을 줄이고, 고유어를 적극적으로 찾아 사용하겠습니다.","하나, 나는 뜻을 알기 어려운 말이나 지나친 줄임말보다는 표준어를 사용하려고 노력하겠습니다.","하나, 나는 비속어나 욕설을 사용하지 않고, 긍정적이고 예쁜 말을 사용해 상대를 존중하겠습니다.","소중한 우리말을 바르게 사용하려고 열심히 노력할 것을 약속합니다.","20○○년 ○○월 ○○일 · ○○○"],"numbered":false,"title":"실천 다짐문 예시 — 『국어』 209쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L08_basic#9','kor',6,2,'u4','L08','tb_g6_2_kor_u4_L08_basic','lesson_basic','K6-2-u4-C15',2,'mc','auto','다짐문 예시에서 ‘구체적인 실천 약속’에 해당하는 문장은 무엇인가요?',ARRAY['K6-2-u4-X22']::text[],false,'{"seq":9,"concept":"K6-2-u4-C15","difficulty":2,"kind":"mc","stem":"다짐문 예시에서 ‘구체적인 실천 약속’에 해당하는 문장은 무엇인가요?","options":[{"t":"“하나, 나는 비속어나 욕설을 사용하지 않고, 긍정적이고 예쁜 말을 사용해 상대를 존중하겠습니다.”","correct":true},{"t":"“나는 아름답고 소중한 우리말을 지키고 바르게 사용하고자 다음과 같이 다짐합니다.”","mis":"K6-2-u4-X22"},{"t":"“소중한 우리말을 바르게 사용하려고 열심히 노력할 것을 약속합니다.”","mis":"K6-2-u4-X22"},{"t":"“20○○년 ○○월 ○○일 · ○○○”","mis":"K6-2-u4-X22"}],"explanation":["실천 약속은 무엇을 할지 구체적으로 밝힌 문장이에요.","예시에서는 ‘하나,’로 시작하는 세 문장이에요.","제목, 전하고 싶은 말, 날짜와는 하는 일이 달라요."],"asset":{"type":"passage","lines":["우리말 지킴이 실천 다짐문","나는 아름답고 소중한 우리말을 지키고 바르게 사용하고자 다음과 같이 다짐합니다.","하나, 나는 일상생활에서 불필요한 외래어 사용을 줄이고, 고유어를 적극적으로 찾아 사용하겠습니다.","하나, 나는 뜻을 알기 어려운 말이나 지나친 줄임말보다는 표준어를 사용하려고 노력하겠습니다.","하나, 나는 비속어나 욕설을 사용하지 않고, 긍정적이고 예쁜 말을 사용해 상대를 존중하겠습니다.","소중한 우리말을 바르게 사용하려고 열심히 노력할 것을 약속합니다.","20○○년 ○○월 ○○일 · ○○○"],"numbered":false,"title":"실천 다짐문 예시 — 『국어』 209쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L08_basic#10','kor',6,2,'u4','L08','tb_g6_2_kor_u4_L08_basic','lesson_basic','K6-2-u4-C15',3,'mc','auto','『국어』 210쪽 (1)에서 친구들이 실천 다짐문의 고칠 점으로 말한 것이 아닌 것은 무엇인가요?',ARRAY['K6-2-u4-X23','K6-2-u4-X22','K6-2-u4-X24']::text[],false,'{"seq":10,"concept":"K6-2-u4-C15","difficulty":3,"kind":"mc","stem":"『국어』 210쪽 (1)에서 친구들이 실천 다짐문의 고칠 점으로 말한 것이 아닌 것은 무엇인가요?","options":[{"t":"“글씨를 더 크고 예쁘게 쓰면 좋겠어.”","correct":true},{"t":"“다짐이 구체적으로 드러나도록 내용을 쓰면 좋겠어.”","mis":"K6-2-u4-X23"},{"t":"“실천 의지가 드러나도록 쓰는 것이 좋겠어.”","mis":"K6-2-u4-X22"},{"t":"“고유어를 활용하면 좋을 것 같아.”","mis":"K6-2-u4-X24"}],"explanation":["친구들은 다짐의 내용에서 고칠 점을 찾았어요.","구체적인 다짐, 실천 의지, 고유어 활용, 실천 가능한 내용이에요.","글씨 같은 겉모습은 고칠 점으로 말하지 않았어요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"“다짐이 구체적으로 드러나도록 내용을 쓰면 좋겠어.”"},{"who":"친구 2","text":"“실천 의지가 드러나도록 쓰는 것이 좋겠어.”"},{"who":"친구 3","text":"“고유어를 활용하면 좋을 것 같아.”"},{"who":"친구 4","text":"“실천 가능한 내용이면 좋을 것 같아.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L08_challenge#1','kor',6,2,'u4','L08','tb_g6_2_kor_u4_L08_challenge','lesson_challenge','K6-2-u4-C14',2,'mc','auto','언어 사용 실태를 다룬 뉴스에서 ‘페이백’, ‘플랫폼’, ‘프랙탈’ 같은 말을 문제로 든 까닭은 무엇인가요?',ARRAY['K6-2-u4-X03','K6-2-u4-X20']::text[],false,'{"seq":1,"concept":"K6-2-u4-C14","difficulty":2,"kind":"mc","stem":"언어 사용 실태를 다룬 뉴스에서 ‘페이백’, ‘플랫폼’, ‘프랙탈’ 같은 말을 문제로 든 까닭은 무엇인가요?","options":[{"t":"쉬운 우리말을 놔두고 어려운 외국어를 써서 누구나 쉽게 이해하기 어렵기 때문","correct":true},{"t":"외국어를 쓰면 더 전문적이고 믿음직하게 보이기 때문","mis":"K6-2-u4-X03"},{"t":"말이 짧아 아무 문제가 없는데 괜히 트집을 잡기 때문","mis":"K6-2-u4-X03"},{"t":"공공 언어는 누가 읽든 아무렇게나 써도 되기 때문","mis":"K6-2-u4-X20"}],"explanation":["공공 언어는 국민 누구나 쉽게 이해할 수 있어야 해요.","우리말이 있는데도 굳이 외국어를 갖다 쓰면 알아듣기 어려워요.","그래서 무분별한 외국어 사용이 대표적인 문제로 꼽혔어요."],"asset":{"type":"passage","lines":["(간추림) 정부 기관이 쓰는 공공 언어는 국민 누구나 쉽게 이해할 수 있어야 한다.","(간추림) 그러나 쉬운 우리말을 놔두고 어려운 외국어 표현을 남발하는 경우가 많다.","(간추림) ‘페이백’, ‘플랫폼’, ‘프랙탈’처럼 우리말이 있는데도 굳이 갖다 쓴 외국어가 많다.","(간추림) 우리말이 잘못 쓰이는 대표 유형은 무분별한 외국어 사용이었다."],"title":"언어 사용 실태를 다룬 뉴스(간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L08_challenge#2','kor',6,2,'u4','L08','tb_g6_2_kor_u4_L08_challenge','lesson_challenge','K6-2-u4-C15',2,'mc','auto','『국어』 211쪽 ‘공유하기’에서 완성한 실천 다짐문을 공유하는 방법으로 안내한 것이 아닌 것은 무엇인가요?',ARRAY['K6-2-u4-X26']::text[],false,'{"seq":2,"concept":"K6-2-u4-C15","difficulty":2,"kind":"mc","stem":"『국어』 211쪽 ‘공유하기’에서 완성한 실천 다짐문을 공유하는 방법으로 안내한 것이 아닌 것은 무엇인가요?","options":[{"t":"다짐문을 접어 서랍 속에 넣어 두기","correct":true},{"t":"교실에서 발표회를 하기","mis":"K6-2-u4-X26"},{"t":"학급 알림판에 붙여 친구들과 나누기","mis":"K6-2-u4-X26"},{"t":"학급 온라인 게시판에 올려 댓글로 생각 나누기","mis":"K6-2-u4-X26"}],"explanation":["다짐문은 여러 방법으로 공유해요.","발표회, 학급 알림판, 학급 온라인 게시판을 쓸 수 있어요.","함께 나누면 다짐이 삶으로 이어지기 쉬워요."],"asset":{"type":"speech","turns":[{"who":"안내 1","text":"“완성한 실천 다짐문은 교실에서 발표회를 하거나 학급 알림판에 붙여 친구들과 공유할 수 있어요.”"},{"who":"안내 2","text":"“학급 온라인 게시판에 게시하는 방법도 있어요. 학급 온라인 게시판에 글을 올리면 서로의 생각을 댓글로 공유할 수 있어요.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L08_challenge#3','kor',6,2,'u4','L08','tb_g6_2_kor_u4_L08_challenge','lesson_challenge','K6-2-u4-C15',3,'error','auto','친구의 실천 다짐문을 읽고 고칠 점을 이야기했어요. 알맞지 않게 말한 것은 무엇인가요?',ARRAY['K6-2-u4-X24','K6-2-u4-X22','K6-2-u4-X23']::text[],false,'{"seq":3,"concept":"K6-2-u4-C15","difficulty":3,"kind":"error","stem":"친구의 실천 다짐문을 읽고 고칠 점을 이야기했어요. 알맞지 않게 말한 것은 무엇인가요?","options":[{"t":"㉰ “다짐 내용보다 종이 색깔이 마음에 안 들어. 색종이에 다시 써.”","correct":true,"mis_target":"K6-2-u4-X24"},{"t":"㉮ “우리말을 바르게 사용하자는 생각이 잘 드러나도록 내용을 더 넣으면 좋겠어.”","mis":"K6-2-u4-X22"},{"t":"㉯ “실천 가능한 내용이면 좋을 것 같아.”","mis":"K6-2-u4-X23"}],"explanation":["고칠 점은 다짐문의 내용에서 찾아요.","종이 색깔 같은 겉모습은 다짐을 더 좋게 만들지 못해요.","㉮, ㉯처럼 내용을 바꿀 방향을 말해 주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L08_challenge#4','kor',6,2,'u4','L08','tb_g6_2_kor_u4_L08_challenge','lesson_challenge','K6-2-u4-C15',3,'mc','auto','다음 다짐 가운데 실천 가능하고 구체적인 다짐은 무엇인가요?',ARRAY['K6-2-u4-X23']::text[],false,'{"seq":4,"concept":"K6-2-u4-C15","difficulty":3,"kind":"mc","stem":"다음 다짐 가운데 실천 가능하고 구체적인 다짐은 무엇인가요?","options":[{"t":"“친구에게 문자를 보낼 때 줄임말 대신 바른 우리말로 쓰겠다.”","correct":true},{"t":"“우리말을 열심히 사랑하겠다.”","mis":"K6-2-u4-X23"},{"t":"“앞으로 외래어를 평생 한 번도 쓰지 않겠다.”","mis":"K6-2-u4-X23"},{"t":"“다들 바른말을 쓰면 좋겠다.”","mis":"K6-2-u4-X23"}],"explanation":["좋은 다짐은 언제, 무엇을 할지가 드러나요.","지킬 수 없을 만큼 큰 다짐은 실천하기 어려워요.","‘다들’처럼 내가 할 일이 없는 다짐도 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L08_challenge#5','kor',6,2,'u4','L08','tb_g6_2_kor_u4_L08_challenge','lesson_challenge','K6-2-u4-C14',3,'mc','auto','언어생활 점검표를 쓰고 결과를 나눌 때 지켜야 할 태도로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u4-X21']::text[],false,'{"seq":5,"concept":"K6-2-u4-C14","difficulty":3,"kind":"mc","stem":"언어생활 점검표를 쓰고 결과를 나눌 때 지켜야 할 태도로 가장 알맞은 것은 무엇인가요?","options":[{"t":"친구를 비난하거나 놀리지 않고, 점검하는 목적을 생각하며 함께 고쳐 나간다","correct":true},{"t":"줄임말을 많이 쓴 친구의 이름을 반 전체에 알린다","mis":"K6-2-u4-X21"},{"t":"내 것은 빼고 친구들의 잘못만 적는다","mis":"K6-2-u4-X21"},{"t":"점검표는 혼자 몰래 쓰고 아무와도 나누지 않는다","mis":"K6-2-u4-X21"}],"explanation":["점검은 흠잡기가 아니에요.","모둠 활동으로 함께 점검하며 바르게 쓸 필요성을 느껴요.","내 언어생활부터 솔직하게 돌아봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L08_challenge#6','kor',6,2,'u4','L08','tb_g6_2_kor_u4_L08_challenge','lesson_challenge','K6-2-u4-C15',3,'match','auto','다짐문 예시의 문장과 그 문장이 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u4-C15","difficulty":3,"kind":"match","stem":"다짐문 예시의 문장과 그 문장이 하는 일을 알맞게 이으세요.","pairs":[{"l":"“우리말 지킴이 실천 다짐문”","r":"제목"},{"l":"“…지키고 바르게 사용하고자 다음과 같이 다짐합니다.”","r":"목적"},{"l":"“하나, 나는 일상생활에서 불필요한 외래어 사용을 줄이고 …”","r":"구체적인 실천 약속"},{"l":"“소중한 우리말을 바르게 사용하려고 열심히 노력할 것을 약속합니다.”","r":"전하고 싶은 말"}],"mis":"K6-2-u4-X22","explanation":["제목은 무엇에 대한 다짐인지 알려 줘요.","목적 다음에 ‘하나,’로 실천 약속을 써요.","마지막에 전하고 싶은 말과 날짜, 쓴 사람을 써요."],"asset":{"type":"passage","lines":["우리말 지킴이 실천 다짐문","나는 아름답고 소중한 우리말을 지키고 바르게 사용하고자 다음과 같이 다짐합니다.","하나, 나는 일상생활에서 불필요한 외래어 사용을 줄이고, 고유어를 적극적으로 찾아 사용하겠습니다.","하나, 나는 뜻을 알기 어려운 말이나 지나친 줄임말보다는 표준어를 사용하려고 노력하겠습니다.","하나, 나는 비속어나 욕설을 사용하지 않고, 긍정적이고 예쁜 말을 사용해 상대를 존중하겠습니다.","소중한 우리말을 바르게 사용하려고 열심히 노력할 것을 약속합니다.","20○○년 ○○월 ○○일 · ○○○"],"numbered":false,"title":"실천 다짐문 예시 — 『국어』 209쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L08_challenge#7','kor',6,2,'u4','L08','tb_g6_2_kor_u4_L08_challenge','lesson_challenge','K6-2-u4-C14',3,'mc','auto','『국어』 211쪽 ‘점검하기’에서 실천 다짐문의 내용을 실천한 뒤 스스로 확인하는 것은 무엇인가요?',ARRAY['K6-2-u4-X26','K6-2-u4-X21']::text[],false,'{"seq":7,"concept":"K6-2-u4-C14","difficulty":3,"kind":"mc","stem":"『국어』 211쪽 ‘점검하기’에서 실천 다짐문의 내용을 실천한 뒤 스스로 확인하는 것은 무엇인가요?","options":[{"t":"자신의 언어생활에서 변화한 점과 앞으로 노력할 점","correct":true},{"t":"다짐문을 몇 번 읽었는지","mis":"K6-2-u4-X26"},{"t":"친구 다짐문에 틀린 글자가 몇 개인지","mis":"K6-2-u4-X21"},{"t":"다짐문을 쓴 날 하루 동안 지켰는지만","mis":"K6-2-u4-X26"}],"explanation":["점검하기는 자기 평가예요.","실천한 뒤 변화한 점과 노력할 점을 써 보며 성찰해요.","다짐은 쓴 날로 끝나지 않고 이어서 실천해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L08_challenge#8','kor',6,2,'u4','L08','tb_g6_2_kor_u4_L08_challenge','lesson_challenge','K6-2-u4-C15',4,'essay','teacher','우리 반 언어생활 실태를 바탕으로 『국어』 209쪽처럼 실천 다짐문을 쓰세요. 목적, 실천 약속 두 가지, 전하고 싶은 말, 날짜와 쓴 사람을 모두 넣으세요.','{}'::text[],false,'{"seq":8,"concept":"K6-2-u4-C15","difficulty":4,"kind":"essay","stem":"우리 반 언어생활 실태를 바탕으로 『국어』 209쪽처럼 실천 다짐문을 쓰세요. 목적, 실천 약속 두 가지, 전하고 싶은 말, 날짜와 쓴 사람을 모두 넣으세요.","answer_guide":{"answer":"예: 우리말 지킴이 실천 다짐문 / 나는 소중한 우리말을 바르게 사용하고자 다음과 같이 다짐합니다. / 하나, 나는 친구와 대화할 때 지나친 줄임말 대신 바른 우리말을 쓰겠습니다. / 하나, 나는 고유어로 바꿀 수 있는 외래어는 고유어로 바꾸어 쓰겠습니다. / 우리말을 아끼는 마음을 꼭 지킬 것을 약속합니다. / 20○○년 ○○월 ○○일 ○○○","scoring_points":["목적, 실천 약속, 전하고 싶은 말, 날짜와 쓴 사람을 갖추었는가","실천 약속이 구체적이고 지킬 수 있는가","우리 반 언어생활 실태와 이어지는가"]},"explanation":["실태 조사에서 고칠 점을 먼저 떠올려요.","실천 약속은 언제, 무엇을 할지 드러나게 써요.","마지막에 날짜와 쓴 사람을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L08_challenge#9','kor',6,2,'u4','L08','tb_g6_2_kor_u4_L08_challenge','lesson_challenge','K6-2-u4-C14',4,'essay','teacher','『국어』 206쪽 (2)처럼 자신과 모둠원의 언어생활 실태를 묻고 답하는 질문을 두 가지 만들고, 각 질문에 대한 자신의 답을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u4-C14","difficulty":4,"kind":"essay","stem":"『국어』 206쪽 (2)처럼 자신과 모둠원의 언어생활 실태를 묻고 답하는 질문을 두 가지 만들고, 각 질문에 대한 자신의 답을 쓰세요.","answer_guide":{"answer":"예: ① 질문 — 줄임말을 많이 사용하는 까닭은 무엇인가요? / 답 — 빨리 쓰고 싶어서 습관처럼 쓴 것 같다. ② 질문 — 어떤 점을 고쳐야 할까요? / 답 — 모르는 사람도 알아듣게 줄임말을 줄여야 한다.","scoring_points":["언어생활 실태를 묻는 질문을 두 가지 만들었는가","각 질문에 솔직하게 답했는가","고칠 점이나 바라는 점으로 이어졌는가"]},"explanation":["점검표의 결과를 보고 궁금한 점을 질문으로 만들어요.","까닭, 고칠 점, 바라는 점을 물을 수 있어요.","친구를 탓하지 않고 함께 생각해요."],"asset":{"type":"passage","lines":["[질문] 어떤 점을 고쳐야 할까요?","[질문] 줄임말을 많이 사용하는 까닭은 무엇인가요?","[질문] 외래어를 무분별하게 사용하는 까닭은 무엇인가요?"],"numbered":false,"title":"언어생활 실태를 묻고 답하는 질문 — 『국어』 206쪽 (2)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L08_challenge#10','kor',6,2,'u4','L08','tb_g6_2_kor_u4_L08_challenge','lesson_challenge','K6-2-u4-C15',4,'essay','teacher','실천 다짐문의 내용을 일주일 동안 실천한다고 생각하고, 『국어』 211쪽 ‘점검하기’처럼 변화한 점과 노력할 점을 하나씩 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u4-C15","difficulty":4,"kind":"essay","stem":"실천 다짐문의 내용을 일주일 동안 실천한다고 생각하고, 『국어』 211쪽 ‘점검하기’처럼 변화한 점과 노력할 점을 하나씩 쓰세요.","answer_guide":{"answer":"예: 변화한 점 — 친구에게 문자를 보낼 때 줄임말 대신 바른 우리말로 쓰게 되었다. / 노력할 점 — 화가 날 때 나도 모르게 거친 말이 나오니 고운 말로 바꾸어 말하도록 노력하겠다.","scoring_points":["실천 다짐과 이어지는 변화한 점을 썼는가","앞으로 노력할 점을 썼는가","솔직하고 구체적으로 썼는가"]},"explanation":["다짐문의 실천 약속을 떠올려요.","실제로 달라진 점과 아직 부족한 점을 나누어 써요.","노력할 점은 실천할 수 있게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L11_basic#1','kor',6,2,'u4','L11','tb_g6_2_kor_u4_L11_basic','lesson_basic','K6-2-u4-C16',1,'mc','auto','『국어』 212쪽 홍보물 만들기에서 홍보물로 표현하는 방법으로 든 것은 무엇인가요?',ARRAY['K6-2-u4-X27','K6-2-u4-X25']::text[],false,'{"seq":1,"concept":"K6-2-u4-C16","difficulty":1,"kind":"mc","stem":"『국어』 212쪽 홍보물 만들기에서 홍보물로 표현하는 방법으로 든 것은 무엇인가요?","options":[{"t":"홍보 영상, 노래, 인쇄물, 만화","correct":true},{"t":"일기, 독후감, 받아쓰기","mis":"K6-2-u4-X27"},{"t":"외국어 표어, 줄임말 사전","mis":"K6-2-u4-X25"},{"t":"벌점 표, 경고문","mis":"K6-2-u4-X25"}],"explanation":["어떤 방법으로 표현할지 먼저 정해요.","홍보 영상, 노래, 인쇄물, 만화 가운데에서 골라요.","빈칸에 다른 방법을 더 쓸 수도 있어요."],"asset":{"type":"passage","lines":["[방법] 홍보 영상 · 노래 · 인쇄물 · 만화","[내용] 우리말의 아름다움을 알리는 내용 · 우리말을 바르게 사용하자는 내용","[예] “아름다운 우리말 함께 지켜요!” · “우리말 바르게 사용하기”"],"numbered":false,"title":"이런 활동도 있어요 — 홍보물 만들기 『국어』 212쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L11_basic#2','kor',6,2,'u4','L11','tb_g6_2_kor_u4_L11_basic','lesson_basic','K6-2-u4-C24',1,'mc','auto','「야, 겨울 온다」에 나오는 고유어 ‘길섶’의 뜻은 무엇인가요?',ARRAY['K6-2-u4-X34']::text[],false,'{"seq":2,"concept":"K6-2-u4-C24","difficulty":1,"kind":"mc","stem":"「야, 겨울 온다」에 나오는 고유어 ‘길섶’의 뜻은 무엇인가요?","options":[{"t":"길의 가장자리","correct":true},{"t":"길 한가운데","mis":"K6-2-u4-X34"},{"t":"숲속의 좁은 오솔길","mis":"K6-2-u4-X34"},{"t":"길에 핀 풀꽃","mis":"K6-2-u4-X34"}],"explanation":["‘길섶 나무들아’는 길 가장자리에 선 나무들을 부르는 말이에요.","길섶은 길의 가장자리예요.","『국어』 215쪽 2번에서 사전으로 뜻을 찾았어요."],"asset":{"type":"passage","lines":["제비 떠나가고 기러기 돌아왔다.","쑥부쟁인 아직도 방그레 웃어 걱정이다.","길섶 나무들아 따스운 옷을 입어라.","(간추림) 오소리랑 너구리는 긴 잠에 들고, 미꾸리들에게는 도랑 깊이 숨으라고 한다.","걸음마다 바삭바삭","(간추림) 마지막에 겨울이 온다고 반갑게 외친다."],"title":"「야, 겨울 온다」(강순예 글) — 『국어』 214쪽","hi":["방그레","길섶","바삭바삭"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L11_basic#3','kor',6,2,'u4','L11','tb_g6_2_kor_u4_L11_basic','lesson_basic','K6-2-u4-C16',1,'ox','auto','홍보물을 만들 때에는 소외되는 친구가 없도록 구체적으로 역할을 정해요.',ARRAY['K6-2-u4-X25']::text[],false,'{"seq":3,"concept":"K6-2-u4-C16","difficulty":1,"kind":"ox","stem":"홍보물을 만들 때에는 소외되는 친구가 없도록 구체적으로 역할을 정해요.","answer":"O","reason_options":[{"t":"모두가 맡은 일이 있어야 함께 홍보물을 완성할 수 있어요.","correct":true},{"t":"역할은 정하지 말고 잘하는 친구 한 명이 다 만들어요.","mis":"K6-2-u4-X25"}],"mis":"K6-2-u4-X25","explanation":["홍보물을 만들 때 역할을 구체적으로 나누어요.","시간과 역할을 계획할 때 미리 정해요.","모두가 참여해야 우리말 지킴이 활동이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L11_basic#4','kor',6,2,'u4','L11','tb_g6_2_kor_u4_L11_basic','lesson_basic','K6-2-u4-C25',1,'mc','auto','『국어』 217쪽 기초 다지기예요. “기온, 비, 눈, 바람 따위의 대기 상태.”를 뜻하는 낱말은 무엇인가요?',ARRAY['K6-2-u4-X35']::text[],false,'{"seq":4,"concept":"K6-2-u4-C25","difficulty":1,"kind":"mc","stem":"『국어』 217쪽 기초 다지기예요. “기온, 비, 눈, 바람 따위의 대기 상태.”를 뜻하는 낱말은 무엇인가요?","options":[{"t":"기후","correct":true},{"t":"강수량","mis":"K6-2-u4-X35"},{"t":"교류","mis":"K6-2-u4-X35"},{"t":"연소","mis":"K6-2-u4-X35"}],"explanation":["기후는 기온, 비, 눈, 바람 따위의 대기 상태예요.","“최근 들어 전 세계적으로 급격한 기후 변화가 나타나고 있다.”처럼 써요.","교과 학습에 자주 나오는 낱말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L11_basic#5','kor',6,2,'u4','L11','tb_g6_2_kor_u4_L11_basic','lesson_basic','K6-2-u4-C24',2,'mc','auto','“쑥부쟁인 아직도 방그레 웃어 걱정이다.”에서 ‘방그레’의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u4-X34']::text[],false,'{"seq":5,"concept":"K6-2-u4-C24","difficulty":2,"kind":"mc","stem":"“쑥부쟁인 아직도 방그레 웃어 걱정이다.”에서 ‘방그레’의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"입만 예쁘게 조금 벌리고 소리 없이 보드랍게 웃는 모양","correct":true},{"t":"입을 크게 벌리고 큰 소리로 껄껄 웃는 모양","mis":"K6-2-u4-X34"},{"t":"눈물을 흘리며 소리 내어 엉엉 우는 모양","mis":"K6-2-u4-X34"},{"t":"바람에 이리저리 가볍게 흔들리는 모양","mis":"K6-2-u4-X34"}],"explanation":["방그레는 소리 없이 보드랍게 웃는 모양이에요.","쑥부쟁이꽃이 피어 있는 모습을 웃는 얼굴에 빗대었어요.","‘아기가 나를 보고 방그레 웃었다.’처럼 쓸 수 있어요."],"asset":{"type":"passage","lines":["제비 떠나가고 기러기 돌아왔다.","쑥부쟁인 아직도 방그레 웃어 걱정이다.","길섶 나무들아 따스운 옷을 입어라.","(간추림) 오소리랑 너구리는 긴 잠에 들고, 미꾸리들에게는 도랑 깊이 숨으라고 한다.","걸음마다 바삭바삭","(간추림) 마지막에 겨울이 온다고 반갑게 외친다."],"title":"「야, 겨울 온다」(강순예 글) — 『국어』 214쪽","hi":["방그레","길섶","바삭바삭"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L11_basic#6','kor',6,2,'u4','L11','tb_g6_2_kor_u4_L11_basic','lesson_basic','K6-2-u4-C24',2,'mc','auto','「야, 겨울 온다」의 ‘걸음마다 바삭바삭’에서 ‘바삭바삭’이 나타내는 것은 무엇인가요?',ARRAY['K6-2-u4-X34']::text[],false,'{"seq":6,"concept":"K6-2-u4-C24","difficulty":2,"kind":"mc","stem":"「야, 겨울 온다」의 ‘걸음마다 바삭바삭’에서 ‘바삭바삭’이 나타내는 것은 무엇인가요?","options":[{"t":"가랑잎 같은 잘 마른 물건을 잇따라 가볍게 밟는 소리나 모양","correct":true},{"t":"단단한 물건을 세게 잇따라 두드리는 소리","mis":"K6-2-u4-X34"},{"t":"눈이 소리 없이 펑펑 쏟아져 내리는 모양","mis":"K6-2-u4-X34"},{"t":"시냇물이 졸졸 흐르며 내는 맑은 소리","mis":"K6-2-u4-X34"}],"explanation":["앞 줄에서 나뭇잎이 떨어진다고 했어요.","걸을 때마다 마른 잎을 밟는 소리가 나요.","흉내 내는 고유어로 늦가을 길의 느낌을 살렸어요."],"asset":{"type":"passage","lines":["제비 떠나가고 기러기 돌아왔다.","쑥부쟁인 아직도 방그레 웃어 걱정이다.","길섶 나무들아 따스운 옷을 입어라.","(간추림) 오소리랑 너구리는 긴 잠에 들고, 미꾸리들에게는 도랑 깊이 숨으라고 한다.","걸음마다 바삭바삭","(간추림) 마지막에 겨울이 온다고 반갑게 외친다."],"title":"「야, 겨울 온다」(강순예 글) — 『국어』 214쪽","hi":["방그레","길섶","바삭바삭"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L11_basic#7','kor',6,2,'u4','L11','tb_g6_2_kor_u4_L11_basic','lesson_basic','K6-2-u4-C16',2,'mc','auto','『국어』 212쪽에서 홍보물에 어떤 내용을 쓸지 고를 때 보기로 든 두 가지는 무엇인가요?',ARRAY['K6-2-u4-X25','K6-2-u4-X13']::text[],false,'{"seq":7,"concept":"K6-2-u4-C16","difficulty":2,"kind":"mc","stem":"『국어』 212쪽에서 홍보물에 어떤 내용을 쓸지 고를 때 보기로 든 두 가지는 무엇인가요?","options":[{"t":"우리말의 아름다움을 알리는 내용, 우리말을 바르게 사용하자는 내용","correct":true},{"t":"외국어를 더 배우자는 내용, 줄임말을 모으자는 내용","mis":"K6-2-u4-X25"},{"t":"다른 반을 탓하는 내용, 벌칙을 정하는 내용","mis":"K6-2-u4-X25"},{"t":"뜻 없이 그림만 가득한 내용","mis":"K6-2-u4-X13"}],"explanation":["홍보물의 주제는 아름다운 우리말의 소중함이에요.","우리말의 아름다움을 알리거나 바르게 사용하자는 내용을 써요.","홍보 목적이 잘 드러나게 만들어요."],"asset":{"type":"passage","lines":["[방법] 홍보 영상 · 노래 · 인쇄물 · 만화","[내용] 우리말의 아름다움을 알리는 내용 · 우리말을 바르게 사용하자는 내용","[예] “아름다운 우리말 함께 지켜요!” · “우리말 바르게 사용하기”"],"numbered":false,"title":"이런 활동도 있어요 — 홍보물 만들기 『국어』 212쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L11_basic#8','kor',6,2,'u4','L11','tb_g6_2_kor_u4_L11_basic','lesson_basic','K6-2-u4-C25',2,'blank','auto','『국어』 217쪽 기초 다지기의 예문 “초가 (     )하면 길이가 짧아진다.”의 빈칸에 알맞은 낱말은 무엇인가요?',ARRAY['K6-2-u4-X35']::text[],false,'{"seq":8,"concept":"K6-2-u4-C25","difficulty":2,"kind":"blank","stem":"『국어』 217쪽 기초 다지기의 예문 “초가 (     )하면 길이가 짧아진다.”의 빈칸에 알맞은 낱말은 무엇인가요?","options":[{"t":"연소","correct":true},{"t":"소화","mis":"K6-2-u4-X35"},{"t":"교류","mis":"K6-2-u4-X35"},{"t":"기후","mis":"K6-2-u4-X35"}],"explanation":["연소는 물질이 산소와 빠르게 반응해 열과 빛을 내며 타는 현상이에요.","초가 타면 길이가 짧아져요.","그래서 빈칸에는 ‘연소’가 들어가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L11_basic#9','kor',6,2,'u4','L11','tb_g6_2_kor_u4_L11_basic','lesson_basic','K6-2-u4-C16',2,'mc','auto','『국어』 213쪽에서 우리가 정한 활동을 할 때 함께 정하라고 한 것은 무엇인가요?',ARRAY['K6-2-u4-X25','K6-2-u4-X26']::text[],false,'{"seq":9,"concept":"K6-2-u4-C16","difficulty":2,"kind":"mc","stem":"『국어』 213쪽에서 우리가 정한 활동을 할 때 함께 정하라고 한 것은 무엇인가요?","options":[{"t":"반 전체가 할지, 모둠으로 할지, 짝과 할지, 혼자 할지","correct":true},{"t":"누가 가장 먼저 끝내는지 모둠끼리 시합할지","mis":"K6-2-u4-X25"},{"t":"활동을 하루만 하고 그 뒤로는 그만둘지","mis":"K6-2-u4-X26"},{"t":"활동 이름을 멋있는 외국어로 붙일지","mis":"K6-2-u4-X25"}],"explanation":["하고 싶은 활동을 정한 다음 함께할 사람을 정해요.","반 전체, 모둠, 짝, 혼자 가운데에서 골라요.","활동한 뒤에는 소감을 나누어요."],"asset":{"type":"passage","lines":["① 하고 싶은 활동 정하기","→ 우리가 정한 활동을 반 전체가 할지, 모둠으로 할지, 짝과 할지, 혼자 할지 정해요.","② 활동하기","③ 활동 소감 나누기"],"numbered":false,"title":"우리가 활동을 정해요 — 『국어』 213쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L11_basic#10','kor',6,2,'u4','L11','tb_g6_2_kor_u4_L11_basic','lesson_basic','K6-2-u4-C16',3,'mc','auto','우리말 지킴이 활동을 한 번으로 끝내지 않고 실천 의지를 기를 수 있는 활동으로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u4-X26','K6-2-u4-X25']::text[],false,'{"seq":10,"concept":"K6-2-u4-C16","difficulty":3,"kind":"mc","stem":"우리말 지킴이 활동을 한 번으로 끝내지 않고 실천 의지를 기를 수 있는 활동으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"우리말 일기를 꾸준히 쓰는 활동","correct":true},{"t":"홍보물을 한 번 붙이고 바로 떼는 활동","mis":"K6-2-u4-X26"},{"t":"하루 동안만 고유어를 쓰는 행사","mis":"K6-2-u4-X26"},{"t":"외국어 표어를 크게 써 붙이는 활동","mis":"K6-2-u4-X25"}],"explanation":["한 번 하고 끝나는 활동보다 꾸준히 하는 활동이 좋아요.","우리말 일기 쓰기, 우리말 지킴이 도전 활동, 교실 언어 환경 개선 계획 같은 활동을 할 수 있어요.","꾸준히 하면 바른 우리말 사용이 몸에 배어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L11_challenge#1','kor',6,2,'u4','L11','tb_g6_2_kor_u4_L11_challenge','lesson_challenge','K6-2-u4-C25',2,'match','auto','『국어』 217쪽 기초 다지기 1번이에요. 낱말과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u4-C25","difficulty":2,"kind":"match","stem":"『국어』 217쪽 기초 다지기 1번이에요. 낱말과 뜻을 알맞게 이으세요.","pairs":[{"l":"강수량","r":"비, 눈, 우박, 안개 따위로 일정 기간 일정한 곳에 내린 물의 양"},{"l":"교류","r":"문화나 사상 따위가 서로 통함"},{"l":"소화","r":"섭취한 음식물을 분해하여 영양분을 흡수하기 쉬운 형태로 변화시키는 일"},{"l":"연소","r":"물질이 공기 중의 산소와 빠르게 반응해 열과 빛을 내며 타는 현상"}],"mis":"K6-2-u4-X35","explanation":["강수량은 내린 물의 양이에요.","교류는 서로 통함, 소화는 음식물을 분해하는 일이에요.","연소는 열과 빛을 내며 타는 현상이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L11_challenge#2','kor',6,2,'u4','L11','tb_g6_2_kor_u4_L11_challenge','lesson_challenge','K6-2-u4-C24',2,'mc','auto','「야, 겨울 온다」의 ‘따스운 옷’과 이어지는 고유어 ‘따습다’의 뜻은 무엇인가요?',ARRAY['K6-2-u4-X34']::text[],false,'{"seq":2,"concept":"K6-2-u4-C24","difficulty":2,"kind":"mc","stem":"「야, 겨울 온다」의 ‘따스운 옷’과 이어지는 고유어 ‘따습다’의 뜻은 무엇인가요?","options":[{"t":"알맞게 따뜻하다","correct":true},{"t":"몹시 뜨겁다","mis":"K6-2-u4-X34"},{"t":"조금 차갑다","mis":"K6-2-u4-X34"},{"t":"축축하게 젖다","mis":"K6-2-u4-X34"}],"explanation":["따습다는 알맞게 따뜻하다는 뜻이에요.","겨울을 앞둔 나무들에게 따뜻한 옷을 입으라고 했어요.","나무를 사람처럼 아끼는 마음이 느껴져요."],"asset":{"type":"passage","lines":["[뜻] 방그레 — 입만 예쁘게 조금 벌리고 소리 없이 보드랍게 웃는 모양.","[뜻] 길섶 — 길의 가장자리.","[뜻] 따습다 — 알맞게 따뜻하다.","[뜻] 바삭바삭 — 가랑잎 같은 잘 마른 물건을 잇따라 가볍게 밟는 소리. 또는 그 모양."],"numbered":false,"title":"「야, 겨울 온다」에 나오는 고유어의 뜻 — 『국어』 215쪽 2번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L11_challenge#3','kor',6,2,'u4','L11','tb_g6_2_kor_u4_L11_challenge','lesson_challenge','K6-2-u4-C16',3,'mc','auto','고유어를 몸짓으로 전달하기 놀이의 ④에 들어갈 내용으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u4-X27']::text[],false,'{"seq":3,"concept":"K6-2-u4-C16","difficulty":3,"kind":"mc","stem":"고유어를 몸짓으로 전달하기 놀이의 ④에 들어갈 내용으로 알맞은 것은 무엇인가요?","options":[{"t":"두 번째 친구는 고유어의 뜻을 몸짓으로 그다음 순서의 친구에게 표현한다","correct":true},{"t":"두 번째 친구는 고유어를 소리 내어 크게 읽어 준다","mis":"K6-2-u4-X27"},{"t":"두 번째 친구는 공책에 고유어의 뜻을 써서 보여 준다","mis":"K6-2-u4-X27"},{"t":"두 번째 친구가 바로 정답을 외친다","mis":"K6-2-u4-X27"}],"explanation":["이 놀이는 고유어의 뜻을 몸으로 표현하는 놀이예요.","두 번째 친구가 본 고유어의 뜻을 몸짓으로 나타내요.","말이나 글로 알려 주면 놀이의 목적과 맞지 않아요."],"asset":{"type":"passage","lines":["① 모둠 친구들과 고유어와 그 뜻을 조사하고 공책에 고유어만 쓴다.","② 차례를 정하고 한 줄로 선다.","③ 맨 앞의 친구가 공책을 펼쳐 두 번째 친구에게 고유어를 보여 준다.","④ (                    )","⑤ 앞의 친구가 표현한 몸짓을 그대로 흉내 내어 마지막 친구에게까지 전달한다.","⑥ 마지막 친구가 고유어를 외치고 맨 앞의 친구가 정오를 확인한다."],"numbered":false,"title":"우리 반에서 정한 활동 예시 1 — 고유어를 몸짓으로 전달하기 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L11_challenge#4','kor',6,2,'u4','L11','tb_g6_2_kor_u4_L11_challenge','lesson_challenge','K6-2-u4-C24',3,'mc','auto','『국어』 215쪽 2번처럼 「야, 겨울 온다」의 고유어를 뜻에 맞게 넣어 만든 문장은 무엇인가요?',ARRAY['K6-2-u4-X34']::text[],false,'{"seq":4,"concept":"K6-2-u4-C24","difficulty":3,"kind":"mc","stem":"『국어』 215쪽 2번처럼 「야, 겨울 온다」의 고유어를 뜻에 맞게 넣어 만든 문장은 무엇인가요?","options":[{"t":"“길섶에 핀 들꽃을 보며 천천히 걸었다.”","correct":true},{"t":"“길섶에서 시원하게 수영을 했다.”","mis":"K6-2-u4-X34"},{"t":"“따스운 얼음물을 벌컥벌컥 마셨다.”","mis":"K6-2-u4-X34"},{"t":"“방그레 소리치며 화를 냈다.”","mis":"K6-2-u4-X34"}],"explanation":["길섶은 길의 가장자리라서 들꽃이 필 수 있어요.","따습다는 알맞게 따뜻하다는 뜻이라 얼음물과 어울리지 않아요.","방그레는 소리 없이 웃는 모양이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L11_challenge#5','kor',6,2,'u4','L11','tb_g6_2_kor_u4_L11_challenge','lesson_challenge','K6-2-u4-C16',3,'error','auto','아름다운 우리말의 소중함을 알리는 홍보물을 만들 계획을 세웠어요. 알맞지 않은 것은 무엇인가요?',ARRAY['K6-2-u4-X25','K6-2-u4-X13']::text[],false,'{"seq":5,"concept":"K6-2-u4-C16","difficulty":3,"kind":"error","stem":"아름다운 우리말의 소중함을 알리는 홍보물을 만들 계획을 세웠어요. 알맞지 않은 것은 무엇인가요?","options":[{"t":"㉰ “‘우리말 러브 캠페인’처럼 외국어를 섞은 문구가 더 눈에 띌 거야.”","correct":true,"mis_target":"K6-2-u4-X25"},{"t":"㉮ “표현할 방법을 먼저 정하고 들어갈 내용과 강조할 부분도 함께 정하자.”","mis":"K6-2-u4-X13"},{"t":"㉯ “시간이 많이 걸리니 계획할 때 시간과 역할을 미리 나누자.”","mis":"K6-2-u4-X25"}],"explanation":["우리말을 알리는 홍보물에 외국어 문구를 쓰면 목적과 맞지 않아요.","방법뿐 아니라 내용과 강조할 부분도 미리 정해요.","시간과 역할을 미리 나누면 모두가 참여할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L11_challenge#6','kor',6,2,'u4','L11','tb_g6_2_kor_u4_L11_challenge','lesson_challenge','K6-2-u4-C25',3,'blank','auto','『국어』 217쪽 기초 다지기 2번 예시 답안 “이 지역은 (     )이 적은 편이다.”의 빈칸에 알맞은 낱말은 무엇인가요?',ARRAY['K6-2-u4-X35']::text[],false,'{"seq":6,"concept":"K6-2-u4-C25","difficulty":3,"kind":"blank","stem":"『국어』 217쪽 기초 다지기 2번 예시 답안 “이 지역은 (     )이 적은 편이다.”의 빈칸에 알맞은 낱말은 무엇인가요?","options":[{"t":"강수량","correct":true},{"t":"기후","mis":"K6-2-u4-X35"},{"t":"교류","mis":"K6-2-u4-X35"},{"t":"소화","mis":"K6-2-u4-X35"}],"explanation":["적은 편이라고 했으니 양을 나타내는 낱말이 들어가요.","강수량은 일정한 곳에 내린 물의 양이에요.","기후는 서늘하다, 따뜻하다처럼 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L11_challenge#7','kor',6,2,'u4','L11','tb_g6_2_kor_u4_L11_challenge','lesson_challenge','K6-2-u4-C24',3,'mc','auto','『국어』 215쪽 3번에서 「야, 겨울 온다」를 읽고 바른 우리말 사용 태도를 알맞게 이야기한 것은 무엇인가요?',ARRAY['K6-2-u4-X03','K6-2-u4-X06','K6-2-u4-X02']::text[],false,'{"seq":7,"concept":"K6-2-u4-C24","difficulty":3,"kind":"mc","stem":"『국어』 215쪽 3번에서 「야, 겨울 온다」를 읽고 바른 우리말 사용 태도를 알맞게 이야기한 것은 무엇인가요?","options":[{"t":"“고유어를 사용하니 시의 느낌이 더 생생하게 느껴졌어. 앞으로 우리말을 소중하게 생각하고 사용해야겠어.”","correct":true},{"t":"“외국어가 더 멋지니 이 시도 외국어를 섞어 바꾸어 쓰고 싶어.”","mis":"K6-2-u4-X03"},{"t":"“고유어는 시에만 쓰는 말이니 평소 대화에서는 안 써도 돼.”","mis":"K6-2-u4-X06"},{"t":"“고유어 말고 다른 갈래의 말은 모두 틀린 말이니 버려야 해.”","mis":"K6-2-u4-X02"}],"explanation":["고유어가 시의 느낌을 생생하게 만들어 주었어요.","앞으로 우리말을 소중하게 생각하고 쓰겠다는 다짐이에요.","다른 갈래의 낱말이 틀렸다는 뜻은 아니에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"“외국어를 쓰는 게 멋져 보여서 많이 사용했는데 고유어를 많이 사용하도록 노력해야겠어.”"},{"who":"친구 2","text":"“우리말의 아름다움을 친구들에게 알릴 수 있도록 나부터 우리말을 바르게 사용해야겠어.”"},{"who":"친구 3","text":"“고유어를 사용하니 시의 느낌이 더 생생하게 느껴졌어. 앞으로 우리말을 소중하게 생각하고 사용해야겠어.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L11_challenge#8','kor',6,2,'u4','L11','tb_g6_2_kor_u4_L11_challenge','lesson_challenge','K6-2-u4-C24',4,'essay','teacher','「야, 겨울 온다」에 나오는 고유어 가운데 하나를 골라 뜻을 쓰고, 그 고유어를 넣어 문장을 만드세요. 그 고유어가 시에 어떤 느낌을 주는지도 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K6-2-u4-C24","difficulty":4,"kind":"essay","stem":"「야, 겨울 온다」에 나오는 고유어 가운데 하나를 골라 뜻을 쓰고, 그 고유어를 넣어 문장을 만드세요. 그 고유어가 시에 어떤 느낌을 주는지도 쓰세요.","answer_guide":{"answer":"예: 바삭바삭 — 가랑잎 같은 잘 마른 물건을 잇따라 가볍게 밟는 소리. 또는 그 모양. 문장 — 공원 길을 걸으니 낙엽이 바삭바삭 소리를 냈다. 느낌 — 마른 잎을 밟는 소리가 들리는 것 같아 늦가을 길이 생생하게 느껴진다.","scoring_points":["고유어의 뜻을 바르게 썼는가","뜻에 맞게 문장을 만들었는가","고유어가 주는 느낌을 썼는가"]},"explanation":["『국어』 215쪽 2번처럼 사전에서 뜻을 찾아요.","뜻이 잘 드러나는 상황을 골라 문장을 만들어요.","시를 소리 내어 읽으며 느낌을 떠올려요."],"asset":{"type":"passage","lines":["제비 떠나가고 기러기 돌아왔다.","쑥부쟁인 아직도 방그레 웃어 걱정이다.","길섶 나무들아 따스운 옷을 입어라.","(간추림) 오소리랑 너구리는 긴 잠에 들고, 미꾸리들에게는 도랑 깊이 숨으라고 한다.","걸음마다 바삭바삭","(간추림) 마지막에 겨울이 온다고 반갑게 외친다."],"title":"「야, 겨울 온다」(강순예 글) — 『국어』 214쪽","hi":["방그레","길섶","바삭바삭"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L11_challenge#9','kor',6,2,'u4','L11','tb_g6_2_kor_u4_L11_challenge','lesson_challenge','K6-2-u4-C16',4,'essay','teacher','아름다운 우리말의 소중함을 알리는 홍보물을 만들 계획을 쓰세요. 표현 방법, 내용, 역할 나누기, 한 번으로 끝내지 않고 이어 갈 방법을 모두 넣으세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u4-C16","difficulty":4,"kind":"essay","stem":"아름다운 우리말의 소중함을 알리는 홍보물을 만들 계획을 쓰세요. 표현 방법, 내용, 역할 나누기, 한 번으로 끝내지 않고 이어 갈 방법을 모두 넣으세요.","answer_guide":{"answer":"예: 방법 — 인쇄물(포스터) / 내용 — ‘아름다운 우리말 함께 지켜요!’라는 문구와 다듬은 말 네 가지(댓글·이어달리기·붙임딱지·동아리) / 역할 — 글씨, 그림, 다듬은 말 조사, 발표를 한 사람씩 맡음 / 이어 갈 방법 — 한 달 동안 우리 반 우리말 지킴이 도전표에 매일 표시하기","scoring_points":["표현 방법과 내용을 정했는가","역할을 구체적으로 나누었는가","꾸준히 이어 갈 방법을 썼는가"]},"explanation":["표현 방법을 먼저 정하고 들어갈 내용을 정해요.","모두가 맡은 일이 있게 역할을 나누어요.","한 번으로 끝나지 않게 이어 갈 방법을 생각해요."],"asset":{"type":"passage","lines":["[방법] 홍보 영상 · 노래 · 인쇄물 · 만화","[내용] 우리말의 아름다움을 알리는 내용 · 우리말을 바르게 사용하자는 내용","[예] “아름다운 우리말 함께 지켜요!” · “우리말 바르게 사용하기”"],"numbered":false,"title":"이런 활동도 있어요 — 홍보물 만들기 『국어』 212쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_L11_challenge#10','kor',6,2,'u4','L11','tb_g6_2_kor_u4_L11_challenge','lesson_challenge','K6-2-u4-C25',4,'essay','teacher','『국어』 217쪽 기초 다지기의 낱말 가운데 두 가지를 골라, 낱말의 뜻을 생각하며 교과 공부와 이어지는 문장을 하나씩 만드세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u4-C25","difficulty":4,"kind":"essay","stem":"『국어』 217쪽 기초 다지기의 낱말 가운데 두 가지를 골라, 낱말의 뜻을 생각하며 교과 공부와 이어지는 문장을 하나씩 만드세요.","answer_guide":{"answer":"예: 교류 — 옛날부터 우리나라는 이웃 나라와 문화 교류를 해 왔다. / 소화 — 음식을 꼭꼭 씹어 먹으면 소화가 잘된다.","scoring_points":["낱말 두 가지를 골랐는가","낱말의 뜻에 맞게 문장을 만들었는가","교과 공부와 이어지는 문장인가"]},"explanation":["먼저 낱말의 뜻을 다시 확인해요.","사회, 과학처럼 그 낱말이 나오는 교과를 떠올려요.","뜻에 맞게 쓰였는지 다시 읽어 보아요."],"asset":{"type":"passage","lines":["강수량 — 비, 눈, 우박, 안개 따위로 일정 기간 일정한 곳에 내린 물의 양.","교류 — 문화나 사상 따위가 서로 통함.","기후 — 기온, 비, 눈, 바람 따위의 대기 상태.","소화 — 섭취한 음식물을 분해하여 영양분을 흡수하기 쉬운 형태로 변화시키는 일.","연소 — 물질이 공기 중의 산소와 빠르게 반응해 열과 빛을 내며 타는 현상."],"title":"기초 다지기 — 교과 학습에 사용되는 낱말 『국어』 217쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_a#1','kor',6,2,'u4','','tb_g6_2_kor_u4_review_a','unit_review','K6-2-u4-C1',1,'mc','auto','이 단원에서 배운 ‘고유어’의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u4-X01','K6-2-u4-X06']::text[],false,'{"seq":1,"concept":"K6-2-u4-C1","difficulty":1,"kind":"mc","stem":"이 단원에서 배운 ‘고유어’의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"우리말에 처음부터 있던 낱말이나 그것을 바탕으로 만들어진 낱말","correct":true},{"t":"한자로 이루어져 사전에서 한자가 함께 있는 낱말","mis":"K6-2-u4-X01"},{"t":"외국에서 들어와 우리 생활에서 널리 쓰이는 낱말","mis":"K6-2-u4-X01"},{"t":"옛날에만 쓰고 지금은 쓰지 않는 낱말","mis":"K6-2-u4-X06"}],"explanation":["고유어는 처음부터 있던 낱말과 그것을 바탕으로 만든 낱말이에요.","한자어는 한자로, 외래어는 외국에서 들어온 말로 이루어져요.","고유어는 지금도 새로 만들어질 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_a#2','kor',6,2,'u4','','tb_g6_2_kor_u4_review_a','unit_review','K6-2-u4-C2',1,'ox','auto','『국어』 179쪽 「생각 열기」에서 아이는 고유어 ‘비설거지’, ‘뒤란’의 뜻을 몰라 할머니의 말을 잘 알아듣지 못했어요.',ARRAY['K6-2-u4-X01']::text[],false,'{"seq":2,"concept":"K6-2-u4-C2","difficulty":1,"kind":"ox","stem":"『국어』 179쪽 「생각 열기」에서 아이는 고유어 ‘비설거지’, ‘뒤란’의 뜻을 몰라 할머니의 말을 잘 알아듣지 못했어요.","answer":"O","reason_options":[{"t":"아이가 “비설거지가 뭐지? 뒤란은 어디일까?” 하고 물었어요.","correct":true},{"t":"할머니가 외국어를 써서 알아듣지 못했어요.","mis":"K6-2-u4-X01"}],"mis":"K6-2-u4-X01","explanation":["할머니는 비설거지를 하자고, 뒤란에 가서 장독대를 덮으라고 했어요.","아이는 두 낱말의 뜻을 몰랐어요.","우리말을 바르게 이해하려면 낱말의 뜻을 알아야 해요."],"asset":{"type":"speech","turns":[{"who":"할머니","text":"“얼른 비설거지 해야겠다. 그래야 비를 안 맞지.”"},{"who":"할머니","text":"“뒤란에 가서 장독대를 덮고 오겠니?”"},{"who":"아이","text":"“비설거지가 뭐지? 뒤란은 어디일까?”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_a#3','kor',6,2,'u4','','tb_g6_2_kor_u4_review_a','unit_review','K6-2-u4-C18',1,'sa','auto','「조각하늘」의 ‘쏘옥’을 바른 표기로 고쳐 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"K6-2-u4-C18","difficulty":1,"kind":"sa","stem":"「조각하늘」의 ‘쏘옥’을 바른 표기로 고쳐 쓰세요.","answer":["쏙"],"explanation":["시에서는 느낌을 살리려고 ‘쏘옥’이라고 썼어요.","시 아래 풀이에 ‘쏙’이 바른 표기라고 나와 있어요.","바른 표기는 국어사전에서 확인해요."],"asset":{"type":"passage","lines":["하늘이 숨바꼭질하고 싶은가 봐요.","구름 뒤에 숨어서 나올 생각을 안 해요.","호수에 비친 자기 얼굴만","빠끔히 내다보고","구름 뒤로 쏘옥 숨어요.","(간추림) 바람이 호수를 간지럽혀도 조각하늘은 구름 뒤에서 좀처럼 나오지 않는다."],"title":"「조각하늘」(권지영 글) — 『국어』 180쪽"},"mis":"K6-2-u4-X29"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_a#4','kor',6,2,'u4','','tb_g6_2_kor_u4_review_a','unit_review','K6-2-u4-C6',1,'mc','auto','『국어』 186쪽에서 외래어 ‘스티커’를 고유어를 살려 다듬은 말은 무엇인가요?',ARRAY['K6-2-u4-X08']::text[],false,'{"seq":4,"concept":"K6-2-u4-C6","difficulty":1,"kind":"mc","stem":"『국어』 186쪽에서 외래어 ‘스티커’를 고유어를 살려 다듬은 말은 무엇인가요?","options":[{"t":"붙임딱지","correct":true},{"t":"스티카","mis":"K6-2-u4-X08"},{"t":"딱지놀이","mis":"K6-2-u4-X08"},{"t":"색종이","mis":"K6-2-u4-X08"}],"explanation":["스티커는 쉽게 붙일 수 있는 작은 조각이에요.","그 뜻을 살려 ‘붙임딱지’로 다듬었어요.","다듬은 말은 뜻을 쉽게 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_a#5','kor',6,2,'u4','','tb_g6_2_kor_u4_review_a','unit_review','K6-2-u4-C7',1,'mc','auto','「고유어의 가치」를 공부하며 알아본 ‘관용 표현’의 뜻은 무엇인가요?',ARRAY['K6-2-u4-X09','K6-2-u4-X01']::text[],false,'{"seq":5,"concept":"K6-2-u4-C7","difficulty":1,"kind":"mc","stem":"「고유어의 가치」를 공부하며 알아본 ‘관용 표현’의 뜻은 무엇인가요?","options":[{"t":"둘 이상의 낱말이 결합해 새로운 의미를 만들어 내는 표현","correct":true},{"t":"낱말 하나로만 이루어져 뜻이 하나인 표현","mis":"K6-2-u4-X09"},{"t":"낱말 뜻을 하나씩 그대로 더해서 만든 표현","mis":"K6-2-u4-X09"},{"t":"외국어 낱말을 섞어서 만든 표현","mis":"K6-2-u4-X01"}],"explanation":["관용 표현은 둘 이상의 낱말이 결합해요.","낱말 뜻을 그대로 더한 것과 다른 새로운 의미가 생겨요.","“눈도 깜짝 안 하다.”, “날개 돋치다.”가 그 예예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_a#6','kor',6,2,'u4','','tb_g6_2_kor_u4_review_a','unit_review','K6-2-u4-C21',1,'mc','auto','「큰사전이 필요하다」에서 우리글에 ‘한글’이라는 이름을 지은 사람은 누구인가요?',ARRAY['K6-2-u4-X30']::text[],false,'{"seq":6,"concept":"K6-2-u4-C21","difficulty":1,"kind":"mc","stem":"「큰사전이 필요하다」에서 우리글에 ‘한글’이라는 이름을 지은 사람은 누구인가요?","options":[{"t":"주시경","correct":true},{"t":"고종","mis":"K6-2-u4-X30"},{"t":"정태진","mis":"K6-2-u4-X30"},{"t":"서울역 역장","mis":"K6-2-u4-X30"}],"explanation":["주시경은 우리글의 이름이 한자인 것이 마음에 들지 않았어요.","‘한’에 크고 바르다는 뜻이 있다며 ‘한글’이라 부르자고 했어요.","고종의 명령으로 붙은 이름은 ‘국문’이에요."],"asset":{"type":"passage","lines":["(간추림) ‘언문’으로 불리던 한글은 고종의 명령으로 ‘국문’이 되었다.","(간추림) 주시경은 우리글의 이름이 한자인 것이 마음에 들지 않았다.","“‘한’이라는 글자에는 ‘크고 바르다’는 뜻이 있다.”","(간추림) ‘첫째가는 글’, ‘우리 겨레의 글’이라는 뜻도 담아 ‘한글’이라 부르자고 했다."],"title":"「큰사전이 필요하다」 ‘한글’이라는 이름 — 『국어』 196쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_a#7','kor',6,2,'u4','','tb_g6_2_kor_u4_review_a','unit_review','K6-2-u4-C13',1,'mc','auto','『국어』 205쪽에서 말한 ‘방언’의 뜻은 무엇인가요?',ARRAY['K6-2-u4-X19','K6-2-u4-X01']::text[],false,'{"seq":7,"concept":"K6-2-u4-C13","difficulty":1,"kind":"mc","stem":"『국어』 205쪽에서 말한 ‘방언’의 뜻은 무엇인가요?","options":[{"t":"특정 지역에서 주로 사용하며 표준어가 아닌 말","correct":true},{"t":"우리나라 사람들이 공통으로 사용하도록 정한 말","mis":"K6-2-u4-X19"},{"t":"잘못 쓴 틀린 말","mis":"K6-2-u4-X19"},{"t":"외국에서 들어온 말","mis":"K6-2-u4-X01"}],"explanation":["방언은 특정 지역에서 주로 사용하는 말이에요.","표준어는 우리나라 사람들이 공통으로 사용하도록 정한 말이에요.","방언도 지역의 개성이 담긴 소중한 우리말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_a#8','kor',6,2,'u4','','tb_g6_2_kor_u4_review_a','unit_review','K6-2-u4-C25',1,'mc','auto','『국어』 217쪽 기초 다지기의 ‘강수량’의 뜻은 무엇인가요?',ARRAY['K6-2-u4-X35']::text[],false,'{"seq":8,"concept":"K6-2-u4-C25","difficulty":1,"kind":"mc","stem":"『국어』 217쪽 기초 다지기의 ‘강수량’의 뜻은 무엇인가요?","options":[{"t":"비, 눈, 우박, 안개 따위로 일정 기간 일정한 곳에 내린 물의 양","correct":true},{"t":"기온, 비, 눈, 바람 따위의 대기 상태","mis":"K6-2-u4-X35"},{"t":"문화나 사상 따위가 서로 통함","mis":"K6-2-u4-X35"},{"t":"물질이 공기 중의 산소와 빠르게 반응해 열과 빛을 내며 타는 현상","mis":"K6-2-u4-X35"}],"explanation":["강수량은 일정한 곳에 내린 물의 양이에요.","“옛날 사람들은 측우기로 강수량을 알 수 있었다.”처럼 써요.","대기 상태는 기후예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_a#9','kor',6,2,'u4','','tb_g6_2_kor_u4_review_a','unit_review','K6-2-u4-C19',2,'mc','auto','「세린이의 즐거운 하루」에 나오는 ‘시나브로’의 뜻은 무엇인가요?',ARRAY['K6-2-u4-X18']::text[],false,'{"seq":9,"concept":"K6-2-u4-C19","difficulty":2,"kind":"mc","stem":"「세린이의 즐거운 하루」에 나오는 ‘시나브로’의 뜻은 무엇인가요?","options":[{"t":"모르는 사이에 조금씩 조금씩","correct":true},{"t":"아주 빠르게 한꺼번에","mis":"K6-2-u4-X18"},{"t":"시간이 남아 심심하게","mis":"K6-2-u4-X18"},{"t":"처음부터 끝까지 꼼꼼하게","mis":"K6-2-u4-X18"}],"explanation":["“시나브로 미술 활동을 마칠 시간이 되었고”를 읽어요.","즐겁게 활동하다 보니 모르는 사이에 시간이 흘렀어요.","시나브로는 모르는 사이에 조금씩 조금씩이라는 뜻이에요."],"asset":{"type":"passage","lines":["(간추림) 미술은 세린이가 가장 좋아하는 과목이다.","시나브로 미술 활동을 마칠 시간이 되었고","세린이는 뒤쓰레질을 얼른 하고 다른 친구들과 모둠 근처를 청소했습니다.","(간추림) 점심 급식에 나온 피자를 생각하니 군침을 흘릴 뻔했다.","(간추림) 점심을 먹고 운동장에서 친구들과 함께 줄넘기 연습을 했다.","[낱말] 뒤쓰레질 — 어떤 일을 마친 뒤에 그 자리의 쓰레기를 쓸어 내는 일."],"numbered":false,"title":"「세린이의 즐거운 하루」 앞부분 — 『국어』 182쪽","hi":["시나브로","뒤쓰레질"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_a#10','kor',6,2,'u4','','tb_g6_2_kor_u4_review_a','unit_review','K6-2-u4-C20',2,'mc','auto','「고유어의 가치」에서 오래전부터 있던 고유어로 든 것은 무엇인가요?',ARRAY['K6-2-u4-X37','K6-2-u4-X01']::text[],false,'{"seq":10,"concept":"K6-2-u4-C20","difficulty":2,"kind":"mc","stem":"「고유어의 가치」에서 오래전부터 있던 고유어로 든 것은 무엇인가요?","options":[{"t":"어버이, 하늘, 아름답다","correct":true},{"t":"떡볶이, 낚싯대, 할미꽃","mis":"K6-2-u4-X37"},{"t":"미술, 수업, 친구","mis":"K6-2-u4-X01"},{"t":"리플, 계주, 서클","mis":"K6-2-u4-X01"}],"explanation":["‘어버이’, ‘하늘’, ‘아름답다’는 오래전부터 있던 낱말이에요.","‘떡볶이’, ‘낚싯대’, ‘할미꽃’은 고유어를 바탕으로 만들어진 낱말이에요.","둘 다 고유어예요."],"asset":{"type":"passage","lines":["우리가 사용하는 낱말을 분류하면 크게 고유어, 한자어, 외래어로 가를 수 있다.","(간추림) ‘어버이’, ‘하늘’, ‘아름답다’는 오래전부터 있던 낱말이다.","(간추림) ‘떡볶이’, ‘낚싯대’, ‘할미꽃’은 고유어를 바탕으로 만들어진 낱말이다.","(간추림) 국어사전에서 ‘하늘’을 찾으면 한글 표기만 볼 수 있다.","이렇게 한글 표기만 있는 낱말이 바로 고유어이다."],"title":"「고유어의 가치」 앞부분 — 『국어』 184쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_a#11','kor',6,2,'u4','','tb_g6_2_kor_u4_review_a','unit_review','K6-2-u4-C8',2,'mc','auto','『국어』 189쪽 (4) 표에서 ‘비빔밥’의 고유어 칸에 쓴 것은 무엇인가요?',ARRAY['K6-2-u4-X10']::text[],false,'{"seq":11,"concept":"K6-2-u4-C8","difficulty":2,"kind":"mc","stem":"『국어』 189쪽 (4) 표에서 ‘비빔밥’의 고유어 칸에 쓴 것은 무엇인가요?","options":[{"t":"비빔, 밥","correct":true},{"t":"비빔밥은 한자어라서 칸을 비움","mis":"K6-2-u4-X10"},{"t":"밥","mis":"K6-2-u4-X10"},{"t":"비빔","mis":"K6-2-u4-X10"}],"explanation":["여러 낱말로 이루어진 사례는 낱말을 나누어요.","‘비빔밥’은 ‘비빔’과 ‘밥’으로 이루어졌어요.","두 낱말 모두 고유어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_a#12','kor',6,2,'u4','','tb_g6_2_kor_u4_review_a','unit_review','K6-2-u4-C10',2,'mc','auto','발표 자료를 점검했더니 자료의 양이 발표 시간에 비해 너무 많았어요. 어떻게 해야 하나요?',ARRAY['K6-2-u4-X13','K6-2-u4-X12']::text[],false,'{"seq":12,"concept":"K6-2-u4-C10","difficulty":2,"kind":"mc","stem":"발표 자료를 점검했더니 자료의 양이 발표 시간에 비해 너무 많았어요. 어떻게 해야 하나요?","options":[{"t":"발표 여건을 생각하며 발표 자료의 양을 줄이거나 추가한다","correct":true},{"t":"자료가 많을수록 좋으니 그대로 두고 빨리 말한다","mis":"K6-2-u4-X13"},{"t":"자료의 출처를 지워 화면을 깔끔하게 만든다","mis":"K6-2-u4-X12"},{"t":"매체를 하나 더 늘려 자료를 모두 보여 준다","mis":"K6-2-u4-X13"}],"explanation":["『국어』 191쪽 (3)의 둘째 점검 질문이에요.","발표 여건을 생각하며 양을 줄이거나 더해요.","많은 자료가 꼭 좋은 자료는 아니에요."],"asset":{"type":"passage","lines":["① 조사한 자료의 출처는 믿을 만한가요?","→ 아니요: 출처를 점검하고 믿을 만한 자료로 바꿔요.","② 발표 자료의 양은 적절한가요?","→ 아니요: 발표 여건을 생각하며 발표 자료의 양을 줄이거나 추가해요.","③ 정한 매체는 발표에 효과적인가요?","→ 아니요: (                    )","모두 ‘예’ → 완성한 발표 자료를 다시 한번 살펴보고 발표를 준비해요."],"numbered":false,"title":"발표 자료 점검하기 — 『국어』 191쪽 (3)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_a#13','kor',6,2,'u4','','tb_g6_2_kor_u4_review_a','unit_review','K6-2-u4-C22',2,'mc','auto','「큰사전이 필요하다」에서 주시경은 한글 연구에 필요한 책이라면 천금을 마다하고 샀어요. ‘천금’의 뜻은 무엇인가요?',ARRAY['K6-2-u4-X31']::text[],false,'{"seq":13,"concept":"K6-2-u4-C22","difficulty":2,"kind":"mc","stem":"「큰사전이 필요하다」에서 주시경은 한글 연구에 필요한 책이라면 천금을 마다하고 샀어요. ‘천금’의 뜻은 무엇인가요?","options":[{"t":"많은 돈이나 아주 귀중한 것을 비유적으로 이르는 말","correct":true},{"t":"천 개의 금덩이를 실제로 하나하나 세는 말","mis":"K6-2-u4-X31"},{"t":"아주 적은 돈이나 하찮은 물건을 이르는 말","mis":"K6-2-u4-X31"},{"t":"하늘에서 내린 금처럼 갑자기 생긴 돈","mis":"K6-2-u4-X31"}],"explanation":["천금은 많은 돈이나 아주 귀중한 것을 비유적으로 이르는 말이에요.","가난했지만 아무리 비싸도 책을 샀다는 뜻이에요.","한글을 얼마나 아꼈는지 알 수 있어요."],"asset":{"type":"passage","lines":["“저기 보퉁이 선생님 오신다.”","(간추림) 학생들은 늘 조선어책을 들고 다니는 그를 ‘보퉁이 선생님’이라 불렀다.","(간추림) 그가 근대 한국어 연구의 아버지, 주시경이다.","(간추림) 집안은 가난했지만 한글 연구에 필요한 책은 천금을 마다하고 샀다.","[낱말] 보퉁이 — 물건을 보자기에 싸서 꾸려 놓은 것."],"numbered":false,"title":"「큰사전이 필요하다」 보퉁이 선생님 — 『국어』 195쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_a#14','kor',6,2,'u4','','tb_g6_2_kor_u4_review_a','unit_review','K6-2-u4-C21',2,'mc','auto','「큰사전이 필요하다」의 다음 일 가운데 가장 먼저 일어난 일은 무엇인가요?',ARRAY['K6-2-u4-X30']::text[],false,'{"seq":14,"concept":"K6-2-u4-C21","difficulty":2,"kind":"mc","stem":"「큰사전이 필요하다」의 다음 일 가운데 가장 먼저 일어난 일은 무엇인가요?","options":[{"t":"주시경이 국어연구학회를 만들어 사전을 만들기 시작했다","correct":true},{"t":"주시경의 제자들이 조선어연구회를 세웠다","mis":"K6-2-u4-X30"},{"t":"일본 경찰이 조선어학회의 사전 원고를 압수했다","mis":"K6-2-u4-X30"},{"t":"역장이 서울역 창고에서 『큰사전』 원고를 찾았다","mis":"K6-2-u4-X30"}],"explanation":["1908년 주시경이 국어연구학회를 만들었어요.","1921년 조선어연구회, 1942년 원고 압수, 1945년 원고를 찾음 차례예요.","『국어』 202쪽 4번 (4)처럼 차례대로 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_a#15','kor',6,2,'u4','','tb_g6_2_kor_u4_review_a','unit_review','K6-2-u4-C14',2,'mc','auto','『국어』 207쪽 (4)의 “알아들을 수 없는 신조어 사용을 줄이고 바르고 고운 말을 쓰면 좋겠어.”는 무엇을 이야기한 것인가요?',ARRAY['K6-2-u4-X21','K6-2-u4-X03']::text[],false,'{"seq":15,"concept":"K6-2-u4-C14","difficulty":2,"kind":"mc","stem":"『국어』 207쪽 (4)의 “알아들을 수 없는 신조어 사용을 줄이고 바르고 고운 말을 쓰면 좋겠어.”는 무엇을 이야기한 것인가요?","options":[{"t":"언어생활 실태를 보고 앞으로의 언어생활을 다짐한 것","correct":true},{"t":"친구의 잘못을 선생님께 알린 것","mis":"K6-2-u4-X21"},{"t":"신조어를 더 만들자고 한 것","mis":"K6-2-u4-X03"},{"t":"점검이 필요 없다고 한 것","mis":"K6-2-u4-X21"}],"explanation":["(4)에서는 실태 정리 결과를 보고 앞으로의 언어생활을 이야기해요.","신조어를 줄이고 바르고 고운 말을 쓰겠다는 다짐이에요.","느낀 점과 다짐을 함께 나누어요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"“줄임말을 무분별하게 사용하지 않아야 해.”"},{"who":"친구 2","text":"“무분별하게 사용하는 외래어를 고유어로 바꿀 수 있는지 생각해 보면 좋겠어.”"},{"who":"친구 3","text":"“바른 우리말을 사용해야 해.”"},{"who":"친구 4","text":"“알아들을 수 없는 신조어 사용을 줄이고 바르고 고운 말을 쓰면 좋겠어.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_a#16','kor',6,2,'u4','','tb_g6_2_kor_u4_review_a','unit_review','K6-2-u4-C15',2,'mc','auto','다짐문 예시에서 ‘전하고 싶은 말’에 해당하는 문장은 무엇인가요?',ARRAY['K6-2-u4-X22']::text[],false,'{"seq":16,"concept":"K6-2-u4-C15","difficulty":2,"kind":"mc","stem":"다짐문 예시에서 ‘전하고 싶은 말’에 해당하는 문장은 무엇인가요?","options":[{"t":"“소중한 우리말을 바르게 사용하려고 열심히 노력할 것을 약속합니다.”","correct":true},{"t":"“우리말 지킴이 실천 다짐문”","mis":"K6-2-u4-X22"},{"t":"“하나, 나는 비속어나 욕설을 사용하지 않고 …”","mis":"K6-2-u4-X22"},{"t":"“20○○년 ○○월 ○○일 · ○○○”","mis":"K6-2-u4-X22"}],"explanation":["전하고 싶은 말은 실천 약속 뒤에 와요.","다짐을 꼭 지키겠다는 마음을 담아요.","맨 끝에는 날짜와 쓴 사람을 써요."],"asset":{"type":"passage","lines":["우리말 지킴이 실천 다짐문","나는 아름답고 소중한 우리말을 지키고 바르게 사용하고자 다음과 같이 다짐합니다.","하나, 나는 일상생활에서 불필요한 외래어 사용을 줄이고, 고유어를 적극적으로 찾아 사용하겠습니다.","하나, 나는 뜻을 알기 어려운 말이나 지나친 줄임말보다는 표준어를 사용하려고 노력하겠습니다.","하나, 나는 비속어나 욕설을 사용하지 않고, 긍정적이고 예쁜 말을 사용해 상대를 존중하겠습니다.","소중한 우리말을 바르게 사용하려고 열심히 노력할 것을 약속합니다.","20○○년 ○○월 ○○일 · ○○○"],"numbered":false,"title":"실천 다짐문 예시 — 『국어』 209쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_a#17','kor',6,2,'u4','','tb_g6_2_kor_u4_review_a','unit_review','K6-2-u4-C12',3,'mc','auto','『국어』 203쪽 5번 ①이에요. 추론한 내용으로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u4-X16','K6-2-u4-X17']::text[],false,'{"seq":17,"concept":"K6-2-u4-C12","difficulty":3,"kind":"mc","stem":"『국어』 203쪽 5번 ①이에요. 추론한 내용으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"‘언문’에서 ‘한글’로 이름이 바뀌면서 한글에 자부심을 가지게 되었을 것이다","correct":true},{"t":"한글을 쓰는 사람이 아무도 없게 되었을 것이다","mis":"K6-2-u4-X16"},{"t":"이름만 바뀌었고 아무것도 달라지지 않았다고 글에 적혀 있다","mis":"K6-2-u4-X17"},{"t":"한글이 한자로 바뀌었을 것이다","mis":"K6-2-u4-X16"}],"explanation":["주시경은 ‘한’에 크고 바르다, 첫째가는, 우리 겨레의 뜻을 담았어요.","이 단서로 사람들이 한글을 자랑스럽게 여겼을 것이라고 추론해요.","추론은 글에 적히지 않은 내용을 단서로 짐작하는 것이에요."],"asset":{"type":"passage","lines":["[글 내용] 한글은 ‘언문’으로 불리다 고종의 명령으로 ‘국문’으로 바뀌었다.","[글 내용] 주시경은 ‘한글’이라는 이름을 지었다.","[질문] ‘한글’이라는 이름이 생기면서 어떤 변화가 있었을까요?","[추론한 내용] (                    )"],"numbered":false,"title":"『국어』 203쪽 5번 — 글 내용 추론하기 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_a#18','kor',6,2,'u4','','tb_g6_2_kor_u4_review_a','unit_review','K6-2-u4-C6',3,'mc','auto','학교에서 볼 수 있는 한자어나 외래어를 고유어로 고쳐 쓸 때 가장 중요하게 생각할 점은 무엇인가요?',ARRAY['K6-2-u4-X08','K6-2-u4-X03']::text[],false,'{"seq":18,"concept":"K6-2-u4-C6","difficulty":3,"kind":"mc","stem":"학교에서 볼 수 있는 한자어나 외래어를 고유어로 고쳐 쓸 때 가장 중요하게 생각할 점은 무엇인가요?","options":[{"t":"낱말의 뜻을 확인하고 고유어를 알맞게 활용하는 것","correct":true},{"t":"모든 한자어와 외래어를 빠짐없이 바꾸는 것","mis":"K6-2-u4-X08"},{"t":"글자 수를 될 수 있는 대로 줄이는 것","mis":"K6-2-u4-X08"},{"t":"어려운 고유어를 많이 쓰는 것","mis":"K6-2-u4-X03"}],"explanation":["단순히 바꾸는 것보다 뜻을 확인하는 것이 먼저예요.","뜻에 맞는 고유어를 골라 알맞게 써야 해요.","바꿀 말이 마땅치 않은 낱말은 그대로 써도 돼요."],"asset":{"type":"passage","lines":["1. 학교에서 볼 수 있는 낱말을 고유어, 한자어, 외래어로 분류해 봅시다.","2. 분류한 한자어나 외래어 가운데에서 고유어로 고칠 수 있는 낱말을 고쳐 써 봅시다.","[표] 한자어나 외래어 · 낱말의 뜻 · 고유어","3. 학교에서 볼 수 있는 고유어 가운데 하나를 넣어 문장을 만들어 봅시다."],"numbered":false,"title":"학교에서 볼 수 있는 낱말을 분류하고 고유어로 고쳐 쓰기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_a#19','kor',6,2,'u4','','tb_g6_2_kor_u4_review_a','unit_review','K6-2-u4-C26',3,'mc','auto','주시경 선생님이 쓴 편지에서 ‘한힌샘’의 ‘힌샘’이 뜻하는 것은 무엇인가요?',ARRAY['K6-2-u4-X38']::text[],false,'{"seq":19,"concept":"K6-2-u4-C26","difficulty":3,"kind":"mc","stem":"주시경 선생님이 쓴 편지에서 ‘한힌샘’의 ‘힌샘’이 뜻하는 것은 무엇인가요?","options":[{"t":"맑고 깨끗한 샘물처럼 지혜롭고 밝은 생각이 흘러나오는 곳","correct":true},{"t":"하얀 눈이 쌓인 높은 산처럼 맑은 곳","mis":"K6-2-u4-X38"},{"t":"하나뿐인 크고 위대한 나라, 우리나라","mis":"K6-2-u4-X38"},{"t":"한자로 지어서 뜻을 알기 어려운 이름","mis":"K6-2-u4-X38"}],"explanation":["편지에서 ‘한’과 ‘힌샘’의 뜻을 풀어 주었어요.","‘힌샘’은 지혜롭고 밝은 생각이 흘러나오는 곳이에요.","‘한’은 하나뿐인 크고 위대한 나라예요."],"asset":{"type":"passage","lines":["저는 주시경이라고 해요. 예전에는 ‘한힌샘’이라는 이름으로도 불렸어요.","(간추림) ‘한’은 하나뿐인 크고 위대한 나라, ‘힌샘’은 맑고 깨끗한 샘물처럼","(간추림) 지혜롭고 밝은 생각이 흘러나오는 곳을 뜻한다.","(간추림) 나라를 빼앗겼을 때 우리말 사전을 만들고 한글을 가르치는 데 온 마음을 다했다.","한글은 우리 겨레의 숨결이 담긴 소중한 보물이에요.","보물은 소중히 아끼고 가꿀수록 더욱 빛이 날 거예요.","[날짜와 쓴 사람] ○○○○년 10월 9일 · 우리말을 사랑하는 주시경 선생님이"],"numbered":false,"title":"주시경 선생님이 쓴 편지 — 글을 읽고 추론하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_a#20','kor',6,2,'u4','','tb_g6_2_kor_u4_review_a','unit_review','K6-2-u4-C24',3,'mc','auto','「야, 겨울 온다」에서 겨울이 다가온다는 것을 알 수 있는 모습으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u4-X34']::text[],false,'{"seq":20,"concept":"K6-2-u4-C24","difficulty":3,"kind":"mc","stem":"「야, 겨울 온다」에서 겨울이 다가온다는 것을 알 수 있는 모습으로 알맞은 것은 무엇인가요?","options":[{"t":"제비가 떠나가고 기러기가 돌아온 모습","correct":true},{"t":"제비가 돌아오고 꽃이 피기 시작한 모습","mis":"K6-2-u4-X34"},{"t":"미꾸리들이 도랑 위로 올라와 노는 모습","mis":"K6-2-u4-X34"},{"t":"나무들이 옷을 벗고 더위를 식히는 모습","mis":"K6-2-u4-X34"}],"explanation":["시의 첫 줄을 다시 읽어요.","제비가 떠나가고 기러기가 돌아왔다고 했어요.","오소리와 너구리가 긴 잠에 드는 것도 겨울이 다가오는 모습이에요."],"asset":{"type":"passage","lines":["제비 떠나가고 기러기 돌아왔다.","쑥부쟁인 아직도 방그레 웃어 걱정이다.","길섶 나무들아 따스운 옷을 입어라.","(간추림) 오소리랑 너구리는 긴 잠에 들고, 미꾸리들에게는 도랑 깊이 숨으라고 한다.","걸음마다 바삭바삭","(간추림) 마지막에 겨울이 온다고 반갑게 외친다."],"title":"「야, 겨울 온다」(강순예 글) — 『국어』 214쪽","hi":["방그레","길섶","바삭바삭"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_a#21','kor',6,2,'u4','','tb_g6_2_kor_u4_review_a','unit_review','K6-2-u4-C16',3,'mc','auto','홍보물을 만들 계획을 세울 때 방법, 배치, 준비물 같은 형식 말고도 미리 생각을 나누어야 할 것은 무엇인가요?',ARRAY['K6-2-u4-X13','K6-2-u4-X12','K6-2-u4-X25']::text[],false,'{"seq":21,"concept":"K6-2-u4-C16","difficulty":3,"kind":"mc","stem":"홍보물을 만들 계획을 세울 때 방법, 배치, 준비물 같은 형식 말고도 미리 생각을 나누어야 할 것은 무엇인가요?","options":[{"t":"홍보물에 들어갈 내용과 강조할 부분","correct":true},{"t":"화려한 색깔만","mis":"K6-2-u4-X13"},{"t":"다른 반 홍보물을 그대로 베낄 방법","mis":"K6-2-u4-X12"},{"t":"외국어로 된 제목","mis":"K6-2-u4-X25"}],"explanation":["형식뿐 아니라 내용과 강조할 부분을 함께 정해요.","홍보 목적이 잘 드러나게 만들어요.","꾸밈은 내용을 정한 다음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_a#22','kor',6,2,'u4','','tb_g6_2_kor_u4_review_a','unit_review','K6-2-u4-C15',3,'mc','auto','친구의 실천 다짐문을 읽고 고칠 점을 알맞게 말한 것은 무엇인가요?',ARRAY['K6-2-u4-X24','K6-2-u4-X23']::text[],false,'{"seq":22,"concept":"K6-2-u4-C15","difficulty":3,"kind":"mc","stem":"친구의 실천 다짐문을 읽고 고칠 점을 알맞게 말한 것은 무엇인가요?","options":[{"t":"“다짐이 구체적으로 드러나도록 내용을 쓰면 좋겠어.”","correct":true},{"t":"“글씨가 삐뚤어서 다시 써.”","mis":"K6-2-u4-X24"},{"t":"“다짐문이 별로야.”","mis":"K6-2-u4-X24"},{"t":"“다들 바르게 쓰면 되니까 그대로 둬.”","mis":"K6-2-u4-X23"}],"explanation":["고칠 점은 다짐의 내용에서 찾아요.","어떻게 바꾸면 좋을지 함께 말해 주어요.","겉모습이나 막연한 말은 도움이 되지 않아요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"“다짐이 구체적으로 드러나도록 내용을 쓰면 좋겠어.”"},{"who":"친구 2","text":"“실천 의지가 드러나도록 쓰는 것이 좋겠어.”"},{"who":"친구 3","text":"“고유어를 활용하면 좋을 것 같아.”"},{"who":"친구 4","text":"“실천 가능한 내용이면 좋을 것 같아.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_a#23','kor',6,2,'u4','','tb_g6_2_kor_u4_review_a','unit_review','K6-2-u4-C1',4,'essay','teacher','교실이나 학교에서 볼 수 있는 낱말을 고유어, 한자어, 외래어로 하나 이상씩 분류하고, 어떻게 분류했는지 방법을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K6-2-u4-C1","difficulty":4,"kind":"essay","stem":"교실이나 학교에서 볼 수 있는 낱말을 고유어, 한자어, 외래어로 하나 이상씩 분류하고, 어떻게 분류했는지 방법을 쓰세요.","answer_guide":{"answer":"예: 고유어 — 미닫이, 걸레 / 한자어 — 칠판, 학급 / 외래어 — 컴퓨터, 텔레비전. 국어사전에서 찾아 한글 표기만 있으면 고유어, 한자가 함께 있으면 한자어, 영어 같은 외국어가 함께 있으면 외래어로 분류했다.","scoring_points":["세 갈래에 맞게 낱말을 분류했는가","국어사전 등 분류한 방법을 썼는가","각 갈래의 뜻을 알고 있는가"]},"explanation":["학교 곳곳의 안내문, 물건 이름을 살펴요.","헷갈리는 낱말은 국어사전에서 확인해요.","학교 낱말을 세 갈래로 나누는 첫째 활동이에요."],"asset":{"type":"passage","lines":["1. 학교에서 볼 수 있는 낱말을 고유어, 한자어, 외래어로 분류해 봅시다.","2. 분류한 한자어나 외래어 가운데에서 고유어로 고칠 수 있는 낱말을 고쳐 써 봅시다.","[표] 한자어나 외래어 · 낱말의 뜻 · 고유어","3. 학교에서 볼 수 있는 고유어 가운데 하나를 넣어 문장을 만들어 봅시다."],"numbered":false,"title":"학교에서 볼 수 있는 낱말을 분류하고 고유어로 고쳐 쓰기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_a#24','kor',6,2,'u4','','tb_g6_2_kor_u4_review_a','unit_review','K6-2-u4-C26',4,'essay','teacher','주시경 선생님이 쓴 편지를 읽고 추론한 내용을 하나 쓰고, 그렇게 추론한 근거(편지의 단서나 자신의 경험·지식)를 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u4-C26","difficulty":4,"kind":"essay","stem":"주시경 선생님이 쓴 편지를 읽고 추론한 내용을 하나 쓰고, 그렇게 추론한 근거(편지의 단서나 자신의 경험·지식)를 쓰세요.","answer_guide":{"answer":"예: 주시경 선생님은 나라를 빼앗긴 때에 우리말을 지키려고 매우 힘들게 노력했을 것이다. 편지에서 일본이 우리말과 글을 쓰지 못하게 했을 때 가슴이 너무 아팠다고 했고, 「큰사전이 필요하다」에서 원고를 빼앗긴 일을 읽었기 때문이다.","scoring_points":["편지에 적히지 않은 내용을 추론했는가","편지의 단서나 경험·지식을 근거로 들었는가","추론과 근거가 서로 이어지는가"]},"explanation":["글에서 찾을 수 있는 단서를 먼저 찾아요.","내가 아는 것이나 배운 것을 함께 떠올려요.","추론한 내용과 근거를 함께 써요."],"asset":{"type":"passage","lines":["저는 주시경이라고 해요. 예전에는 ‘한힌샘’이라는 이름으로도 불렸어요.","(간추림) ‘한’은 하나뿐인 크고 위대한 나라, ‘힌샘’은 맑고 깨끗한 샘물처럼","(간추림) 지혜롭고 밝은 생각이 흘러나오는 곳을 뜻한다.","(간추림) 나라를 빼앗겼을 때 우리말 사전을 만들고 한글을 가르치는 데 온 마음을 다했다.","한글은 우리 겨레의 숨결이 담긴 소중한 보물이에요.","보물은 소중히 아끼고 가꿀수록 더욱 빛이 날 거예요.","[날짜와 쓴 사람] ○○○○년 10월 9일 · 우리말을 사랑하는 주시경 선생님이"],"numbered":false,"title":"주시경 선생님이 쓴 편지 — 글을 읽고 추론하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_a#25','kor',6,2,'u4','','tb_g6_2_kor_u4_review_a','unit_review','K6-2-u4-C11',4,'essay','teacher','이 단원에서 알게 된 우리말을 지키기 위한 노력(사전 편찬 · 시골말 캐기)을 정리하고, 오늘날 내가 할 수 있는 일을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u4-C11","difficulty":4,"kind":"essay","stem":"이 단원에서 알게 된 우리말을 지키기 위한 노력(사전 편찬 · 시골말 캐기)을 정리하고, 오늘날 내가 할 수 있는 일을 쓰세요.","answer_guide":{"answer":"예: 주시경과 조선어학회는 일본의 탄압 속에서도 『큰사전』을 만들었고, 학생들은 시골말 캐기로 전국의 방언을 모았다. 나는 고유어로 바꿀 수 있는 말은 바꾸어 쓰고, 지역 방언도 소중한 우리말로 존중하겠다.","scoring_points":["사전 편찬과 시골말 캐기를 바르게 정리했는가","오늘날 내가 할 수 있는 일을 썼는가","실천할 수 있게 구체적으로 썼는가"]},"explanation":["「큰사전이 필요하다」와 「시골말 캐기」의 내용을 떠올려요.","그분들의 노력을 오늘의 생활과 이어 생각해요.","내가 할 일을 구체적으로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_b#1','kor',6,2,'u4','','tb_g6_2_kor_u4_review_b','unit_review','K6-2-u4-C1',1,'mc','auto','이 단원에서 배운 ‘한자어’의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u4-X01','K6-2-u4-X05']::text[],false,'{"seq":1,"concept":"K6-2-u4-C1","difficulty":1,"kind":"mc","stem":"이 단원에서 배운 ‘한자어’의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"한자로 이루어진 낱말","correct":true},{"t":"우리말에 처음부터 있던 낱말","mis":"K6-2-u4-X01"},{"t":"외국에서 들어와 우리 생활에서 널리 쓰이는 낱말","mis":"K6-2-u4-X01"},{"t":"뜻이 어려운 모든 낱말","mis":"K6-2-u4-X05"}],"explanation":["한자어는 한자로 이루어진 낱말이에요.","국어사전에서 찾으면 낱말 뒤에 한자가 같이 있어요.","‘수업’, ‘친구’, ‘미술’이 한자어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_b#2','kor',6,2,'u4','','tb_g6_2_kor_u4_review_b','unit_review','K6-2-u4-C16',1,'mc','auto','『국어』 216쪽 ‘스스로 확인하기’에서 확인하는 질문이 아닌 것은 무엇인가요?',ARRAY['K6-2-u4-X03']::text[],false,'{"seq":2,"concept":"K6-2-u4-C16","difficulty":1,"kind":"mc","stem":"『국어』 216쪽 ‘스스로 확인하기’에서 확인하는 질문이 아닌 것은 무엇인가요?","options":[{"t":"외국어를 많이 알고 있나요?","correct":true},{"t":"고유어를 알고 있나요?","mis":"K6-2-u4-X03"},{"t":"우리말을 바르게 사용할 수 있나요?","mis":"K6-2-u4-X03"}],"explanation":["스스로 확인하기는 이 단원에서 배운 것을 되돌아봐요.","고유어, 고유어 활용 사례 발표, 우리말 바르게 사용하기를 확인해요.","외국어를 많이 아는지는 확인하지 않아요."],"asset":{"type":"passage","lines":["고유어를 알고 있나요?","고유어를 활용한 사례를 조사하여 발표할 수 있나요?","우리말을 바르게 사용할 수 있나요?","[표시] 매우 잘함 · 잘함 · 보통임"],"numbered":false,"title":"스스로 확인하기 — 『국어』 216쪽 (2)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_b#3','kor',6,2,'u4','','tb_g6_2_kor_u4_review_b','unit_review','K6-2-u4-C18',1,'ox','auto','「조각하늘」에서 조각하늘은 구름 뒤에서 좀처럼 나오지 않아요.',ARRAY['K6-2-u4-X29']::text[],false,'{"seq":3,"concept":"K6-2-u4-C18","difficulty":1,"kind":"ox","stem":"「조각하늘」에서 조각하늘은 구름 뒤에서 좀처럼 나오지 않아요.","answer":"O","reason_options":[{"t":"하늘이 구름 뒤에 숨어서 나올 생각을 안 한다고 했어요.","correct":true},{"t":"조각하늘은 구름을 밀어내고 환하게 나타나요.","mis":"K6-2-u4-X29"}],"mis":"K6-2-u4-X29","explanation":["시의 첫째 연을 다시 읽어요.","하늘은 구름 뒤에 숨어 빠끔히 내다보기만 해요.","그래서 조각처럼 조금씩만 보여요."],"asset":{"type":"passage","lines":["하늘이 숨바꼭질하고 싶은가 봐요.","구름 뒤에 숨어서 나올 생각을 안 해요.","호수에 비친 자기 얼굴만","빠끔히 내다보고","구름 뒤로 쏘옥 숨어요.","(간추림) 바람이 호수를 간지럽혀도 조각하늘은 구름 뒤에서 좀처럼 나오지 않는다."],"title":"「조각하늘」(권지영 글) — 『국어』 180쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_b#4','kor',6,2,'u4','','tb_g6_2_kor_u4_review_b','unit_review','K6-2-u4-C6',1,'mc','auto','『국어』 186쪽에서 외래어 ‘서클’을 고유어를 살려 다듬은 말은 무엇인가요?',ARRAY['K6-2-u4-X08']::text[],false,'{"seq":4,"concept":"K6-2-u4-C6","difficulty":1,"kind":"mc","stem":"『국어』 186쪽에서 외래어 ‘서클’을 고유어를 살려 다듬은 말은 무엇인가요?","options":[{"t":"동아리","correct":true},{"t":"서클방","mis":"K6-2-u4-X08"},{"t":"둥근 원","mis":"K6-2-u4-X08"},{"t":"모임터","mis":"K6-2-u4-X08"}],"explanation":["서클은 함께 모여 어떤 활동을 하는 모임이에요.","그래서 ‘동아리’로 다듬었어요.","글자 그대로 옮긴 ‘둥근 원’은 뜻이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_b#5','kor',6,2,'u4','','tb_g6_2_kor_u4_review_b','unit_review','K6-2-u4-C7',1,'ox','auto','“날개 돋치다.”는 새에게 날개가 새로 난다는 뜻으로만 쓰여요.',ARRAY['K6-2-u4-X09']::text[],false,'{"seq":5,"concept":"K6-2-u4-C7","difficulty":1,"kind":"ox","stem":"“날개 돋치다.”는 새에게 날개가 새로 난다는 뜻으로만 쓰여요.","answer":"X","reason_options":[{"t":"“날개 돋치다.”에는 상품이 빠른 속도로 팔려 나간다는 새로운 뜻이 있어요.","correct":true},{"t":"관용 표현은 낱말 뜻을 하나씩 더해 글자 그대로 풀이해요.","mis":"K6-2-u4-X09"}],"mis":"K6-2-u4-X09","explanation":["관용 표현은 낱말이 어울려 새로운 뜻을 만들어요.","“날개 돋친 듯이 팔려 나가서”는 물건이 빨리 팔렸다는 말이에요.","글자 그대로 풀이하면 뜻을 알 수 없어요."],"asset":{"type":"speech","turns":[{"who":"㉮ 친구 1","text":"“치과 치료를 받을 때 놀라지 않았어?”"},{"who":"㉮ 친구 2","text":"“응, 눈도 깜짝 안 했어.”"},{"who":"㉯ 친구 1","text":"“학교 알뜰 장터에서 무엇을 샀어?”"},{"who":"㉯ 친구 2","text":"“예쁜 물건은 날개 돋친 듯이 팔려 나가서 이걸 겨우 샀어.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_b#6','kor',6,2,'u4','','tb_g6_2_kor_u4_review_b','unit_review','K6-2-u4-C21',1,'mc','auto','「큰사전이 필요하다」에서 1945년 9월 8일에 『큰사전』 원고를 찾은 곳은 어디인가요?',ARRAY['K6-2-u4-X30']::text[],false,'{"seq":6,"concept":"K6-2-u4-C21","difficulty":1,"kind":"mc","stem":"「큰사전이 필요하다」에서 1945년 9월 8일에 『큰사전』 원고를 찾은 곳은 어디인가요?","options":[{"t":"서울역 창고","correct":true},{"t":"함흥의 학교","mis":"K6-2-u4-X30"},{"t":"상하이","mis":"K6-2-u4-X30"},{"t":"조선어학회 사무실","mis":"K6-2-u4-X30"}],"explanation":["창고 정리를 하던 역장이 커다란 상자를 열었어요.","그 안에서 원고 수만 장이 나왔어요.","광복 뒤 회원들이 애타게 찾던 원고였어요."],"asset":{"type":"passage","lines":["(간추림) 1945년 9월 8일 서울역 창고에서 역장이 커다란 상자를 열었다.","(간추림) 그 안에서 잃어버렸던 『큰사전』 원고 수만 장이 모습을 드러냈다.","(간추림) 1947년 『조선말 큰사전』 1권이 나왔고, 1957년 6권으로 완간되었다.","(간추림) 조선어학회의 값진 노력으로 우리나라는 우리글 사전을 가지게 되었다."],"title":"「큰사전이 필요하다」 다시 찾은 원고 — 『국어』 200쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_b#7','kor',6,2,'u4','','tb_g6_2_kor_u4_review_b','unit_review','K6-2-u4-C13',1,'mc','auto','『국어』 205쪽 6번 (2) 예시 답안에서 표준어 ‘옥수수’의 방언으로 든 말은 무엇인가요?',ARRAY['K6-2-u4-X33']::text[],false,'{"seq":7,"concept":"K6-2-u4-C13","difficulty":1,"kind":"mc","stem":"『국어』 205쪽 6번 (2) 예시 답안에서 표준어 ‘옥수수’의 방언으로 든 말은 무엇인가요?","options":[{"t":"깡냉이, 강내이, 옥시기","correct":true},{"t":"개고리, 깨고리, 깨고락지","mis":"K6-2-u4-X33"},{"t":"세우리, 정구지","mis":"K6-2-u4-X33"},{"t":"가새, 가시개, 까깨","mis":"K6-2-u4-X33"}],"explanation":["옥수수의 방언은 깡냉이, 강내이, 옥시기예요.","개고리, 깨고리, 깨고락지는 개구리의 방언이에요.","방언을 찾을 때 어느 지역의 말인지도 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_b#8','kor',6,2,'u4','','tb_g6_2_kor_u4_review_b','unit_review','K6-2-u4-C25',1,'mc','auto','“문화나 사상 따위가 서로 통함.”을 뜻하는 교과 낱말은 무엇인가요?',ARRAY['K6-2-u4-X35']::text[],false,'{"seq":8,"concept":"K6-2-u4-C25","difficulty":1,"kind":"mc","stem":"“문화나 사상 따위가 서로 통함.”을 뜻하는 교과 낱말은 무엇인가요?","options":[{"t":"교류","correct":true},{"t":"소화","mis":"K6-2-u4-X35"},{"t":"강수량","mis":"K6-2-u4-X35"},{"t":"기후","mis":"K6-2-u4-X35"}],"explanation":["교류는 문화나 사상 따위가 서로 통하는 것이에요.","“다른 나라들과 경제 교류가 활발하다.”처럼 써요.","사회 공부에서 자주 나오는 낱말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_b#9','kor',6,2,'u4','','tb_g6_2_kor_u4_review_b','unit_review','K6-2-u4-C19',2,'mc','auto','「세린이의 즐거운 하루」에서 세린이가 피자를 생각하며 흘릴 뻔한 ‘군침’의 뜻은 무엇인가요?',ARRAY['K6-2-u4-X18','K6-2-u4-X05']::text[],false,'{"seq":9,"concept":"K6-2-u4-C19","difficulty":2,"kind":"mc","stem":"「세린이의 즐거운 하루」에서 세린이가 피자를 생각하며 흘릴 뻔한 ‘군침’의 뜻은 무엇인가요?","options":[{"t":"음식이 먹고 싶어서 입안에 도는 침","correct":true},{"t":"잠잘 때 흘리는 침","mis":"K6-2-u4-X18"},{"t":"군대에서 쓰는 말","mis":"K6-2-u4-X05"},{"t":"음식을 먹은 뒤에 남은 맛","mis":"K6-2-u4-X18"}],"explanation":["세린이는 먹음직스러운 피자를 생각했어요.","음식이 먹고 싶어서 입안에 침이 돌았어요.","군침은 고유어예요."],"asset":{"type":"passage","lines":["(간추림) 미술은 세린이가 가장 좋아하는 과목이다.","시나브로 미술 활동을 마칠 시간이 되었고","세린이는 뒤쓰레질을 얼른 하고 다른 친구들과 모둠 근처를 청소했습니다.","(간추림) 점심 급식에 나온 피자를 생각하니 군침을 흘릴 뻔했다.","(간추림) 점심을 먹고 운동장에서 친구들과 함께 줄넘기 연습을 했다.","[낱말] 뒤쓰레질 — 어떤 일을 마친 뒤에 그 자리의 쓰레기를 쓸어 내는 일."],"numbered":false,"title":"「세린이의 즐거운 하루」 앞부분 — 『국어』 182쪽","hi":["시나브로","뒤쓰레질"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_b#10','kor',6,2,'u4','','tb_g6_2_kor_u4_review_b','unit_review','K6-2-u4-C20',2,'mc','auto','『국어』 185쪽 3번 (4) 예시 답안에서 ‘함박눈’의 뜻은 무엇인가요?',ARRAY['K6-2-u4-X37','K6-2-u4-X18']::text[],false,'{"seq":10,"concept":"K6-2-u4-C20","difficulty":2,"kind":"mc","stem":"『국어』 185쪽 3번 (4) 예시 답안에서 ‘함박눈’의 뜻은 무엇인가요?","options":[{"t":"굵고 탐스럽게 내리는 눈","correct":true},{"t":"가늘게 조금 내리는 눈","mis":"K6-2-u4-X37"},{"t":"함박꽃처럼 하얀 꽃","mis":"K6-2-u4-X18"},{"t":"녹아서 질척한 눈","mis":"K6-2-u4-X37"}],"explanation":["함박눈은 굵고 탐스럽게 내리는 눈이에요.","내리는 모양이 생동감 있게 떠올라요.","뜻을 쉽게 짐작할 수 있는 고유어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_b#11','kor',6,2,'u4','','tb_g6_2_kor_u4_review_b','unit_review','K6-2-u4-C8',2,'mc','auto','『국어』 189쪽 (4) 표에서 ‘두레길’의 유형은 무엇인가요?',ARRAY['K6-2-u4-X10']::text[],false,'{"seq":11,"concept":"K6-2-u4-C8","difficulty":2,"kind":"mc","stem":"『국어』 189쪽 (4) 표에서 ‘두레길’의 유형은 무엇인가요?","options":[{"t":"도로","correct":true},{"t":"음식","mis":"K6-2-u4-X10"},{"t":"동네 이름","mis":"K6-2-u4-X10"},{"t":"가게 이름","mis":"K6-2-u4-X10"}],"explanation":["표에서 유형은 동네 이름, 음식, 도로였어요.","‘두레길’은 길 이름이라 유형이 도로예요.","유형을 나누면 사례를 한눈에 볼 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_b#12','kor',6,2,'u4','','tb_g6_2_kor_u4_review_b','unit_review','K6-2-u4-C10',2,'mc','auto','『국어』 191쪽 (3)의 셋째 점검 질문에 ‘아니요’라고 답했을 때 빈칸에 들어갈 내용은 무엇인가요?',ARRAY['K6-2-u4-X13','K6-2-u4-X12']::text[],false,'{"seq":12,"concept":"K6-2-u4-C10","difficulty":2,"kind":"mc","stem":"『국어』 191쪽 (3)의 셋째 점검 질문에 ‘아니요’라고 답했을 때 빈칸에 들어갈 내용은 무엇인가요?","options":[{"t":"듣는 사람들이 내용을 이해하는 데 도움이 되는 매체로 바꿔요.","correct":true},{"t":"더 화려하고 눈에 띄는 매체로 바꿔요.","mis":"K6-2-u4-X13"},{"t":"매체를 쓰지 않고 말로만 발표하기로 해요.","mis":"K6-2-u4-X13"},{"t":"자료의 출처를 지우고 그대로 발표해요.","mis":"K6-2-u4-X12"}],"explanation":["매체는 발표를 듣는 사람의 이해를 돕기 위해 써요.","효과가 없으면 이해를 돕는 매체로 바꿔요.","화려함보다 내용 전달이 먼저예요."],"asset":{"type":"passage","lines":["① 조사한 자료의 출처는 믿을 만한가요?","→ 아니요: 출처를 점검하고 믿을 만한 자료로 바꿔요.","② 발표 자료의 양은 적절한가요?","→ 아니요: 발표 여건을 생각하며 발표 자료의 양을 줄이거나 추가해요.","③ 정한 매체는 발표에 효과적인가요?","→ 아니요: (                    )","모두 ‘예’ → 완성한 발표 자료를 다시 한번 살펴보고 발표를 준비해요."],"numbered":false,"title":"발표 자료 점검하기 — 『국어』 191쪽 (3)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_b#13','kor',6,2,'u4','','tb_g6_2_kor_u4_review_b','unit_review','K6-2-u4-C22',2,'mc','auto','「큰사전이 필요하다」에서 일본은 조선어학회에 섣불리 손을 댈 수 없었어요. ‘섣부르다’의 뜻은 무엇인가요?',ARRAY['K6-2-u4-X31']::text[],false,'{"seq":13,"concept":"K6-2-u4-C22","difficulty":2,"kind":"mc","stem":"「큰사전이 필요하다」에서 일본은 조선어학회에 섣불리 손을 댈 수 없었어요. ‘섣부르다’의 뜻은 무엇인가요?","options":[{"t":"솜씨가 익숙하지 못하고 어설프다","correct":true},{"t":"아주 빠르고 정확하다","mis":"K6-2-u4-X31"},{"t":"기회나 시기가 더할 수 없이 좋다","mis":"K6-2-u4-X31"},{"t":"배우지 못해 글을 모른다","mis":"K6-2-u4-X31"}],"explanation":["섣부르다는 솜씨가 익숙하지 못하고 어설프다는 뜻이에요.","민중의 지지가 높아 함부로 건드릴 수 없었다는 말이에요.","기회가 좋다는 뜻의 낱말은 ‘절호’예요."],"asset":{"type":"passage","lines":["보기 — 문맹 · 절호 · 천금 · 직결되다 · 섣부르다","㉠ 배우지 못하여 글을 읽거나 쓸 줄을 모름. 또는 그런 사람.","㉡ 많은 돈이나 아주 귀중한 것을 비유적으로 이르는 말.","㉢ 솜씨가 익숙하지 못하고 어설프다.","㉣ 무엇을 하기에 기회나 시기가 더할 수 없이 좋음을 이르는 말."],"numbered":false,"title":"『국어』 201쪽 3번 — 낱말의 뜻"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_b#14','kor',6,2,'u4','','tb_g6_2_kor_u4_review_b','unit_review','K6-2-u4-C21',2,'mc','auto','「큰사전이 필요하다」에서 1931년에 있었던 일은 무엇인가요?',ARRAY['K6-2-u4-X30']::text[],false,'{"seq":14,"concept":"K6-2-u4-C21","difficulty":2,"kind":"mc","stem":"「큰사전이 필요하다」에서 1931년에 있었던 일은 무엇인가요?","options":[{"t":"조선어연구회가 이름을 ‘조선어학회’로 바꾸었다","correct":true},{"t":"주시경이 ‘한글’이라는 이름을 처음 지었다","mis":"K6-2-u4-X30"},{"t":"『큰사전』 원고를 서울역에서 찾았다","mis":"K6-2-u4-X30"},{"t":"『조선말 큰사전』이 완간되었다","mis":"K6-2-u4-X30"}],"explanation":["1921년에 조선어연구회가 세워졌어요.","1931년에 이름을 조선어학회로 바꾸었어요.","그리고 주시경의 뜻을 이어받아 사전 편찬을 시작했어요."],"asset":{"type":"passage","lines":["(간추림) 제자들은 1921년 ‘조선어연구회’를 세우고 1931년 ‘조선어학회’로 이름을 바꾸었다.","(간추림) 첫째 목표 — 글을 알지 못하는 민중에게 한글을 가르치는 문맹 퇴치 운동","(간추림) 둘째 목표 — 주시경의 뜻을 이어받은 한글 사전의 편찬","“일단 쉬운 한글을 가르쳐 문맹을 퇴치한 다음에 일본어를 가르치는 게 낫지 않겠습니까?”","(간추림) 1938년 일본이 ‘일본어 상용화’를 발표하며 한글 사용을 금지했다."],"title":"「큰사전이 필요하다」 조선어학회 — 『국어』 198쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_b#15','kor',6,2,'u4','','tb_g6_2_kor_u4_review_b','unit_review','K6-2-u4-C14',2,'mc','auto','우리 반 언어생활 점검 결과를 횟수나 그래프로 나타내면 좋은 점은 무엇인가요?',ARRAY['K6-2-u4-X21']::text[],false,'{"seq":15,"concept":"K6-2-u4-C14","difficulty":2,"kind":"mc","stem":"우리 반 언어생활 점검 결과를 횟수나 그래프로 나타내면 좋은 점은 무엇인가요?","options":[{"t":"우리 반의 언어생활 실태를 한눈에 볼 수 있다","correct":true},{"t":"누가 가장 많이 틀렸는지 순위를 매길 수 있다","mis":"K6-2-u4-X21"},{"t":"점검을 하지 않아도 된다","mis":"K6-2-u4-X21"},{"t":"외래어를 많이 쓴 친구를 놀릴 수 있다","mis":"K6-2-u4-X21"}],"explanation":["횟수나 그래프로 나타내면 실태를 직관적으로 볼 수 있어요.","온라인 설문을 쓰면 시간도 줄일 수 있어요.","순위를 매기거나 놀리려는 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_b#16','kor',6,2,'u4','','tb_g6_2_kor_u4_review_b','unit_review','K6-2-u4-C15',2,'mc','auto','어떤 친구가 쓴 다짐문에 제목, 목적, 실천 약속만 있었어요. 더 넣어야 할 부분은 무엇인가요?',ARRAY['K6-2-u4-X22','K6-2-u4-X24','K6-2-u4-X21']::text[],false,'{"seq":16,"concept":"K6-2-u4-C15","difficulty":2,"kind":"mc","stem":"어떤 친구가 쓴 다짐문에 제목, 목적, 실천 약속만 있었어요. 더 넣어야 할 부분은 무엇인가요?","options":[{"t":"전하고 싶은 말, 날짜와 쓴 사람","correct":true},{"t":"등장인물과 사건, 배경","mis":"K6-2-u4-X22"},{"t":"그림과 색깔, 꾸밈 글씨","mis":"K6-2-u4-X24"},{"t":"친구들의 잘못과 벌칙","mis":"K6-2-u4-X21"}],"explanation":["실천 다짐문에는 목적, 실천 약속, 전하고 싶은 말을 써요.","마지막 부분에는 날짜와 쓴 사람을 써요.","빠진 부분을 채우면 다짐문이 완성돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_b#17','kor',6,2,'u4','','tb_g6_2_kor_u4_review_b','unit_review','K6-2-u4-C12',3,'mc','auto','글의 내용을 추론하고 쓴 뒤에 할 일로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u4-X36','K6-2-u4-X16']::text[],false,'{"seq":17,"concept":"K6-2-u4-C12","difficulty":3,"kind":"mc","stem":"글의 내용을 추론하고 쓴 뒤에 할 일로 가장 알맞은 것은 무엇인가요?","options":[{"t":"친구의 추론과 비교해 보고, 생략된 내용을 짐작한 방법도 이야기한다","correct":true},{"t":"내 추론과 다르면 친구의 추론은 틀렸다고 한다","mis":"K6-2-u4-X36"},{"t":"추론한 방법은 말하지 않고 답만 말한다","mis":"K6-2-u4-X16"},{"t":"추론은 정답이 하나라서 비교할 필요가 없다","mis":"K6-2-u4-X36"}],"explanation":["추론은 사람마다 조금씩 다를 수 있어요.","친구의 생각과 비교하며 짐작한 방법을 나누어요.","근거가 있으면 서로 다른 추론도 존중해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_b#18','kor',6,2,'u4','','tb_g6_2_kor_u4_review_b','unit_review','K6-2-u4-C4',3,'mc','auto','학교에서 볼 수 있는 낱말을 고유어, 한자어, 외래어로 분류하기 어려울 때 해야 할 일로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u4-X05','K6-2-u4-X01','K6-2-u4-X12']::text[],false,'{"seq":18,"concept":"K6-2-u4-C4","difficulty":3,"kind":"mc","stem":"학교에서 볼 수 있는 낱말을 고유어, 한자어, 외래어로 분류하기 어려울 때 해야 할 일로 알맞은 것은 무엇인가요?","options":[{"t":"국어사전을 활용해 낱말 뒤에 무엇이 붙어 있는지 확인한다","correct":true},{"t":"소리가 낯설면 외국에서 들어온 외래어로 정한다","mis":"K6-2-u4-X05"},{"t":"자주 쓰는 말은 모두 우리말인 고유어로 정한다","mis":"K6-2-u4-X01"},{"t":"친구가 정한 대로 따라 표에 옮겨 쓴다","mis":"K6-2-u4-X12"}],"explanation":["낱말만 보고 갈래를 가르기는 어려울 수 있어요.","국어사전에서 한자나 외국어가 함께 있는지 확인해요.","한글 표기만 있으면 고유어예요."],"asset":{"type":"passage","lines":["1. 학교에서 볼 수 있는 낱말을 고유어, 한자어, 외래어로 분류해 봅시다.","2. 분류한 한자어나 외래어 가운데에서 고유어로 고칠 수 있는 낱말을 고쳐 써 봅시다.","[표] 한자어나 외래어 · 낱말의 뜻 · 고유어","3. 학교에서 볼 수 있는 고유어 가운데 하나를 넣어 문장을 만들어 봅시다."],"numbered":false,"title":"학교에서 볼 수 있는 낱말을 분류하고 고유어로 고쳐 쓰기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_b#19','kor',6,2,'u4','','tb_g6_2_kor_u4_review_b','unit_review','K6-2-u4-C26',3,'mc','auto','주시경 선생님이 쓴 편지의 날짜가 ‘10월 9일’이에요. 이 날짜를 보고 추론할 수 있는 것은 무엇인가요?',ARRAY['K6-2-u4-X16','K6-2-u4-X17']::text[],false,'{"seq":19,"concept":"K6-2-u4-C26","difficulty":3,"kind":"mc","stem":"주시경 선생님이 쓴 편지의 날짜가 ‘10월 9일’이에요. 이 날짜를 보고 추론할 수 있는 것은 무엇인가요?","options":[{"t":"한글날을 맞아 한글의 소중함을 전하려고 쓴 편지일 것이다","correct":true},{"t":"주시경의 생일을 알리려고 쓴 편지일 것이다","mis":"K6-2-u4-X16"},{"t":"날짜에는 아무 뜻이 없다","mis":"K6-2-u4-X17"},{"t":"일본에 보내려고 쓴 편지일 것이다","mis":"K6-2-u4-X16"}],"explanation":["10월 9일은 한글날이에요.","내가 아는 지식과 편지의 내용을 이어 추론해요.","편지는 한글이 소중한 보물이라고 말해요."],"asset":{"type":"passage","lines":["저는 주시경이라고 해요. 예전에는 ‘한힌샘’이라는 이름으로도 불렸어요.","(간추림) ‘한’은 하나뿐인 크고 위대한 나라, ‘힌샘’은 맑고 깨끗한 샘물처럼","(간추림) 지혜롭고 밝은 생각이 흘러나오는 곳을 뜻한다.","(간추림) 나라를 빼앗겼을 때 우리말 사전을 만들고 한글을 가르치는 데 온 마음을 다했다.","한글은 우리 겨레의 숨결이 담긴 소중한 보물이에요.","보물은 소중히 아끼고 가꿀수록 더욱 빛이 날 거예요.","[날짜와 쓴 사람] ○○○○년 10월 9일 · 우리말을 사랑하는 주시경 선생님이"],"numbered":false,"title":"주시경 선생님이 쓴 편지 — 글을 읽고 추론하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_b#20','kor',6,2,'u4','','tb_g6_2_kor_u4_review_b','unit_review','K6-2-u4-C24',3,'mc','auto','「야, 겨울 온다」에서 말하는 이가 쑥부쟁이를 걱정하는 까닭은 무엇인가요?',ARRAY['K6-2-u4-X34']::text[],false,'{"seq":20,"concept":"K6-2-u4-C24","difficulty":3,"kind":"mc","stem":"「야, 겨울 온다」에서 말하는 이가 쑥부쟁이를 걱정하는 까닭은 무엇인가요?","options":[{"t":"겨울이 다가오는데도 쑥부쟁이가 아직도 방그레 웃고 있어서","correct":true},{"t":"쑥부쟁이가 추위에 시들어 울고 있어서","mis":"K6-2-u4-X34"},{"t":"쑥부쟁이가 길섶을 가득 막고 서 있어서","mis":"K6-2-u4-X34"},{"t":"쑥부쟁이가 겨울이 오기도 전에 너무 빨리 져서","mis":"K6-2-u4-X34"}],"explanation":["“쑥부쟁인 아직도 방그레 웃어 걱정이다.”를 읽어요.","날이 추워지는데 꽃이 아직 피어 웃고 있어요.","꽃을 아끼는 마음이 느껴져요."],"asset":{"type":"passage","lines":["제비 떠나가고 기러기 돌아왔다.","쑥부쟁인 아직도 방그레 웃어 걱정이다.","길섶 나무들아 따스운 옷을 입어라.","(간추림) 오소리랑 너구리는 긴 잠에 들고, 미꾸리들에게는 도랑 깊이 숨으라고 한다.","걸음마다 바삭바삭","(간추림) 마지막에 겨울이 온다고 반갑게 외친다."],"title":"「야, 겨울 온다」(강순예 글) — 『국어』 214쪽","hi":["방그레","길섶","바삭바삭"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_b#21','kor',6,2,'u4','','tb_g6_2_kor_u4_review_b','unit_review','K6-2-u4-C16',3,'mc','auto','홍보물을 완성해 친구들 앞에서 발표한 뒤에 할 일로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u4-X13','K6-2-u4-X26','K6-2-u4-X21']::text[],false,'{"seq":21,"concept":"K6-2-u4-C16","difficulty":3,"kind":"mc","stem":"홍보물을 완성해 친구들 앞에서 발표한 뒤에 할 일로 알맞은 것은 무엇인가요?","options":[{"t":"친구들의 발표를 듣고 느낀 점이나 보충할 점을 함께 이야기한다","correct":true},{"t":"가장 화려한 홍보물에만 박수를 친다","mis":"K6-2-u4-X13"},{"t":"발표가 끝나면 홍보물을 바로 버린다","mis":"K6-2-u4-X26"},{"t":"다른 모둠의 홍보물에서 흠만 찾는다","mis":"K6-2-u4-X21"}],"explanation":["발표를 들은 뒤 느낀 점을 나누어요.","보충할 점을 이야기하면 홍보물이 더 좋아져요.","활동하며 느낀 점과 깨달은 점도 이야기해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_b#22','kor',6,2,'u4','','tb_g6_2_kor_u4_review_b','unit_review','K6-2-u4-C15',3,'mc','auto','친구들의 의견을 바탕으로 실천 다짐문을 고쳐 쓴 뒤에 할 일로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u4-X26','K6-2-u4-X24']::text[],false,'{"seq":22,"concept":"K6-2-u4-C15","difficulty":3,"kind":"mc","stem":"친구들의 의견을 바탕으로 실천 다짐문을 고쳐 쓴 뒤에 할 일로 알맞은 것은 무엇인가요?","options":[{"t":"고친 내용도 점검 항목에 따라 다시 점검한다","correct":true},{"t":"고쳤으니 다시 볼 필요가 없다","mis":"K6-2-u4-X26"},{"t":"친구에게 대신 고쳐 달라고 한다","mis":"K6-2-u4-X24"},{"t":"처음에 쓴 것으로 되돌려 놓는다","mis":"K6-2-u4-X24"}],"explanation":["고친 다짐문도 다시 점검해요.","끝까지 최선을 다해 다짐문을 완성해요.","그다음 여러 방법으로 공유해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_b#23','kor',6,2,'u4','','tb_g6_2_kor_u4_review_b','unit_review','K6-2-u4-C6',4,'essay','teacher','학교에서 볼 수 있는 한자어나 외래어 하나를 골라 ‘한자어나 외래어 · 낱말의 뜻 · 고유어’ 표에 맞게 쓰세요. 그렇게 고친 까닭도 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K6-2-u4-C6","difficulty":4,"kind":"essay","stem":"학교에서 볼 수 있는 한자어나 외래어 하나를 골라 ‘한자어나 외래어 · 낱말의 뜻 · 고유어’ 표에 맞게 쓰세요. 그렇게 고친 까닭도 쓰세요.","answer_guide":{"answer":"예: 서클 · 함께 모여 어떤 활동을 하는 모임 · 동아리. 동아리라고 하면 함께 모인 사람들이라는 뜻을 누구나 쉽게 알 수 있어서 고쳤다.","scoring_points":["한자어나 외래어 하나를 골랐는가","낱말의 뜻을 확인해 썼는가","뜻에 맞는 고유어로 고치고 까닭을 썼는가"]},"explanation":["먼저 고치려는 낱말의 뜻을 정확히 확인해요.","비슷한 뜻의 고유어를 찾아요.","참고 자료나 다듬은 말 자료를 활용해도 좋아요."],"asset":{"type":"passage","lines":["1. 학교에서 볼 수 있는 낱말을 고유어, 한자어, 외래어로 분류해 봅시다.","2. 분류한 한자어나 외래어 가운데에서 고유어로 고칠 수 있는 낱말을 고쳐 써 봅시다.","[표] 한자어나 외래어 · 낱말의 뜻 · 고유어","3. 학교에서 볼 수 있는 고유어 가운데 하나를 넣어 문장을 만들어 봅시다."],"numbered":false,"title":"학교에서 볼 수 있는 낱말을 분류하고 고유어로 고쳐 쓰기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_b#24','kor',6,2,'u4','','tb_g6_2_kor_u4_review_b','unit_review','K6-2-u4-C26',4,'essay','teacher','주시경 선생님이 쓴 편지를 읽고 글쓴이의 의도에 대한 자신의 생각을 쓰고, 친구와 생각이 다를 때 어떻게 이야기 나눌지도 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u4-C26","difficulty":4,"kind":"essay","stem":"주시경 선생님이 쓴 편지를 읽고 글쓴이의 의도에 대한 자신의 생각을 쓰고, 친구와 생각이 다를 때 어떻게 이야기 나눌지도 쓰세요.","answer_guide":{"answer":"예: 글쓴이는 어린이들이 한글을 마음껏 쓸 수 있게 된 것을 고맙게 여기고 한글을 아껴 쓰기를 바랐다고 생각한다. 친구의 생각이 나와 다르면 어떤 문장을 근거로 그렇게 생각했는지 묻고, 내 근거도 말하며 서로의 생각을 존중하겠다.","scoring_points":["글쓴이의 의도에 대한 자신의 생각을 썼는가","근거가 편지 내용과 이어지는가","다른 생각을 존중하며 나누는 방법을 썼는가"]},"explanation":["글쓴이가 무엇을 바라는지 생각해요.","추론은 사람마다 조금씩 다를 수 있어요.","서로의 근거를 듣고 존중해요."],"asset":{"type":"passage","lines":["저는 주시경이라고 해요. 예전에는 ‘한힌샘’이라는 이름으로도 불렸어요.","(간추림) ‘한’은 하나뿐인 크고 위대한 나라, ‘힌샘’은 맑고 깨끗한 샘물처럼","(간추림) 지혜롭고 밝은 생각이 흘러나오는 곳을 뜻한다.","(간추림) 나라를 빼앗겼을 때 우리말 사전을 만들고 한글을 가르치는 데 온 마음을 다했다.","한글은 우리 겨레의 숨결이 담긴 소중한 보물이에요.","보물은 소중히 아끼고 가꿀수록 더욱 빛이 날 거예요.","[날짜와 쓴 사람] ○○○○년 10월 9일 · 우리말을 사랑하는 주시경 선생님이"],"numbered":false,"title":"주시경 선생님이 쓴 편지 — 글을 읽고 추론하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_b#25','kor',6,2,'u4','','tb_g6_2_kor_u4_review_b','unit_review','K6-2-u4-C16',4,'essay','teacher','아름다운 우리말의 소중함을 알리는 활동을 하나 정해 계획을 쓰세요. 활동 방법, 함께할 사람(반 전체·모둠·짝·혼자), 꾸준히 이어 갈 방법을 넣으세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u4-C16","difficulty":4,"kind":"essay","stem":"아름다운 우리말의 소중함을 알리는 활동을 하나 정해 계획을 쓰세요. 활동 방법, 함께할 사람(반 전체·모둠·짝·혼자), 꾸준히 이어 갈 방법을 넣으세요.","answer_guide":{"answer":"예: 활동 — 고유어를 몸짓으로 전달하기 놀이 / 함께할 사람 — 모둠 / 이어 갈 방법 — 매주 금요일마다 새 고유어 다섯 개를 조사해 놀이하고 교실 알림판에 고유어와 뜻을 붙인다.","scoring_points":["우리말의 소중함을 알리는 활동을 골랐는가","활동 방법과 함께할 사람을 정했는가","꾸준히 이어 갈 방법을 썼는가"]},"explanation":["『국어』 212~213쪽과 우리 반 활동 예시를 떠올려요.","누구와 할지 정해요.","한 번으로 끝나지 않게 이어 갈 방법을 생각해요."],"asset":{"type":"passage","lines":["① 하고 싶은 활동 정하기","→ 우리가 정한 활동을 반 전체가 할지, 모둠으로 할지, 짝과 할지, 혼자 할지 정해요.","② 활동하기","③ 활동 소감 나누기"],"numbered":false,"title":"우리가 활동을 정해요 — 『국어』 213쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_c#1','kor',6,2,'u4','','tb_g6_2_kor_u4_review_c','unit_review','K6-2-u4-C4',1,'ox','auto','국어사전에서 ‘미술’을 찾으면 ‘美術’이라는 한자가 함께 있으니 ‘미술’은 한자어예요.',ARRAY['K6-2-u4-X01']::text[],false,'{"seq":1,"concept":"K6-2-u4-C4","difficulty":1,"kind":"ox","stem":"국어사전에서 ‘미술’을 찾으면 ‘美術’이라는 한자가 함께 있으니 ‘미술’은 한자어예요.","answer":"O","reason_options":[{"t":"낱말 뒤에 한자가 같이 있으면 한자어예요.","correct":true},{"t":"자주 쓰는 말이니 ‘미술’은 고유어예요.","mis":"K6-2-u4-X01"}],"mis":"K6-2-u4-X01","explanation":["친구 2는 ‘미술’ 뒤에 ‘美術’이라는 한자가 붙어 있다고 했어요.","한자가 같이 있으면 한자어예요.","자주 쓰는지로 갈래를 정하지 않아요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"“글에 나온 여러 낱말을 사전에서 찾아보니 각각의 종류가 다른 것 같아.”"},{"who":"친구 2","text":"“그래. ‘미술’을 사전에서 찾아보니 낱말 뒤에 ‘美術’이라는 한자가 붙어 있네.”"},{"who":"친구 3","text":"“‘벤치’라는 낱말 뒤에는 ‘bench’라는 영어가 붙어 있는데, ‘시나브로’와 ‘군침’ 뒤에는 아무것도 붙어 있지 않아.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_c#2','kor',6,2,'u4','','tb_g6_2_kor_u4_review_c','unit_review','K6-2-u4-C1',1,'mc','auto','할머니가 말한 ‘뒤란’이 어디인지 짐작할 수 있는 단서로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u4-X18','K6-2-u4-X16']::text[],false,'{"seq":2,"concept":"K6-2-u4-C1","difficulty":1,"kind":"mc","stem":"할머니가 말한 ‘뒤란’이 어디인지 짐작할 수 있는 단서로 알맞은 것은 무엇인가요?","options":[{"t":"“뒤란에 가서 장독대를 덮고 오겠니?”라는 말","correct":true},{"t":"‘뒤란’이라는 글자의 모양과 소리","mis":"K6-2-u4-X18"},{"t":"아이가 입은 옷과 할머니의 표정","mis":"K6-2-u4-X16"},{"t":"단서가 없으니 마음대로 정한다","mis":"K6-2-u4-X16"}],"explanation":["할머니는 뒤란에 가서 장독대를 덮으라고 했어요.","그러니 뒤란은 장독대가 있는 곳임을 짐작할 수 있어요.","정확한 뜻은 국어사전에서 확인해요."],"asset":{"type":"speech","turns":[{"who":"할머니","text":"“얼른 비설거지 해야겠다. 그래야 비를 안 맞지.”"},{"who":"할머니","text":"“뒤란에 가서 장독대를 덮고 오겠니?”"},{"who":"아이","text":"“비설거지가 뭐지? 뒤란은 어디일까?”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_c#3','kor',6,2,'u4','','tb_g6_2_kor_u4_review_c','unit_review','K6-2-u4-C18',1,'mc','auto','「조각하늘」에서 하늘이 하고 싶어 하는 것처럼 보인다고 한 놀이는 무엇인가요?',ARRAY['K6-2-u4-X29']::text[],false,'{"seq":3,"concept":"K6-2-u4-C18","difficulty":1,"kind":"mc","stem":"「조각하늘」에서 하늘이 하고 싶어 하는 것처럼 보인다고 한 놀이는 무엇인가요?","options":[{"t":"숨바꼭질","correct":true},{"t":"술래잡기","mis":"K6-2-u4-X29"},{"t":"줄넘기","mis":"K6-2-u4-X29"},{"t":"물놀이","mis":"K6-2-u4-X29"}],"explanation":["시의 첫 줄을 다시 읽어요.","하늘이 숨바꼭질하고 싶은가 보다고 했어요.","구름 뒤에 숨어 나오지 않기 때문이에요."],"asset":{"type":"passage","lines":["하늘이 숨바꼭질하고 싶은가 봐요.","구름 뒤에 숨어서 나올 생각을 안 해요.","호수에 비친 자기 얼굴만","빠끔히 내다보고","구름 뒤로 쏘옥 숨어요.","(간추림) 바람이 호수를 간지럽혀도 조각하늘은 구름 뒤에서 좀처럼 나오지 않는다."],"title":"「조각하늘」(권지영 글) — 『국어』 180쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_c#4','kor',6,2,'u4','','tb_g6_2_kor_u4_review_c','unit_review','K6-2-u4-C6',1,'mc','auto','국립국어원 ‘다듬은 말’ 자료에서 ‘네티즌’을 다듬은 말은 무엇인가요?',ARRAY['K6-2-u4-X08']::text[],false,'{"seq":4,"concept":"K6-2-u4-C6","difficulty":1,"kind":"mc","stem":"국립국어원 ‘다듬은 말’ 자료에서 ‘네티즌’을 다듬은 말은 무엇인가요?","options":[{"t":"누리꾼","correct":true},{"t":"인터넷 사람","mis":"K6-2-u4-X08"},{"t":"네티즌족","mis":"K6-2-u4-X08"},{"t":"컴퓨터꾼","mis":"K6-2-u4-X08"}],"explanation":["‘네티즌’을 ‘누리꾼’으로 다듬었어요.","‘디엠’은 ‘쪽지’, ‘신참자’는 ‘새내기’로 다듬었어요.","다듬은 말은 누구나 알아듣게 하려는 것이에요."],"asset":{"type":"passage","lines":["가십 → 소문","네티즌 → 누리꾼","더치페이 → 각자 내기","디엠 → 쪽지","섬네일 → 마중그림","스토리보드 → 줄거리판","신참자 → 새내기","인터체인지 → 나들목"],"title":"다듬은 말 더 보기(국립국어원 ‘다듬은 말’ 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_c#5','kor',6,2,'u4','','tb_g6_2_kor_u4_review_c','unit_review','K6-2-u4-C7',1,'mc','auto','『국어』 186쪽 ㉮ 대화에서 쓰인 고유어 관용 표현은 무엇인가요?',ARRAY['K6-2-u4-X09']::text[],false,'{"seq":5,"concept":"K6-2-u4-C7","difficulty":1,"kind":"mc","stem":"『국어』 186쪽 ㉮ 대화에서 쓰인 고유어 관용 표현은 무엇인가요?","options":[{"t":"눈도 깜짝 안 하다","correct":true},{"t":"날개 돋치다","mis":"K6-2-u4-X09"},{"t":"치과 치료를 받다","mis":"K6-2-u4-X09"},{"t":"놀라지 않다","mis":"K6-2-u4-X09"}],"explanation":["㉮는 치과 치료 이야기예요.","“응, 눈도 깜짝 안 했어.”라고 대답했어요.","‘날개 돋치다’는 ㉯ 대화에 나와요."],"asset":{"type":"speech","turns":[{"who":"㉮ 친구 1","text":"“치과 치료를 받을 때 놀라지 않았어?”"},{"who":"㉮ 친구 2","text":"“응, 눈도 깜짝 안 했어.”"},{"who":"㉯ 친구 1","text":"“학교 알뜰 장터에서 무엇을 샀어?”"},{"who":"㉯ 친구 2","text":"“예쁜 물건은 날개 돋친 듯이 팔려 나가서 이걸 겨우 샀어.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_c#6','kor',6,2,'u4','','tb_g6_2_kor_u4_review_c','unit_review','K6-2-u4-C21',1,'ox','auto','「큰사전이 필요하다」에서 주시경과 제자들이 편찬한 『말모이』는 완성되어 널리 출간되었어요.',ARRAY['K6-2-u4-X30']::text[],false,'{"seq":6,"concept":"K6-2-u4-C21","difficulty":1,"kind":"ox","stem":"「큰사전이 필요하다」에서 주시경과 제자들이 편찬한 『말모이』는 완성되어 널리 출간되었어요.","answer":"X","reason_options":[{"t":"주시경이 생을 마친 뒤 『말모이』는 빛을 보지 못하고 묻혔어요.","correct":true},{"t":"『말모이』는 1914년에 출간되어 우리나라 최초의 사전이 되었어요.","mis":"K6-2-u4-X30"}],"mis":"K6-2-u4-X30","explanation":["주시경은 원고를 가지고 외국으로 나가기 전에 생을 마쳤어요.","참여한 사람들도 떠나가 『말모이』는 묻히고 말았어요.","그 뜻은 조선어학회가 이어받았어요."],"asset":{"type":"passage","lines":["(간추림) 1908년 주시경은 ‘국어연구학회’를 만들어 제자들과 사전을 만들기 시작했다.","사전의 이름은 “말을 모아 놓았다.”라는 뜻에서 ‘말모이’라 정했다.","(간추림) 1914년 원고를 가지고 외국으로 나갈 계획이었지만 그 전에 생을 마쳤다.","(간추림) 참여한 사람들도 떠나가 『말모이』는 빛을 보지 못하고 묻혔다."],"title":"「큰사전이 필요하다」 『말모이』 — 『국어』 196~197쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_c#7','kor',6,2,'u4','','tb_g6_2_kor_u4_review_c','unit_review','K6-2-u4-C13',1,'mc','auto','「우리말의 보물을 찾아서, ‘시골말 캐기’」에서 표준어 ‘구멍’의 방언으로 든 말은 무엇인가요?',ARRAY['K6-2-u4-X33']::text[],false,'{"seq":7,"concept":"K6-2-u4-C13","difficulty":1,"kind":"mc","stem":"「우리말의 보물을 찾아서, ‘시골말 캐기’」에서 표준어 ‘구멍’의 방언으로 든 말은 무엇인가요?","options":[{"t":"구먹, 구명, 구녕, 구무","correct":true},{"t":"세우리, 정구지","mis":"K6-2-u4-X33"},{"t":"부치개, 지지미, 찌짐","mis":"K6-2-u4-X33"},{"t":"깡냉이, 강내이, 옥시기","mis":"K6-2-u4-X33"}],"explanation":["글에서 구멍 대신 구먹, 구명, 구녕, 구무 같은 말을 쓴다고 했어요.","세우리, 정구지는 부추의 방언이에요.","시골말 캐기는 이런 지역의 말을 모은 운동이에요."],"asset":{"type":"passage","lines":["(간추림) 사전을 만들려고 전국의 우리말을 모으던 시절, 학자들은 ‘시골말 캐기’를 펼쳤다.","(간추림) 구멍 대신 구먹·구명·구녕·구무, 부추 대신 세우리·정구지 같은 말을 모았다.","(간추림) 방학을 맞은 전국의 학생들이 고향에서 실제 쓰는 말을 종이에 써 보냈다.","(간추림) 학자들은 각 지역의 개성이 담긴 방언도 우리 민족의 소중한 보물이라고 생각했다.","(간추림) 모인 수많은 말은 『큰사전』을 만드는 든든한 뿌리가 되었다."],"title":"「우리말의 보물을 찾아서, ‘시골말 캐기’」 — 『국어』 204쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_c#8','kor',6,2,'u4','','tb_g6_2_kor_u4_review_c','unit_review','K6-2-u4-C25',1,'mc','auto','『국어』 217쪽 예문 “이 약은 (     )을/를 돕는 데 효과가 있다.”의 빈칸에 알맞은 낱말은 무엇인가요?',ARRAY['K6-2-u4-X35']::text[],false,'{"seq":8,"concept":"K6-2-u4-C25","difficulty":1,"kind":"mc","stem":"『국어』 217쪽 예문 “이 약은 (     )을/를 돕는 데 효과가 있다.”의 빈칸에 알맞은 낱말은 무엇인가요?","options":[{"t":"소화","correct":true},{"t":"연소","mis":"K6-2-u4-X35"},{"t":"교류","mis":"K6-2-u4-X35"},{"t":"강수량","mis":"K6-2-u4-X35"}],"explanation":["소화는 음식물을 분해하여 영양분을 흡수하기 쉬운 형태로 바꾸는 일이에요.","약이 돕는 일이니 ‘소화’가 알맞아요.","연소는 물질이 타는 현상이에요."],"asset":{"type":"passage","lines":["㉠ 옛날 사람들은 측우기로 (     )을/를 알 수 있었다.","㉡ 다른 나라들과 경제 (     )이/가 활발하다.","㉢ 최근 들어 전 세계적으로 급격한 (     ) 변화가 나타나고 있다.","㉣ 이 약은 (     )을/를 돕는 데 효과가 있다."],"numbered":false,"title":"기초 다지기 — 낱말이 쓰인 예 『국어』 217쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_c#9','kor',6,2,'u4','','tb_g6_2_kor_u4_review_c','unit_review','K6-2-u4-C4',2,'mc','auto','국어사전에서 ‘시나브로’와 ‘군침’을 찾았을 때 알 수 있는 것은 무엇인가요?',ARRAY['K6-2-u4-X05']::text[],false,'{"seq":9,"concept":"K6-2-u4-C4","difficulty":2,"kind":"mc","stem":"국어사전에서 ‘시나브로’와 ‘군침’을 찾았을 때 알 수 있는 것은 무엇인가요?","options":[{"t":"낱말 뒤에 아무것도 붙어 있지 않아 고유어임을 알 수 있다","correct":true},{"t":"낱말 뒤에 한자가 붙어 있어 한자어임을 알 수 있다","mis":"K6-2-u4-X05"},{"t":"낱말 뒤에 영어가 붙어 있어 외래어임을 알 수 있다","mis":"K6-2-u4-X05"},{"t":"사전으로는 갈래를 알 수 없다","mis":"K6-2-u4-X05"}],"explanation":["사전에서 한글 표기만 있으면 고유어예요.","‘시나브로’, ‘군침’ 뒤에는 아무것도 붙어 있지 않아요.","헷갈리는 낱말은 사전에서 확인해요."],"asset":{"type":"passage","lines":["미술(美術) — 공간 및 시각의 미를 표현하는 예술.","벤치(bench) — 여러 사람이 함께 앉을 수 있는 긴 의자.","시나브로 — 모르는 사이에 조금씩 조금씩.","군침 — 음식이 먹고 싶어서 입안에 도는 침."],"title":"국어사전에서 찾은 낱말 — 『국어』 183쪽 2번 (1)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_c#10','kor',6,2,'u4','','tb_g6_2_kor_u4_review_c','unit_review','K6-2-u4-C20',2,'mc','auto','『국어』 185쪽 3번 (4) 예시 답안에서 ‘샛길’의 뜻은 무엇인가요?',ARRAY['K6-2-u4-X18','K6-2-u4-X37']::text[],false,'{"seq":10,"concept":"K6-2-u4-C20","difficulty":2,"kind":"mc","stem":"『국어』 185쪽 3번 (4) 예시 답안에서 ‘샛길’의 뜻은 무엇인가요?","options":[{"t":"사이에 난 길","correct":true},{"t":"새로 닦은 큰길","mis":"K6-2-u4-X18"},{"t":"새가 날아다니는 길","mis":"K6-2-u4-X18"},{"t":"길이 끝나는 곳","mis":"K6-2-u4-X37"}],"explanation":["샛길은 사이에 난 길이에요.","무언가 사이에 쏙 나 있는 길을 재미있게 나타냈어요.","『국어』 185쪽 3번 (4)에서 사전으로 뜻을 찾았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_c#11','kor',6,2,'u4','','tb_g6_2_kor_u4_review_c','unit_review','K6-2-u4-C9',2,'mc','auto','고유어를 활용한 사례를 조사한 뒤 정리하는 표의 네 칸은 무엇인가요?',ARRAY['K6-2-u4-X11','K6-2-u4-X13','K6-2-u4-X12']::text[],false,'{"seq":11,"concept":"K6-2-u4-C9","difficulty":2,"kind":"mc","stem":"고유어를 활용한 사례를 조사한 뒤 정리하는 표의 네 칸은 무엇인가요?","options":[{"t":"유형, 사례, 고유어, 고유어의 뜻","correct":true},{"t":"이름, 날짜, 장소, 사진","mis":"K6-2-u4-X11"},{"t":"사례, 그림, 색깔, 크기","mis":"K6-2-u4-X13"},{"t":"사례, 출처 없음, 짐작, 소문","mis":"K6-2-u4-X12"}],"explanation":["『국어』 189쪽 (4)의 표는 네 칸이에요.","유형, 사례, 고유어, 고유어의 뜻이에요.","발표를 들을 때도 같은 칸으로 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_c#12','kor',6,2,'u4','','tb_g6_2_kor_u4_review_c','unit_review','K6-2-u4-C10',2,'mc','auto','『국어』 190쪽 안내에 따르면 발표 자료를 보여 주는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u4-X27','K6-2-u4-X13']::text[],false,'{"seq":12,"concept":"K6-2-u4-C10","difficulty":2,"kind":"mc","stem":"『국어』 190쪽 안내에 따르면 발표 자료를 보여 주는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"종이 자료나 컴퓨터 화면을 보여 주거나 태블릿 피시로 자료를 공유한다","correct":true},{"t":"발표 자료는 반드시 종이에 써서 종이로만 보여 준다","mis":"K6-2-u4-X27"},{"t":"매체는 한 발표에 한 가지만 쓸 수 있다","mis":"K6-2-u4-X27"},{"t":"자료는 보여 주지 않고 말로만 설명한다","mis":"K6-2-u4-X13"}],"explanation":["발표할 때 종이 자료나 컴퓨터 화면을 보여 줄 수 있어요.","태블릿 피시로 자료를 공유할 수도 있어요.","발표 내용과 교실 여건에 맞게 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_c#13','kor',6,2,'u4','','tb_g6_2_kor_u4_review_c','unit_review','K6-2-u4-C22',2,'mc','auto','「큰사전이 필요하다」에서 “일본에게 절호의 기회가 찾아왔다.”라고 했어요. ‘절호’의 뜻은 무엇인가요?',ARRAY['K6-2-u4-X31']::text[],false,'{"seq":13,"concept":"K6-2-u4-C22","difficulty":2,"kind":"mc","stem":"「큰사전이 필요하다」에서 “일본에게 절호의 기회가 찾아왔다.”라고 했어요. ‘절호’의 뜻은 무엇인가요?","options":[{"t":"무엇을 하기에 기회나 시기가 더할 수 없이 좋음","correct":true},{"t":"모든 기회를 잃어버려 아무것도 할 수 없음","mis":"K6-2-u4-X31"},{"t":"많은 돈이나 아주 귀중한 것을 이르는 말","mis":"K6-2-u4-X31"},{"t":"솜씨가 익숙하지 못하고 어설픔","mis":"K6-2-u4-X31"}],"explanation":["절호는 기회나 시기가 더할 수 없이 좋음을 이르는 말이에요.","일본은 일기장 사건을 빌미로 조선어학회를 탄압했어요.","그래서 그때를 절호의 기회라고 했어요."],"asset":{"type":"passage","lines":["(간추림) 1942년 함흥에서 기차 안에서 우리말을 쓴 학생들이 일본 경찰에 붙잡혔다.","(간추림) 학생의 일기장을 단서로 교사 정태진이 조선어학회 회원임이 밝혀졌다.","(간추림) 일제는 이를 빌미로 조선어학회를 탄압하고 『큰사전』 원고를 모두 압수했다.","(간추림) 1945년 광복 뒤 회원들은 원고를 찾아 전국을 뒤졌지만 찾지 못했다.","“『큰사전』의 원고를 찾아야 합니다!”"],"title":"「큰사전이 필요하다」 빼앗긴 원고 — 『국어』 199쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_c#14','kor',6,2,'u4','','tb_g6_2_kor_u4_review_c','unit_review','K6-2-u4-C21',2,'mc','auto','「큰사전이 필요하다」에서 1942년에 있었던 일은 무엇인가요?',ARRAY['K6-2-u4-X30']::text[],false,'{"seq":14,"concept":"K6-2-u4-C21","difficulty":2,"kind":"mc","stem":"「큰사전이 필요하다」에서 1942년에 있었던 일은 무엇인가요?","options":[{"t":"조선어학회가 편찬하던 사전 원고를 전부 압수당했다","correct":true},{"t":"주시경이 국어연구학회를 만들었다","mis":"K6-2-u4-X30"},{"t":"한일 합병 조약이 발표되었다","mis":"K6-2-u4-X30"},{"t":"우리나라가 광복을 맞았다","mis":"K6-2-u4-X30"}],"explanation":["1942년 함흥의 일기장 사건이 일어났어요.","일제는 이를 빌미로 조선어학회를 탄압했어요.","그때 『큰사전』 원고를 모두 압수했어요."],"asset":{"type":"passage","lines":["(간추림) 1942년 함흥에서 기차 안에서 우리말을 쓴 학생들이 일본 경찰에 붙잡혔다.","(간추림) 학생의 일기장을 단서로 교사 정태진이 조선어학회 회원임이 밝혀졌다.","(간추림) 일제는 이를 빌미로 조선어학회를 탄압하고 『큰사전』 원고를 모두 압수했다.","(간추림) 1945년 광복 뒤 회원들은 원고를 찾아 전국을 뒤졌지만 찾지 못했다.","“『큰사전』의 원고를 찾아야 합니다!”"],"title":"「큰사전이 필요하다」 빼앗긴 원고 — 『국어』 199쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_c#15','kor',6,2,'u4','','tb_g6_2_kor_u4_review_c','unit_review','K6-2-u4-C14',2,'ox','auto','언어생활 점검표는 친구를 놀리려는 것이 아니라 우리 반의 언어생활을 돌아보고 바르게 고치려고 써요.',ARRAY['K6-2-u4-X21']::text[],false,'{"seq":15,"concept":"K6-2-u4-C14","difficulty":2,"kind":"ox","stem":"언어생활 점검표는 친구를 놀리려는 것이 아니라 우리 반의 언어생활을 돌아보고 바르게 고치려고 써요.","answer":"O","reason_options":[{"t":"점검하는 목적을 생각하며 비난하거나 놀리지 않아요.","correct":true},{"t":"점검표는 말을 가장 많이 틀린 친구를 찾으려고 써요.","mis":"K6-2-u4-X21"}],"mis":"K6-2-u4-X21","explanation":["점검표를 쓰는 목적을 먼저 알아요.","친구를 비난하거나 놀리는 일이 생기지 않게 해요.","함께 점검하며 바른 언어생활의 필요성을 느껴요."],"asset":{"type":"passage","lines":["[점검표] 사용하는 말 — 외래어 · 줄임말 · 고유어","[표시] 하루에 네 번 이상 · 두세 번 · 한 번 이하","[조사 항목] 많이 사용하는 말 — 조사 결과"],"numbered":false,"title":"자신과 모둠원의 언어생활 점검 — 『국어』 206쪽 (1)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_c#16','kor',6,2,'u4','','tb_g6_2_kor_u4_review_c','unit_review','K6-2-u4-C15',2,'blank','auto','『국어』 209쪽 안내 “실천 다짐문에는 목적, 구체적인 실천 약속, (     )을/를 쓸 수 있어요.”의 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K6-2-u4-X21','K6-2-u4-X22','K6-2-u4-X25']::text[],false,'{"seq":16,"concept":"K6-2-u4-C15","difficulty":2,"kind":"blank","stem":"『국어』 209쪽 안내 “실천 다짐문에는 목적, 구체적인 실천 약속, (     )을/를 쓸 수 있어요.”의 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"전하고 싶은 말","correct":true},{"t":"친구의 잘못","mis":"K6-2-u4-X21"},{"t":"주장과 근거","mis":"K6-2-u4-X22"},{"t":"외국어 표어","mis":"K6-2-u4-X25"}],"explanation":["실천 다짐문의 내용은 목적, 구체적인 실천 약속, 전하고 싶은 말이에요.","마지막에 날짜와 쓴 사람을 써요.","이 형식에 맞추어 다짐문을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_c#17','kor',6,2,'u4','','tb_g6_2_kor_u4_review_c','unit_review','K6-2-u4-C12',3,'mc','auto','『국어』 196쪽 「생각하며 읽기」 “모르는 낱말이 있나요? 낱말의 뜻을 이해하려면 어떻게 해야 할까요?”에 대한 답으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u4-X18']::text[],false,'{"seq":17,"concept":"K6-2-u4-C12","difficulty":3,"kind":"mc","stem":"『국어』 196쪽 「생각하며 읽기」 “모르는 낱말이 있나요? 낱말의 뜻을 이해하려면 어떻게 해야 할까요?”에 대한 답으로 알맞은 것은 무엇인가요?","options":[{"t":"앞뒤 문맥에서 뜻을 짐작하고 낱말 풀이나 국어사전으로 확인한다","correct":true},{"t":"모르는 낱말은 건너뛰고 끝까지 빨리 읽는다","mis":"K6-2-u4-X18"},{"t":"글자 모양을 보고 떠오르는 뜻으로 정한다","mis":"K6-2-u4-X18"},{"t":"그 낱말이 나온 부분은 읽지 않는다","mis":"K6-2-u4-X18"}],"explanation":["모르는 낱말의 뜻은 앞뒤 문맥에서 짐작할 수 있어요.","쪽 아래의 낱말 풀이나 국어사전으로 확인해요.","그러면 글의 내용을 더 잘 파악할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_c#18','kor',6,2,'u4','','tb_g6_2_kor_u4_review_c','unit_review','K6-2-u4-C6',3,'mc','auto','학교에서 볼 수 있는 외래어를 고유어로 알맞게 고쳐 쓴 것은 무엇인가요?',ARRAY['K6-2-u4-X08']::text[],false,'{"seq":18,"concept":"K6-2-u4-C6","difficulty":3,"kind":"mc","stem":"학교에서 볼 수 있는 외래어를 고유어로 알맞게 고쳐 쓴 것은 무엇인가요?","options":[{"t":"스티커 → 붙임딱지","correct":true},{"t":"붙임딱지 → 스티커","mis":"K6-2-u4-X08"},{"t":"동아리 → 서클","mis":"K6-2-u4-X08"},{"t":"계주 → 릴레이","mis":"K6-2-u4-X08"}],"explanation":["외래어를 고유어로 고쳐야 해요.","‘스티커’를 ‘붙임딱지’로 고친 것이 알맞아요.","고유어를 외래어로 바꾸는 것은 거꾸로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_c#19','kor',6,2,'u4','','tb_g6_2_kor_u4_review_c','unit_review','K6-2-u4-C26',3,'mc','auto','주시경 선생님이 쓴 편지에서 글쓴이의 의도로 가장 알맞은 것은 무엇인가요?',ARRAY['K6-2-u4-X38']::text[],false,'{"seq":19,"concept":"K6-2-u4-C26","difficulty":3,"kind":"mc","stem":"주시경 선생님이 쓴 편지에서 글쓴이의 의도로 가장 알맞은 것은 무엇인가요?","options":[{"t":"어린이들이 한글을 소중한 보물로 여기고 아끼고 가꾸기를 바라서","correct":true},{"t":"자기 이름 ‘한힌샘’을 어린이들에게 자랑하려고","mis":"K6-2-u4-X38"},{"t":"어린이들에게 한자를 더 열심히 배우라고 권하려고","mis":"K6-2-u4-X38"},{"t":"편지의 내용을 짧게 간추려 정리해 주려고","mis":"K6-2-u4-X38"}],"explanation":["글쓴이의 생각이 드러난 문장을 찾아요.","“보물은 소중히 아끼고 가꿀수록 더욱 빛이 날 거예요.”라고 했어요.","어린이들이 한글을 아끼기를 바라는 마음이 담겨 있어요."],"asset":{"type":"passage","lines":["저는 주시경이라고 해요. 예전에는 ‘한힌샘’이라는 이름으로도 불렸어요.","(간추림) ‘한’은 하나뿐인 크고 위대한 나라, ‘힌샘’은 맑고 깨끗한 샘물처럼","(간추림) 지혜롭고 밝은 생각이 흘러나오는 곳을 뜻한다.","(간추림) 나라를 빼앗겼을 때 우리말 사전을 만들고 한글을 가르치는 데 온 마음을 다했다.","한글은 우리 겨레의 숨결이 담긴 소중한 보물이에요.","보물은 소중히 아끼고 가꿀수록 더욱 빛이 날 거예요.","[날짜와 쓴 사람] ○○○○년 10월 9일 · 우리말을 사랑하는 주시경 선생님이"],"numbered":false,"title":"주시경 선생님이 쓴 편지 — 글을 읽고 추론하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_c#20','kor',6,2,'u4','','tb_g6_2_kor_u4_review_c','unit_review','K6-2-u4-C24',3,'mc','auto','「야, 겨울 온다」를 소리 내어 읽은 뒤 시를 더 깊이 이해하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u4-X32','K6-2-u4-X02','K6-2-u4-X18']::text[],false,'{"seq":20,"concept":"K6-2-u4-C24","difficulty":3,"kind":"mc","stem":"「야, 겨울 온다」를 소리 내어 읽은 뒤 시를 더 깊이 이해하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"떠오른 장면을 나누며 고유어 표현의 분위기와 느낌을 이야기한다","correct":true},{"t":"고유어가 몇 개 나오는지 글자 수를 세어 본다","mis":"K6-2-u4-X32"},{"t":"고유어를 모두 한자어로 바꾸어 다시 읽어 본다","mis":"K6-2-u4-X02"},{"t":"뜻을 몰라도 빨리 읽고 다음 시로 넘어간다","mis":"K6-2-u4-X18"}],"explanation":["시를 읽고 떠오른 장면을 서로 나누어요.","방그레, 바삭바삭 같은 고유어가 주는 느낌을 이야기해요.","그러면 우리말의 아름다움을 더 깊이 느낄 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_c#21','kor',6,2,'u4','','tb_g6_2_kor_u4_review_c','unit_review','K6-2-u4-C16',3,'mc','auto','우리말 지킴이 활동으로 알맞은 것끼리 묶은 것은 무엇인가요?',ARRAY['K6-2-u4-X25','K6-2-u4-X21','K6-2-u4-X26']::text[],false,'{"seq":21,"concept":"K6-2-u4-C16","difficulty":3,"kind":"mc","stem":"우리말 지킴이 활동으로 알맞은 것끼리 묶은 것은 무엇인가요?","options":[{"t":"홍보물 만들기, 고유어를 몸짓으로 전달하기 놀이, 만화 그리기","correct":true},{"t":"외국어 노래 부르기, 줄임말 사전 만들기","mis":"K6-2-u4-X25"},{"t":"다른 반 말 감시하기, 벌점 주기","mis":"K6-2-u4-X21"},{"t":"하루 동안만 고유어 쓰기 행사","mis":"K6-2-u4-X26"}],"explanation":["『국어』 212쪽은 홍보물 만들기를 소개했어요.","고유어 몸짓 전달 놀이와 만화 그리기도 할 수 있어요.","모두 우리말의 소중함을 알리는 활동이에요."],"asset":{"type":"passage","lines":["(1) 만화로 표현하고 싶은 주제 정하기 — 예: 줄임말을 사용하지 말자.","(2) 주제에 맞게 내용이 자연스럽게 이어지도록 장면 1~4 정하기","(3) 아름다운 우리말의 소중함을 알릴 수 있는 만화 그리기"],"numbered":false,"title":"우리 반에서 정한 활동 예시 2 — 만화 그리기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_c#22','kor',6,2,'u4','','tb_g6_2_kor_u4_review_c','unit_review','K6-2-u4-C15',3,'mc','auto','완성한 실천 다짐문을 학급 온라인 게시판에 올리면 좋은 점은 무엇인가요?',ARRAY['K6-2-u4-X26','K6-2-u4-X24']::text[],false,'{"seq":22,"concept":"K6-2-u4-C15","difficulty":3,"kind":"mc","stem":"완성한 실천 다짐문을 학급 온라인 게시판에 올리면 좋은 점은 무엇인가요?","options":[{"t":"서로의 생각을 댓글로 공유할 수 있다","correct":true},{"t":"다짐을 실천하지 않아도 된다","mis":"K6-2-u4-X26"},{"t":"친구의 다짐문을 마음대로 고칠 수 있다","mis":"K6-2-u4-X24"},{"t":"다짐문을 쓴 날 하루만 지키면 된다","mis":"K6-2-u4-X26"}],"explanation":["학급 온라인 게시판에 글을 올리면 댓글로 생각을 나눌 수 있어요.","교실 발표회나 학급 알림판에 붙여 나눌 수도 있어요.","함께 나누면 다짐을 지키는 힘이 생겨요."],"asset":{"type":"speech","turns":[{"who":"안내 1","text":"“완성한 실천 다짐문은 교실에서 발표회를 하거나 학급 알림판에 붙여 친구들과 공유할 수 있어요.”"},{"who":"안내 2","text":"“학급 온라인 게시판에 게시하는 방법도 있어요. 학급 온라인 게시판에 글을 올리면 서로의 생각을 댓글로 공유할 수 있어요.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_c#23','kor',6,2,'u4','','tb_g6_2_kor_u4_review_c','unit_review','K6-2-u4-C5',4,'essay','teacher','학교에서 볼 수 있는 고유어 하나를 넣어 문장을 만들고, 그 고유어에서 느껴지는 고유어의 가치를 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K6-2-u4-C5","difficulty":4,"kind":"essay","stem":"학교에서 볼 수 있는 고유어 하나를 넣어 문장을 만들고, 그 고유어에서 느껴지는 고유어의 가치를 쓰세요.","answer_guide":{"answer":"예: 고유어 — 동아리 / 문장 — 나는 이번 학기에 그림 동아리에 들었다. / 가치 — 함께 어울리는 모임이라는 뜻을 쉽게 짐작할 수 있고 정겨운 느낌을 준다.","scoring_points":["고유어를 뜻에 맞게 넣어 문장을 만들었는가","고유어의 가치를 썼는가","생활 속에서 고유어를 쓰려는 마음이 드러나는가"]},"explanation":["학교에서 볼 수 있는 고유어로 문장을 만드는 셋째 활동이에요.","학교생활과 이어지는 문장을 만들어요.","고유어의 가치는 여러 가지예요."],"asset":{"type":"passage","lines":["1. 학교에서 볼 수 있는 낱말을 고유어, 한자어, 외래어로 분류해 봅시다.","2. 분류한 한자어나 외래어 가운데에서 고유어로 고칠 수 있는 낱말을 고쳐 써 봅시다.","[표] 한자어나 외래어 · 낱말의 뜻 · 고유어","3. 학교에서 볼 수 있는 고유어 가운데 하나를 넣어 문장을 만들어 봅시다."],"numbered":false,"title":"학교에서 볼 수 있는 낱말을 분류하고 고유어로 고쳐 쓰기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_c#24','kor',6,2,'u4','','tb_g6_2_kor_u4_review_c','unit_review','K6-2-u4-C12',4,'essay','teacher','「큰사전이 필요하다」에서 『큰사전』의 원고를 빼앗겼을 때 조선어학회 회원들의 마음은 어땠을지 추론하고, 그렇게 생각한 근거를 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u4-C12","difficulty":4,"kind":"essay","stem":"「큰사전이 필요하다」에서 『큰사전』의 원고를 빼앗겼을 때 조선어학회 회원들의 마음은 어땠을지 추론하고, 그렇게 생각한 근거를 쓰세요.","answer_guide":{"answer":"예: 오랫동안 애써 만든 원고를 빼앗겨 몹시 절망스럽고 분했을 것이다. 글에서 원고 압수를 회원들이 고문을 받은 것보다 더 큰 비극이라고 했고, 다시 시작하면 언제 끝날지 모를 작업이라고 했기 때문이다.","scoring_points":["회원들의 마음을 추론했는가","글의 단서를 근거로 들었는가","추론한 마음과 근거가 이어지는가"]},"explanation":["원고를 만드는 데 들인 시간과 노력을 떠올려요.","글에서 그 일을 어떻게 표현했는지 찾아요.","근거가 있는 추론은 상상과 달라요."],"asset":{"type":"passage","lines":["(간추림) 1942년 함흥에서 기차 안에서 우리말을 쓴 학생들이 일본 경찰에 붙잡혔다.","(간추림) 학생의 일기장을 단서로 교사 정태진이 조선어학회 회원임이 밝혀졌다.","(간추림) 일제는 이를 빌미로 조선어학회를 탄압하고 『큰사전』 원고를 모두 압수했다.","(간추림) 1945년 광복 뒤 회원들은 원고를 찾아 전국을 뒤졌지만 찾지 못했다.","“『큰사전』의 원고를 찾아야 합니다!”"],"title":"「큰사전이 필요하다」 빼앗긴 원고 — 『국어』 199쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_c#25','kor',6,2,'u4','','tb_g6_2_kor_u4_review_c','unit_review','K6-2-u4-C2',4,'essay','teacher','『국어』 215쪽 3번처럼 이 단원을 마치며 우리말을 바르게 사용하는 태도에 대해 생각이 어떻게 바뀌었는지 쓰고, 앞으로 실천할 일을 한 가지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u4-C2","difficulty":4,"kind":"essay","stem":"『국어』 215쪽 3번처럼 이 단원을 마치며 우리말을 바르게 사용하는 태도에 대해 생각이 어떻게 바뀌었는지 쓰고, 앞으로 실천할 일을 한 가지 쓰세요.","answer_guide":{"answer":"예: 전에는 외국어를 쓰는 게 멋져 보였는데, 고유어를 쓰니 말의 느낌이 더 생생하고 정겹다는 것을 알게 되었다. 앞으로 친구와 대화할 때 줄임말 대신 바른 우리말을 쓰겠다.","scoring_points":["바뀐 생각을 썼는가","실천할 일을 구체적으로 썼는가","우리말을 소중히 여기는 마음이 드러나는가"]},"explanation":["친구들이 나눈 이야기를 떠올려요.","단원을 공부하며 달라진 생각을 솔직하게 써요.","실천할 일은 구체적으로 써요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"“외국어를 쓰는 게 멋져 보여서 많이 사용했는데 고유어를 많이 사용하도록 노력해야겠어.”"},{"who":"친구 2","text":"“우리말의 아름다움을 친구들에게 알릴 수 있도록 나부터 우리말을 바르게 사용해야겠어.”"},{"who":"친구 3","text":"“고유어를 사용하니 시의 느낌이 더 생생하게 느껴졌어. 앞으로 우리말을 소중하게 생각하고 사용해야겠어.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_d#1','kor',6,2,'u4','','tb_g6_2_kor_u4_review_d','unit_review','K6-2-u4-C1',1,'mc','auto','이 단원에서 배운 ‘외래어’의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K6-2-u4-X01','K6-2-u4-X07']::text[],false,'{"seq":1,"concept":"K6-2-u4-C1","difficulty":1,"kind":"mc","stem":"이 단원에서 배운 ‘외래어’의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"외국에서 들어와 우리 생활에서 널리 쓰이는 낱말","correct":true},{"t":"한자로 이루어져 사전에 한자가 함께 있는 낱말","mis":"K6-2-u4-X01"},{"t":"우리말에 처음부터 있던 낱말이나 그것으로 만든 낱말","mis":"K6-2-u4-X01"},{"t":"잘못 써서 고쳐야 하는 틀린 낱말","mis":"K6-2-u4-X07"}],"explanation":["외래어는 외국에서 들어와 우리 생활에서 널리 쓰이는 낱말이에요.","국어사전에서 찾으면 영어 같은 외국어가 같이 있어요.","‘피자’, ‘벤치’가 외래어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_d#2','kor',6,2,'u4','','tb_g6_2_kor_u4_review_d','unit_review','K6-2-u4-C3',1,'mc','auto','『국어』 181쪽 2번의 ‘점메추’ 같은 줄임말을 쓸 때 생길 수 있는 문제는 무엇인가요?',ARRAY['K6-2-u4-X03','K6-2-u4-X01','K6-2-u4-X04']::text[],false,'{"seq":2,"concept":"K6-2-u4-C3","difficulty":1,"kind":"mc","stem":"『국어』 181쪽 2번의 ‘점메추’ 같은 줄임말을 쓸 때 생길 수 있는 문제는 무엇인가요?","options":[{"t":"아는 사람끼리만 통해 듣는 사람이 알아듣지 못할 수 있다","correct":true},{"t":"짧아서 누구나 더 잘 알아듣고 빨리 통한다","mis":"K6-2-u4-X03"},{"t":"줄임말은 모두 고유어라서 괜찮다","mis":"K6-2-u4-X01"},{"t":"뜻만 통하면 아무 문제가 없다","mis":"K6-2-u4-X04"}],"explanation":["친구 1은 ‘점메추’를 알아듣지 못한 적이 있다고 했어요.","지나치게 줄인 말은 모르는 사람에게 통하지 않아요.","그래서 줄임말을 줄이자고 했어요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"“나는 친구가 ‘점메추’라는 줄임말을 써서 알아듣지 못한 적이 있어.”"},{"who":"친구 2","text":"“친구들이 비속어를 쓰면 대화할 때 불쾌하고 기분이 좋지 않아.”"},{"who":"친구 3","text":"“줄임말과 비속어를 줄이고 우리말을 바르게 사용하는 습관을 길러야 해.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_d#3','kor',6,2,'u4','','tb_g6_2_kor_u4_review_d','unit_review','K6-2-u4-C18',1,'mc','auto','「조각하늘」에서 하늘이 자기 얼굴을 비추어 본 곳은 어디인가요?',ARRAY['K6-2-u4-X29']::text[],false,'{"seq":3,"concept":"K6-2-u4-C18","difficulty":1,"kind":"mc","stem":"「조각하늘」에서 하늘이 자기 얼굴을 비추어 본 곳은 어디인가요?","options":[{"t":"호수","correct":true},{"t":"거울","mis":"K6-2-u4-X29"},{"t":"창문","mis":"K6-2-u4-X29"},{"t":"웅덩이","mis":"K6-2-u4-X29"}],"explanation":["시의 둘째 연을 다시 읽어요.","호수에 비친 자기 얼굴만 빠끔히 내다본다고 했어요.","그러고는 구름 뒤로 숨어요."],"asset":{"type":"passage","lines":["하늘이 숨바꼭질하고 싶은가 봐요.","구름 뒤에 숨어서 나올 생각을 안 해요.","호수에 비친 자기 얼굴만","빠끔히 내다보고","구름 뒤로 쏘옥 숨어요.","(간추림) 바람이 호수를 간지럽혀도 조각하늘은 구름 뒤에서 좀처럼 나오지 않는다."],"title":"「조각하늘」(권지영 글) — 『국어』 180쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_d#4','kor',6,2,'u4','','tb_g6_2_kor_u4_review_d','unit_review','K6-2-u4-C6',1,'mc','auto','국립국어원 ‘다듬은 말’ 자료에서 ‘인터체인지’를 다듬은 말은 무엇인가요?',ARRAY['K6-2-u4-X08']::text[],false,'{"seq":4,"concept":"K6-2-u4-C6","difficulty":1,"kind":"mc","stem":"국립국어원 ‘다듬은 말’ 자료에서 ‘인터체인지’를 다듬은 말은 무엇인가요?","options":[{"t":"나들목","correct":true},{"t":"교차점","mis":"K6-2-u4-X08"},{"t":"인터길","mis":"K6-2-u4-X08"},{"t":"큰길","mis":"K6-2-u4-X08"}],"explanation":["‘인터체인지’는 ‘나들목’으로 다듬었어요.","‘섬네일’은 ‘마중그림’, ‘스토리보드’는 ‘줄거리판’으로 다듬었어요.","고유어를 살리면 말이 정겹고 뜻을 짐작하기 쉬워요."],"asset":{"type":"passage","lines":["가십 → 소문","네티즌 → 누리꾼","더치페이 → 각자 내기","디엠 → 쪽지","섬네일 → 마중그림","스토리보드 → 줄거리판","신참자 → 새내기","인터체인지 → 나들목"],"title":"다듬은 말 더 보기(국립국어원 ‘다듬은 말’ 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_d#5','kor',6,2,'u4','','tb_g6_2_kor_u4_review_d','unit_review','K6-2-u4-C7',1,'mc','auto','「고유어의 가치」에서 “어떤 물건이 매우 빠르게 팔려 나가다.”라는 뜻으로 든 관용 표현은 무엇인가요?',ARRAY['K6-2-u4-X09']::text[],false,'{"seq":5,"concept":"K6-2-u4-C7","difficulty":1,"kind":"mc","stem":"「고유어의 가치」에서 “어떤 물건이 매우 빠르게 팔려 나가다.”라는 뜻으로 든 관용 표현은 무엇인가요?","options":[{"t":"날개 돋치다","correct":true},{"t":"눈도 깜짝 안 하다","mis":"K6-2-u4-X09"},{"t":"새우잠을 자다","mis":"K6-2-u4-X09"}],"explanation":["글에서 “날개 돋치다.”를 이 뜻으로 소개했어요.","“눈도 깜짝 안 하다.”는 조금도 놀라지 않고 태연하다는 뜻이에요.","두 표현 모두 고유어로 이루어진 관용 표현이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_d#6','kor',6,2,'u4','','tb_g6_2_kor_u4_review_d','unit_review','K6-2-u4-C21',1,'mc','auto','「큰사전이 필요하다」에서 1938년 일본이 한글 사용을 금지하며 발표한 것은 무엇인가요?',ARRAY['K6-2-u4-X30','K6-2-u4-X33']::text[],false,'{"seq":6,"concept":"K6-2-u4-C21","difficulty":1,"kind":"mc","stem":"「큰사전이 필요하다」에서 1938년 일본이 한글 사용을 금지하며 발표한 것은 무엇인가요?","options":[{"t":"일본어 상용화","correct":true},{"t":"문맹 퇴치 운동","mis":"K6-2-u4-X30"},{"t":"시골말 캐기","mis":"K6-2-u4-X33"},{"t":"한일 합병 조약","mis":"K6-2-u4-X30"}],"explanation":["1938년 일본은 일본어 상용화를 발표했어요.","그러면서 한글 사용을 금지했어요.","조선어학회는 일본에게 눈엣가시와 같은 존재가 되었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_d#7','kor',6,2,'u4','','tb_g6_2_kor_u4_review_d','unit_review','K6-2-u4-C13',1,'ox','auto','방언도 우리말을 지키기 위해 소중히 여겨야 할 우리말이에요.',ARRAY['K6-2-u4-X19']::text[],false,'{"seq":7,"concept":"K6-2-u4-C13","difficulty":1,"kind":"ox","stem":"방언도 우리말을 지키기 위해 소중히 여겨야 할 우리말이에요.","answer":"O","reason_options":[{"t":"학자들은 각 지역의 개성이 담긴 방언도 우리 민족의 소중한 보물이라고 생각했어요.","correct":true},{"t":"방언은 고쳐야 할 틀린 말이라서 모으지 않아요.","mis":"K6-2-u4-X19"}],"mis":"K6-2-u4-X19","explanation":["시골말 캐기로 모인 방언은 『큰사전』의 뿌리가 되었어요.","방언에는 지역의 특성이 담겨 있어요.","우리말을 지키는 일에는 방언을 이해하는 자세도 들어가요."],"asset":{"type":"passage","lines":["(간추림) 사전을 만들려고 전국의 우리말을 모으던 시절, 학자들은 ‘시골말 캐기’를 펼쳤다.","(간추림) 구멍 대신 구먹·구명·구녕·구무, 부추 대신 세우리·정구지 같은 말을 모았다.","(간추림) 방학을 맞은 전국의 학생들이 고향에서 실제 쓰는 말을 종이에 써 보냈다.","(간추림) 학자들은 각 지역의 개성이 담긴 방언도 우리 민족의 소중한 보물이라고 생각했다.","(간추림) 모인 수많은 말은 『큰사전』을 만드는 든든한 뿌리가 되었다."],"title":"「우리말의 보물을 찾아서, ‘시골말 캐기’」 — 『국어』 204쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_d#8','kor',6,2,'u4','','tb_g6_2_kor_u4_review_d','unit_review','K6-2-u4-C25',1,'sa','auto','“물질이 공기 중의 산소와 빠르게 반응해 열과 빛을 내며 타는 현상.”을 뜻하는 낱말을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K6-2-u4-C25","difficulty":1,"kind":"sa","stem":"“물질이 공기 중의 산소와 빠르게 반응해 열과 빛을 내며 타는 현상.”을 뜻하는 낱말을 쓰세요.","answer":["연소"],"explanation":["물질이 열과 빛을 내며 타는 현상은 연소예요.","“초가 연소하면 길이가 짧아진다.”처럼 써요.","과학 공부에서 자주 나오는 낱말이에요."],"mis":"K6-2-u4-X35"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_d#9','kor',6,2,'u4','','tb_g6_2_kor_u4_review_d','unit_review','K6-2-u4-C19',2,'match','auto','「세린이의 즐거운 하루」에 나온 낱말과 그 갈래를 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u4-C19","difficulty":2,"kind":"match","stem":"「세린이의 즐거운 하루」에 나온 낱말과 그 갈래를 알맞게 이으세요.","pairs":[{"l":"벌개미취","r":"고유어"},{"l":"수업","r":"한자어"},{"l":"피자","r":"외래어"}],"mis":"K6-2-u4-X01","explanation":["사전에서 ‘벌개미취’는 한글 표기만 있어요.","‘수업’은 한자가 함께 있어요.","‘피자’는 외국어가 함께 있어요."],"asset":{"type":"passage","lines":["수업 · 피자 · 친구 · 둘레 · 모둠 · 줄넘기 · 벌개미취"],"title":"『국어』 183쪽 2번 (2) — 사전에서 찾아볼 낱말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_d#10','kor',6,2,'u4','','tb_g6_2_kor_u4_review_d','unit_review','K6-2-u4-C20',2,'blank','auto','「고유어의 가치」의 끝부분이에요. “한자어와 외래어를 대신할 수 있는 고유어를 찾아보는 활동 과정에서 우리말을 남달리 여기고 (     ) 마음을 기를 수 있을 것이다.” 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K6-2-u4-X02','K6-2-u4-X03']::text[],false,'{"seq":10,"concept":"K6-2-u4-C20","difficulty":2,"kind":"blank","stem":"「고유어의 가치」의 끝부분이에요. “한자어와 외래어를 대신할 수 있는 고유어를 찾아보는 활동 과정에서 우리말을 남달리 여기고 (     ) 마음을 기를 수 있을 것이다.” 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"사랑하는","correct":true},{"t":"버리는","mis":"K6-2-u4-X02"},{"t":"어렵게 여기는","mis":"K6-2-u4-X03"},{"t":"외국어를 좋아하는","mis":"K6-2-u4-X03"}],"explanation":["글쓴이는 고유어가 우리말의 기본 바탕이라고 했어요.","그래서 대신할 고유어를 찾아보자고 했어요.","이 활동으로 우리말을 사랑하는 마음을 기를 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_d#11','kor',6,2,'u4','','tb_g6_2_kor_u4_review_d','unit_review','K6-2-u4-C8',2,'mc','auto','『국어』 189쪽 (4) 예시 답안에서 ‘두레길’의 ‘두레’의 뜻은 무엇인가요?',ARRAY['K6-2-u4-X10']::text[],false,'{"seq":11,"concept":"K6-2-u4-C8","difficulty":2,"kind":"mc","stem":"『국어』 189쪽 (4) 예시 답안에서 ‘두레길’의 ‘두레’의 뜻은 무엇인가요?","options":[{"t":"둥근 켜로 된 시루떡 덩어리 모양","correct":true},{"t":"두 팔을 둥글게 모아서 만든 둘레","mis":"K6-2-u4-X10"},{"t":"옛 우리말에서 큰 밭","mis":"K6-2-u4-X10"},{"t":"사람이나 차가 지나가는 땅","mis":"K6-2-u4-X10"}],"explanation":["‘두레’는 둥근 켜로 된 시루떡 덩어리 모양이에요.","‘길’은 사람이나 동물, 자동차가 지나가게 땅 위에 낸 공간이에요.","두 낱말을 나누어 각각 뜻을 찾았어요."],"asset":{"type":"passage","lines":["[표] 유형 · 사례 · 고유어 · 고유어의 뜻","동네 이름 · 아름동 · 아름 · 두 팔을 둥글게 모아서 만든 둘레.","음식 · 비빔밥 · 비빔, 밥 · 고기나 나물 따위와 여러 가지 양념을 넣어 비벼 먹는 밥.","도로 · 두레길 · 두레, 길 · 두레: 둥근 켜로 된 시루떡 덩어리 모양."],"numbered":false,"title":"조사한 자료 정리 — 『국어』 189쪽 (4)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_d#12','kor',6,2,'u4','','tb_g6_2_kor_u4_review_d','unit_review','K6-2-u4-C10',2,'error','auto','친구들의 발표를 들을 때의 태도예요. 알맞지 않은 것은 무엇인가요?',ARRAY['K6-2-u4-X14']::text[],false,'{"seq":12,"concept":"K6-2-u4-C10","difficulty":2,"kind":"error","stem":"친구들의 발표를 들을 때의 태도예요. 알맞지 않은 것은 무엇인가요?","options":[{"t":"㉰ “친구가 발표하는 동안 내 발표 준비만 하고 친구 발표는 듣지 않을래.”","correct":true,"mis_target":"K6-2-u4-X14"},{"t":"㉮ “친구가 발표한 고유어와 뜻을 표에 정리하며 들을래.”","mis":"K6-2-u4-X14"},{"t":"㉯ “궁금한 점은 발표가 끝난 뒤에 질문할래.”","mis":"K6-2-u4-X14"}],"explanation":["발표를 들을 때는 내용에 주의를 집중해요.","새롭게 안 고유어와 뜻을 정리하며 들어요.","궁금한 점은 발표가 끝난 뒤 질문해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_d#13','kor',6,2,'u4','','tb_g6_2_kor_u4_review_d','unit_review','K6-2-u4-C22',2,'mc','auto','「큰사전이 필요하다」에서 사전은 1957년 6권을 끝으로 완간되었어요. ‘완간되다’의 뜻은 무엇인가요?',ARRAY['K6-2-u4-X31']::text[],false,'{"seq":13,"concept":"K6-2-u4-C22","difficulty":2,"kind":"mc","stem":"「큰사전이 필요하다」에서 사전은 1957년 6권을 끝으로 완간되었어요. ‘완간되다’의 뜻은 무엇인가요?","options":[{"t":"총서나 전집 따위가 빠진 것 없이 모두 발간되다","correct":true},{"t":"책의 원고를 처음 쓰기 시작하다","mis":"K6-2-u4-X31"},{"t":"책이 모두 팔려서 사라지다","mis":"K6-2-u4-X31"},{"t":"전집 가운데 책을 한 권만 내다","mis":"K6-2-u4-X31"}],"explanation":["완간되다는 빠진 것 없이 모두 발간되었다는 뜻이에요.","1947년 1권이 나오고 1957년 6권으로 끝났어요.","오랜 노력 끝에 우리글 사전이 완성되었어요."],"asset":{"type":"passage","lines":["[낱말] 집대성하다 — 여러 가지를 모아 하나의 체계를 이루어 완성하다.","[낱말] 손색없다 — 다른 것과 견주어 부족함이 없다.","[낱말] 상흔 — 상처를 입은 자리에 남은 흔적.","[낱말] 완간되다 — 총서나 전집 따위가 빠진 것 없이 모두 발간되다."],"numbered":false,"title":"「큰사전이 필요하다」 낱말 풀이 — 『국어』 195~200쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_d#14','kor',6,2,'u4','','tb_g6_2_kor_u4_review_d','unit_review','K6-2-u4-C21',2,'mc','auto','「큰사전이 필요하다」의 다음 일 가운데 가장 나중에 일어난 일은 무엇인가요?',ARRAY['K6-2-u4-X30']::text[],false,'{"seq":14,"concept":"K6-2-u4-C21","difficulty":2,"kind":"mc","stem":"「큰사전이 필요하다」의 다음 일 가운데 가장 나중에 일어난 일은 무엇인가요?","options":[{"t":"『조선말 큰사전』이 6권으로 완간되었다","correct":true},{"t":"서울역 창고에서 『큰사전』 원고를 찾았다","mis":"K6-2-u4-X30"},{"t":"조선어학회가 문맹 퇴치 운동을 했다","mis":"K6-2-u4-X30"},{"t":"주시경이 생을 마쳤다","mis":"K6-2-u4-X30"}],"explanation":["1945년 원고를 찾은 뒤 사전 출간이 시작되었어요.","1947년 1권이 나오고 1957년 6권으로 완간되었어요.","한국 전쟁 중에도 사전 편찬은 이어졌어요."],"asset":{"type":"passage","lines":["(간추림) 1945년 9월 8일 서울역 창고에서 역장이 커다란 상자를 열었다.","(간추림) 그 안에서 잃어버렸던 『큰사전』 원고 수만 장이 모습을 드러냈다.","(간추림) 1947년 『조선말 큰사전』 1권이 나왔고, 1957년 6권으로 완간되었다.","(간추림) 조선어학회의 값진 노력으로 우리나라는 우리글 사전을 가지게 되었다."],"title":"「큰사전이 필요하다」 다시 찾은 원고 — 『국어』 200쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_d#15','kor',6,2,'u4','','tb_g6_2_kor_u4_review_d','unit_review','K6-2-u4-C14',2,'mc','auto','언어 사용 실태를 다룬 뉴스에서 우리말이 잘못 쓰이는 대표 유형으로 든 것은 무엇인가요?',ARRAY['K6-2-u4-X02','K6-2-u4-X19','K6-2-u4-X03']::text[],false,'{"seq":15,"concept":"K6-2-u4-C14","difficulty":2,"kind":"mc","stem":"언어 사용 실태를 다룬 뉴스에서 우리말이 잘못 쓰이는 대표 유형으로 든 것은 무엇인가요?","options":[{"t":"무분별한 외국어 사용","correct":true},{"t":"고유어를 너무 많이 쓰는 것","mis":"K6-2-u4-X02"},{"t":"방언을 쓰는 것","mis":"K6-2-u4-X19"},{"t":"문장을 짧게 쓰는 것","mis":"K6-2-u4-X03"}],"explanation":["뉴스는 공공 언어에 어려운 외국어가 많다고 했어요.","우리말이 있는데도 굳이 갖다 쓴 외국어가 대표 유형이었어요.","공공 언어는 누구나 쉽게 이해할 수 있어야 해요."],"asset":{"type":"passage","lines":["(간추림) 정부 기관이 쓰는 공공 언어는 국민 누구나 쉽게 이해할 수 있어야 한다.","(간추림) 그러나 쉬운 우리말을 놔두고 어려운 외국어 표현을 남발하는 경우가 많다.","(간추림) ‘페이백’, ‘플랫폼’, ‘프랙탈’처럼 우리말이 있는데도 굳이 갖다 쓴 외국어가 많다.","(간추림) 우리말이 잘못 쓰이는 대표 유형은 무분별한 외국어 사용이었다."],"title":"언어 사용 실태를 다룬 뉴스(간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_d#16','kor',6,2,'u4','','tb_g6_2_kor_u4_review_d','unit_review','K6-2-u4-C15',2,'blank','auto','다짐문 예시 “하나, 나는 뜻을 알기 어려운 말이나 지나친 줄임말보다는 (     )을/를 사용하려고 노력하겠습니다.”의 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K6-2-u4-X03','K6-2-u4-X04']::text[],false,'{"seq":16,"concept":"K6-2-u4-C15","difficulty":2,"kind":"blank","stem":"다짐문 예시 “하나, 나는 뜻을 알기 어려운 말이나 지나친 줄임말보다는 (     )을/를 사용하려고 노력하겠습니다.”의 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"표준어","correct":true},{"t":"외국어","mis":"K6-2-u4-X03"},{"t":"비속어","mis":"K6-2-u4-X04"},{"t":"새로 만든 줄임말","mis":"K6-2-u4-X03"}],"explanation":["뜻을 알기 어려운 말이나 줄임말은 서로 통하기 어려워요.","모두가 공통으로 쓰도록 정한 표준어를 쓰겠다는 다짐이에요.","구체적인 실천 약속의 한 가지예요."],"asset":{"type":"passage","lines":["우리말 지킴이 실천 다짐문","나는 아름답고 소중한 우리말을 지키고 바르게 사용하고자 다음과 같이 다짐합니다.","하나, 나는 일상생활에서 불필요한 외래어 사용을 줄이고, 고유어를 적극적으로 찾아 사용하겠습니다.","하나, 나는 뜻을 알기 어려운 말이나 지나친 줄임말보다는 표준어를 사용하려고 노력하겠습니다.","하나, 나는 비속어나 욕설을 사용하지 않고, 긍정적이고 예쁜 말을 사용해 상대를 존중하겠습니다.","소중한 우리말을 바르게 사용하려고 열심히 노력할 것을 약속합니다.","20○○년 ○○월 ○○일 · ○○○"],"numbered":false,"title":"실천 다짐문 예시 — 『국어』 209쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_d#17','kor',6,2,'u4','','tb_g6_2_kor_u4_review_d','unit_review','K6-2-u4-C12',3,'error','auto','광복 뒤 『큰사전』 원고를 찾아다닌 회원들의 마음을 추론했어요. 알맞지 않게 추론한 것은 무엇인가요?',ARRAY['K6-2-u4-X16','K6-2-u4-X17','K6-2-u4-X36']::text[],false,'{"seq":17,"concept":"K6-2-u4-C12","difficulty":3,"kind":"error","stem":"광복 뒤 『큰사전』 원고를 찾아다닌 회원들의 마음을 추론했어요. 알맞지 않게 추론한 것은 무엇인가요?","options":[{"t":"㉰ “원고를 팔아 부자가 되려고 찾았을 거야. 그냥 그럴 것 같아.”","correct":true,"mis_target":"K6-2-u4-X16"},{"t":"㉮ “시간이 흐를수록 불안이 싹텄다는 부분을 보니 원고를 꼭 찾고 싶었을 거야.”","mis":"K6-2-u4-X17"},{"t":"㉯ “다시 시작하면 언제 끝날지 모를 작업이라는 말을 보니 원고가 아주 소중했을 거야.”","mis":"K6-2-u4-X36"}],"explanation":["추론에는 글에서 찾은 근거가 있어야 해요.","㉮와 ㉯는 글의 단서를 근거로 들었어요.","㉰는 글에 단서가 없는 마음대로 한 상상이에요."],"asset":{"type":"passage","lines":["(간추림) 1942년 함흥에서 기차 안에서 우리말을 쓴 학생들이 일본 경찰에 붙잡혔다.","(간추림) 학생의 일기장을 단서로 교사 정태진이 조선어학회 회원임이 밝혀졌다.","(간추림) 일제는 이를 빌미로 조선어학회를 탄압하고 『큰사전』 원고를 모두 압수했다.","(간추림) 1945년 광복 뒤 회원들은 원고를 찾아 전국을 뒤졌지만 찾지 못했다.","“『큰사전』의 원고를 찾아야 합니다!”"],"title":"「큰사전이 필요하다」 빼앗긴 원고 — 『국어』 199쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_d#18','kor',6,2,'u4','','tb_g6_2_kor_u4_review_d','unit_review','K6-2-u4-C1',3,'match','auto','낱말의 세 갈래와 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":18,"concept":"K6-2-u4-C1","difficulty":3,"kind":"match","stem":"낱말의 세 갈래와 그 뜻을 알맞게 이으세요.","pairs":[{"l":"고유어","r":"우리말에 처음부터 있던 낱말이나 그것을 바탕으로 만들어진 낱말"},{"l":"한자어","r":"한자로 이루어진 낱말"},{"l":"외래어","r":"외국에서 들어와 우리 생활에서 널리 쓰이는 낱말"}],"mis":"K6-2-u4-X01","explanation":["낱말을 분류하려면 각 갈래의 뜻도 알고 있어야 해요.","고유어, 한자어, 외래어의 뜻을 바르게 알아야 분류할 수 있어요.","헷갈리면 국어사전으로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_d#19','kor',6,2,'u4','','tb_g6_2_kor_u4_review_d','unit_review','K6-2-u4-C26',3,'ox','auto','편지의 “보물은 소중히 아끼고 가꿀수록 더욱 빛이 날 거예요.”는 한글을 보물에 빗대어 한글을 아끼고 가꾸기를 바라는 마음을 담은 말이에요.',ARRAY['K6-2-u4-X38']::text[],false,'{"seq":19,"concept":"K6-2-u4-C26","difficulty":3,"kind":"ox","stem":"편지의 “보물은 소중히 아끼고 가꿀수록 더욱 빛이 날 거예요.”는 한글을 보물에 빗대어 한글을 아끼고 가꾸기를 바라는 마음을 담은 말이에요.","answer":"O","reason_options":[{"t":"앞 문장에서 한글을 소중한 보물이라고 했어요.","correct":true},{"t":"실제 보물 상자를 찾으라는 뜻이에요.","mis":"K6-2-u4-X38"}],"mis":"K6-2-u4-X38","explanation":["앞 문장에서 한글을 겨레의 숨결이 담긴 보물이라고 했어요.","그러니 보물은 한글을 빗댄 말이에요.","한글을 아끼고 가꾸자는 글쓴이의 의도가 드러나요."],"asset":{"type":"passage","lines":["저는 주시경이라고 해요. 예전에는 ‘한힌샘’이라는 이름으로도 불렸어요.","(간추림) ‘한’은 하나뿐인 크고 위대한 나라, ‘힌샘’은 맑고 깨끗한 샘물처럼","(간추림) 지혜롭고 밝은 생각이 흘러나오는 곳을 뜻한다.","(간추림) 나라를 빼앗겼을 때 우리말 사전을 만들고 한글을 가르치는 데 온 마음을 다했다.","한글은 우리 겨레의 숨결이 담긴 소중한 보물이에요.","보물은 소중히 아끼고 가꿀수록 더욱 빛이 날 거예요.","[날짜와 쓴 사람] ○○○○년 10월 9일 · 우리말을 사랑하는 주시경 선생님이"],"numbered":false,"title":"주시경 선생님이 쓴 편지 — 글을 읽고 추론하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_d#20','kor',6,2,'u4','','tb_g6_2_kor_u4_review_d','unit_review','K6-2-u4-C24',3,'match','auto','『국어』 215쪽 2번이에요. 「야, 겨울 온다」의 고유어와 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":20,"concept":"K6-2-u4-C24","difficulty":3,"kind":"match","stem":"『국어』 215쪽 2번이에요. 「야, 겨울 온다」의 고유어와 뜻을 알맞게 이으세요.","pairs":[{"l":"방그레","r":"입만 예쁘게 조금 벌리고 소리 없이 보드랍게 웃는 모양"},{"l":"길섶","r":"길의 가장자리"},{"l":"따습다","r":"알맞게 따뜻하다"}],"mis":"K6-2-u4-X34","explanation":["방그레는 소리 없이 보드랍게 웃는 모양이에요.","길섶은 길의 가장자리예요.","따습다는 알맞게 따뜻하다는 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_d#21','kor',6,2,'u4','','tb_g6_2_kor_u4_review_d','unit_review','K6-2-u4-C16',3,'error','auto','우리말 지킴이 활동 계획이에요. 알맞지 않은 것은 무엇인가요?',ARRAY['K6-2-u4-X26','K6-2-u4-X27']::text[],false,'{"seq":21,"concept":"K6-2-u4-C16","difficulty":3,"kind":"error","stem":"우리말 지킴이 활동 계획이에요. 알맞지 않은 것은 무엇인가요?","options":[{"t":"㉰ “홍보물을 한 번 붙이면 우리말 지킴이 활동은 다 끝난 거야.”","correct":true,"mis_target":"K6-2-u4-X26"},{"t":"㉮ “만화로 ‘줄임말을 사용하지 말자.’라는 주제를 장면 네 개로 나타내자.”","mis":"K6-2-u4-X27"},{"t":"㉯ “우리말 일기 쓰기처럼 꾸준히 하는 활동도 함께 하자.”","mis":"K6-2-u4-X26"}],"explanation":["우리말 지킴이 활동은 한 번으로 끝나지 않아요.","꾸준히 실천하며 바른 우리말 사용을 몸에 익혀요.","㉮, ㉯는 알맞은 계획이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_d#22','kor',6,2,'u4','','tb_g6_2_kor_u4_review_d','unit_review','K6-2-u4-C14',3,'mc','auto','『국어』 211쪽 ‘점검하기’처럼 다짐문을 실천한 뒤 스스로 쓰는 것은 무엇인가요?',ARRAY['K6-2-u4-X21','K6-2-u4-X24','K6-2-u4-X26']::text[],false,'{"seq":22,"concept":"K6-2-u4-C14","difficulty":3,"kind":"mc","stem":"『국어』 211쪽 ‘점검하기’처럼 다짐문을 실천한 뒤 스스로 쓰는 것은 무엇인가요?","options":[{"t":"실천한 뒤 내 언어생활에서 변화한 점과 노력할 점","correct":true},{"t":"친구가 변화한 점과 친구의 잘못만","mis":"K6-2-u4-X21"},{"t":"다짐문의 글자 수와 줄 수","mis":"K6-2-u4-X24"},{"t":"다짐문을 쓴 날 하루 동안 지킨 일만","mis":"K6-2-u4-X26"}],"explanation":["점검하기는 자기 평가예요.","변화한 점과 노력할 점을 스스로 써요.","나의 언어생활을 되돌아보며 성찰해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_d#23','kor',6,2,'u4','','tb_g6_2_kor_u4_review_d','unit_review','K6-2-u4-C7',4,'essay','teacher','“눈도 깜짝 안 하다.”와 “날개 돋치다.” 가운데 하나를 골라 학교생활 장면에 맞게 넣은 대화를 만들고, 관용 표현을 쓰면 좋은 점을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K6-2-u4-C7","difficulty":4,"kind":"essay","stem":"“눈도 깜짝 안 하다.”와 “날개 돋치다.” 가운데 하나를 골라 학교생활 장면에 맞게 넣은 대화를 만들고, 관용 표현을 쓰면 좋은 점을 쓰세요.","answer_guide":{"answer":"예: 가 — “알뜰 장터에서 우리 모둠 물건은 어땠어?” 나 — “날개 돋친 듯이 팔려서 금방 다 팔았어.” 좋은 점 — 짧은 말로 물건이 빨리 팔린 모습을 생생하게 전할 수 있다.","scoring_points":["관용 표현을 뜻에 맞게 넣었는가","학교생활 장면이 드러나는가","관용 표현을 쓰면 좋은 점을 썼는가"]},"explanation":["관용 표현의 뜻을 먼저 떠올려요.","그 뜻이 어울리는 장면을 정해요.","우리 고유의 문화와 정서가 담긴 표현이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_d#24','kor',6,2,'u4','','tb_g6_2_kor_u4_review_d','unit_review','K6-2-u4-C21',4,'essay','teacher','「큰사전이 필요하다」에서 ‘말모이’라는 이름에 담긴 뜻을 쓰고, 이 이름을 지은 사람들의 마음을 추론해 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u4-C21","difficulty":4,"kind":"essay","stem":"「큰사전이 필요하다」에서 ‘말모이’라는 이름에 담긴 뜻을 쓰고, 이 이름을 지은 사람들의 마음을 추론해 쓰세요.","answer_guide":{"answer":"예: ‘말모이’에는 “말을 모아 놓았다.”라는 뜻이 담겨 있다. 한자 대신 쉬운 우리말로 이름을 지은 것을 보면, 흩어진 우리말을 하나하나 모아 지키고 싶은 마음이 컸을 것이다.","scoring_points":["‘말모이’의 뜻을 바르게 썼는가","이름을 지은 사람들의 마음을 추론했는가","추론의 근거를 글에서 찾았는가"]},"explanation":["사전의 이름을 정한 부분을 다시 읽어요.","주시경이 우리글의 이름이 한자인 것을 싫어한 일도 떠올려요.","이름에 담긴 마음을 근거와 함께 써요."],"asset":{"type":"passage","lines":["(간추림) 1908년 주시경은 ‘국어연구학회’를 만들어 제자들과 사전을 만들기 시작했다.","사전의 이름은 “말을 모아 놓았다.”라는 뜻에서 ‘말모이’라 정했다.","(간추림) 1914년 원고를 가지고 외국으로 나갈 계획이었지만 그 전에 생을 마쳤다.","(간추림) 참여한 사람들도 떠나가 『말모이』는 빛을 보지 못하고 묻혔다."],"title":"「큰사전이 필요하다」 『말모이』 — 『국어』 196~197쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_kor_u4_review_d#25','kor',6,2,'u4','','tb_g6_2_kor_u4_review_d','unit_review','K6-2-u4-C13',4,'essay','teacher','표준어와 방언이 각각 하는 일을 쓰고, 방언을 소중히 여겨야 하는 까닭을 「우리말의 보물을 찾아서, ‘시골말 캐기’」의 내용과 이어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u4-C13","difficulty":4,"kind":"essay","stem":"표준어와 방언이 각각 하는 일을 쓰고, 방언을 소중히 여겨야 하는 까닭을 「우리말의 보물을 찾아서, ‘시골말 캐기’」의 내용과 이어 쓰세요.","answer_guide":{"answer":"예: 표준어는 우리나라 사람들이 공통으로 쓰도록 정한 말이라 어디에 사는 사람이든 서로 통하게 해 준다. 방언은 그 지역의 개성과 특성을 담고 있다. 학자들이 방언도 우리 민족의 소중한 보물이라고 여겨 『큰사전』에 모았듯이 방언도 아끼고 존중해야 한다.","scoring_points":["표준어가 하는 일을 썼는가","방언이 하는 일을 썼는가","방언을 소중히 여겨야 하는 까닭을 글과 이어 썼는가"]},"explanation":["표준어와 방언의 뜻을 먼저 떠올려요.","시골말 캐기에서 학자들이 방언을 어떻게 여겼는지 찾아요.","두 말 모두 소중한 우리말이에요."],"asset":{"type":"passage","lines":["(간추림) 사전을 만들려고 전국의 우리말을 모으던 시절, 학자들은 ‘시골말 캐기’를 펼쳤다.","(간추림) 구멍 대신 구먹·구명·구녕·구무, 부추 대신 세우리·정구지 같은 말을 모았다.","(간추림) 방학을 맞은 전국의 학생들이 고향에서 실제 쓰는 말을 종이에 써 보냈다.","(간추림) 학자들은 각 지역의 개성이 담긴 방언도 우리 민족의 소중한 보물이라고 생각했다.","(간추림) 모인 수많은 말은 『큰사전』을 만드는 든든한 뿌리가 되었다."],"title":"「우리말의 보물을 찾아서, ‘시골말 캐기’」 — 『국어』 204쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
